# ---------------- protobuf / 帧 ----------------
def read_varint(b, o):
    v = 0; s = 0
    while True:
        if o >= len(b):
            raise ValueError('trunc')
        c = b[o]; o += 1
        v |= (c & 0x7f) << s; s += 7
        if c < 0x80:
            return v, o


def write_varint(v):
    out = bytearray()
    while True:
        x = v & 0x7f
        v >>= 7
        if v:
            out.append(x | 0x80)
        else:
            out.append(x)
            return bytes(out)


def _pb_tag(field, wire=0):
    """构造 protobuf tag 字节：tag = (field << 3) | wire

    手写 tag 很容易数错 —— 比如字段 2 是 0x10、字段 16 是 0x80 0x01。
    第一版就用 b'\\x10' 拼错了字段语义，所以这里统一走函数，
    让它只可能在"传错字段号"上出错，不会在"数错移位"上出错。
    """
    return write_varint((int(field) << 3) | int(wire))


def dump_proto(b, ind='', depth=0, out=None):
    try:
        return _dump(b, ind, depth, out)
    except Exception as e:
        return ['<%s>' % e]


def _dump(b, ind='', depth=0, out=None):
    if out is None:
        out = []
    o = 0
    while o < len(b):
        try:
            key, o = read_varint(b, o)
        except Exception:
            out.append(ind + '…'); return out
        fn, wt = key >> 3, key & 7
        if wt == 0:
            try:
                v, o = read_varint(b, o)
            except Exception:
                out.append(ind + '…'); return out
            out.append('%s#%d = %d' % (ind, fn, v))
        elif wt == 2:
            try:
                ln, o = read_varint(b, o)
            except Exception:
                out.append(ind + '…'); return out
            raw = b[o:o + ln]; o += ln
            try:
                t = raw.decode('utf-8')
                printable = t and all(c.isprintable() or c in '\r\n\t' for c in t)
            except Exception:
                printable = False
            if printable:
                out.append('%s#%d = %r' % (ind, fn, t))
            else:
                out.append('%s#%d = bytes[%d] %s' % (ind, fn, ln, raw[:20].hex()))
                if depth < 3 and ln:
                    sub = _dump(raw, ind + '  ', depth + 1, [])
                    if sub and not any('…' in x for x in sub):
                        out += sub
        elif wt == 5:
            out.append('%s#%d = fixed32 %s' % (ind, fn, b[o:o + 4].hex())); o += 4
        elif wt == 1:
            out.append('%s#%d = fixed64 %s' % (ind, fn, b[o:o + 8].hex())); o += 8
        else:
            out.append('%s<wt%d>' % (ind, wt)); break
    return out


def lz4_block_decompress(data, expected):
    """LZ4 block 解压（游戏大报文用）"""
    out = bytearray()
    off = 0
    n = len(data)
    while off < n:
        token = data[off]; off += 1
        lit = token >> 4
        if lit == 15:
            while True:
                if off >= n:
                    raise ValueError('lz4 lit len trunc')
                e = data[off]; off += 1
                lit += e
                if e != 255:
                    break
        if off + lit > n:
            raise ValueError('lz4 lit data trunc')
        out += data[off:off + lit]
        off += lit
        if off >= n:
            break
        if off + 2 > n:
            raise ValueError('lz4 match off trunc')
        moff = data[off] | (data[off + 1] << 8)
        off += 2
        if moff == 0 or moff > len(out):
            raise ValueError('lz4 bad match offset %d' % moff)
        mlen = (token & 0x0f) + 4
        if (token & 0x0f) == 15:
            while True:
                if off >= n:
                    raise ValueError('lz4 match len trunc')
                e = data[off]; off += 1
                mlen += e
                if e != 255:
                    break
        for _ in range(mlen):
            out.append(out[-moff])
    if expected and len(out) != expected:
        raise ValueError('lz4 size mismatch %d != %d' % (len(out), expected))
    return bytes(out)


def build_frame(msg_type, payload=b'', route='00000000'):
    nb = msg_type.encode()
    body = bytes([2]) + bytes.fromhex(route) + bytes([len(nb)]) + nb + bytes([0]) + payload
    return len(body).to_bytes(4, 'big') + body


def parse_frame(b):
    if len(b) < 12:
        return None
    if int.from_bytes(b[:4], 'big') != len(b) - 4 or b[4] != 2:
        return None
    mtl = b[9]
    if mtl == 0 or 10 + mtl >= len(b):
        return None
    comp = b[10 + mtl]
    payload = b[11 + mtl:]
    if comp == 1 and len(payload) >= 4:
        try:
            exp = int.from_bytes(payload[:4], 'big')
            payload = lz4_block_decompress(payload[4:], exp)
        except Exception:
            pass
    return {'route': b[5:9].hex(), 'type': b[10:10 + mtl].decode('ascii', 'replace'),
            'compression': comp, 'payload': payload}


def ws_send(sock, data, opcode=0x2):
    mask = os.urandom(4)
    n = len(data)
    h = bytearray([0x80 | opcode])
    if n < 126:
        h.append(0x80 | n)
    elif n < 65536:
        h.append(0x80 | 126); h += struct.pack('>H', n)
    else:
        h.append(0x80 | 127); h += struct.pack('>Q', n)
    h += mask
    h += bytes(c ^ mask[i % 4] for i, c in enumerate(data))
    sock.sendall(bytes(h))


def _ws_read_more(sock, want, tries=3):
    """把剩余的 want 字节读满（TCP 会把一帧拆成多段）。

    只给有限的几次重试：正常情况第一段之后剩下的会立刻到；
    真超时就返回 None，让上层按"本次没数据"处理，而不是死等。
    """
    buf = b''
    while len(buf) < want:
        try:
            chunk = sock.recv(min(65536, want - len(buf)))
        except socket.timeout:
            tries -= 1
            if tries <= 0:
                return None
            continue
        except (OSError, ValueError):
            return None
        if not chunk:
            return None
        buf += chunk
    return buf


def ws_recv(sock, timeout):
    sock.settimeout(timeout)
    try:
        d = sock.recv(65536)
    except socket.timeout:
        return None
    if not d:
        raise ConnectionError('closed')
    if len(d) < 2:
        return None
    op = d[0] & 0x0f
    fin = bool(d[0] & 0x80)
    ln = d[1] & 0x7f
    off = 2
    if ln == 126:
        if len(d) < 4:
            more = _ws_read_more(sock, 4 - len(d))
            if more is None:
                return None
            d += more
        ln = struct.unpack('>H', d[2:4])[0]; off = 4
    elif ln == 127:
        if len(d) < 10:
            more = _ws_read_more(sock, 10 - len(d))
            if more is None:
                return None
            d += more
        ln = struct.unpack('>Q', d[2:10])[0]; off = 10
    # ★ 必须把整帧读完再返回。
    #   以前这里只 recv 一次就按 ln 切片，只要服务端把这一帧拆成两段 TCP
    #   （背包 AllItemResponse、建筑全量表这类大包常被拆），拿到的就是半截；
    #   parse_frame 的前 4 字节长度校验（== len-4）过不了 → 整帧被静默丢弃。
    #   线上表现：某个号背包/库存一直是空的（只有资源那 4 项），
    #   工厂因此以为"所有材料都是 0"、居民订单也永远判不准。
    if len(d) < off + ln:
        more = _ws_read_more(sock, off + ln - len(d))
        if more is None:
            return None
        d += more
    if op == 0x8:
        # 关闭帧里常带关闭码/原因。以前直接吞掉，只能看到一句
        # "server close"，无法区分主动下线、被顶号和服务端维护。
        code = 0
        reason = ''
        try:
            close_raw = d[off:off + ln]
            if len(close_raw) >= 2:
                code = struct.unpack('>H', close_raw[:2])[0]
            if len(close_raw) > 2:
                reason = close_raw[2:].decode('utf-8', 'replace')
        except Exception:
            pass
        detail = 'server close'
        if code:
            detail += ' code=%d' % code
        if reason:
            detail += ' reason=%s' % reason
        raise ConnectionError(detail)
    if op in (0x9, 0xA):
        return None
    payload = d[off:off + ln]
    # 分片消息（FIN=0）：把后面的 continuation 帧接上，
    # 否则大包一样只拿到第一片。
    while not fin:
        head = _ws_read_more(sock, 2)
        if head is None:
            return None
        op2 = head[0] & 0x0f
        fin = bool(head[0] & 0x80)
        l2 = head[1] & 0x7f
        if l2 == 126:
            ext = _ws_read_more(sock, 2)
            if ext is None:
                return None
            l2 = struct.unpack('>H', ext)[0]
        elif l2 == 127:
            ext = _ws_read_more(sock, 8)
            if ext is None:
                return None
            l2 = struct.unpack('>Q', ext)[0]
        # 服务端发来的帧不带掩码，表头之后就是净荷（2/4/10 字节表头已消费）。
        piece = _ws_read_more(sock, l2) if l2 else b''
        if piece is None:
            return None
        if op2 == 0x8:
            break
        payload += piece
    return payload



