def frame_with_world(hexstr, wid):
    """把登录帧的 #8(worldId) 设成指定值（不影响签名）"""
    if not wid:
        return hexstr
    b = bytes.fromhex(hexstr)
    mtl = b[9]
    head = b[:11 + mtl]              # 帧头 + 类型 + 压缩标志
    pl = b[11 + mtl:]                # 载荷
    # 剥掉原有 #8
    out = bytearray()
    o = 0
    while o < len(pl):
        key, o2 = read_varint(pl, o)
        fn, wt = key >> 3, key & 7
        if wt == 0:
            _, o3 = read_varint(pl, o2)
            if fn != 8:
                out += pl[o:o3]
            o = o3
        elif wt == 2:
            ln, o3 = read_varint(pl, o2)
            if fn != 8:
                out += pl[o:o3 + ln]
            o = o3 + ln
        else:
            out += pl[o:]
            break
    out += b'\x40' + write_varint(wid)     # field 8, varint
    body = bytearray(head[4:]) + out
    return (len(body).to_bytes(4, 'big') + bytes(body)).hex()


# ---------------- 反应式任务（收到推送就行动）----------------
def _ex_floaters(payload, fields=(1, 2)):
    """提取 DispWaterFloater.floaterId。

    客户端有两个入口都会带漂浮物：
      - SCRandomWaterFloaters: repeated floater = field 1
      - OnWaterResponse:       repeated floater = field 2
    DispWaterFloater 的 floaterId 在 field 1；部分线上回包会把它放到
    field 2，所以字段缺失时取首个可打印字符串作为兼容。
    """
    names = []
    seen = set()

    def add(name):
        if not name or name in seen:
            return
        seen.add(name)
        names.append(name)

    def read_item(raw):
        strings = {}
        oo = 0
        while oo < len(raw):
            try:
                k2, oo = read_varint(raw, oo)
            except Exception:
                break
            f2, w2 = k2 >> 3, k2 & 7
            if w2 == 2:
                l2, oo = read_varint(raw, oo)
                r2 = raw[oo:oo + l2]; oo += l2
                try:
                    val = r2.decode('utf-8')
                except Exception:
                    continue
                if val and all(c.isprintable() for c in val):
                    strings[f2] = val
            elif w2 == 0:
                _, oo = read_varint(raw, oo)
            else:
                break
        if 1 in strings:
            add(strings[1])
        elif 2 in strings:
            add(strings[2])
        else:
            for val in strings.values():
                add(val)
                break

    o = 0
    while o < len(payload):
        try:
            key, o = read_varint(payload, o)
        except Exception:
            break
        fn, wt = key >> 3, key & 7
        if wt == 2:
            ln, o = read_varint(payload, o)
            raw = payload[o:o + ln]; o += ln
            if fn in fields:
                read_item(raw)
        elif wt == 0:
            _, o = read_varint(payload, o)
        else:
            break
    return names


def _pickup_floater_payload(floater_ids):
    """PickUpFloaterRequest {#2 repeated: floaterId:string}"""
    out = bytearray()
    for name in floater_ids or ():
        raw = str(name).encode('utf-8')
        out += _pb_tag(2, 2) + write_varint(len(raw)) + raw
    return bytes(out)


def _ex_all_buildings(payload):
    """从岛屿/建筑大报文里批量提取
    (名字, 等级, 开工时间, 完工时间, 生产槽, 装备排产)
    """
    out = []
    o = 0
    while o < len(payload):
        try:
            key, o = read_varint(payload, o)
        except Exception:
            break
        fn, wt = key >> 3, key & 7
        if wt == 2:
            ln, o = read_varint(payload, o)
            raw = payload[o:o + ln]; o += ln
            if fn == 1 and len(raw) > 4:
                name, state, start, finish, slots = None, None, 0, 0, []
                em = None
                # DispWaterBuilding 的海兽字段（客户端 bundle 里的生成式
                # 编解码器为准）：#15 = petBreed（培育队列/成熟海兽），
                # #16 = petServe（战备室里随队的那只海兽，其 #1 = petUid）。
                petuid = None
                petbreed = None
                oo = 0
                while oo < len(raw):
                    try:
                        k2, oo = read_varint(raw, oo)
                    except Exception:
                        break
                    f2, w2 = k2 >> 3, k2 & 7
                    if w2 == 2:
                        l2, oo = read_varint(raw, oo)
                        r2 = raw[oo:oo + l2]; oo += l2
                        if f2 == 1:
                            try:
                                t2 = r2.decode('utf-8')
                                if all(c.isprintable() for c in t2):
                                    name = t2
                            except Exception:
                                pass
                    elif w2 == 0:
                        v2, oo = read_varint(raw, oo)
                        if f2 == 2:
                            state = v2
                        elif f2 == 10:
                            start = v2
                        elif f2 == 11:
                            finish = v2
                    else:
                        break
                    if w2 == 2 and f2 == 8:
                        # DispWaterBuilding.#8 = equipMaking（装备厂的排产任务）。
                        # 结构 DispEquipMaking{ #1 makeId:int32, #2 finishTime:int32,
                        #   #3 equipId:string, #4 star:int32 }。以前只认 #7 factory，
                        # 装备厂的排产被整个丢掉，机器人以为它闲着，每轮重复发同一条
                        # MakeEquipRequest，服务端一直回 producing。
                        try:
                            _em = {}
                            o3 = 0
                            while o3 < len(r2):
                                k3, o4 = read_varint(r2, o3)
                                f3, w3 = k3 >> 3, k3 & 7
                                if w3 == 2:
                                    l3, o5 = read_varint(r2, o4)
                                    v3 = r2[o5:o5 + l3]; o3 = o5 + l3
                                    if f3 == 3:
                                        try:
                                            _em['equipId'] = v3.decode('utf-8')
                                        except Exception:
                                            _em['equipId'] = ''
                                elif w3 == 0:
                                    v3, o3 = read_varint(r2, o4)
                                    if f3 == 1:
                                        _em['makeId'] = v3
                                    elif f3 == 2:
                                        _em['finishTime'] = v3
                                    elif f3 == 4:
                                        _em['star'] = v3
                                else:
                                    break
                            if _em.get('makeId'):
                                em = _em
                        except Exception:
                            pass
                    if w2 == 2 and f2 == 7:
                        try:
                            o3 = 0
                            while o3 < len(r2):
                                k3, o4 = read_varint(r2, o3)
                                f3, w3 = k3 >> 3, k3 & 7
                                if w3 == 2:
                                    l3, o5 = read_varint(r2, o4)
                                    slot_raw = r2[o5:o5 + l3]; o3 = o5 + l3
                                    if f3 != 1:
                                        # DispFactory 的 #1 才是 factoryQ，
                                        # #2 是 finishedProducts。两者结构不同，
                                        # 以前一把塞进来会把成品误当生产槽位。
                                        continue
                                    d = {}
                                    o6 = 0
                                    while o6 < len(slot_raw):
                                        k4, o7 = read_varint(slot_raw, o6)
                                        f4, w4 = k4 >> 3, k4 & 7
                                        if w4 == 2:
                                            l4, o8 = read_varint(slot_raw, o7)
                                            v4 = slot_raw[o8:o8 + l4]; o6 = o8 + l4
                                            try:
                                                d[str(f4)] = v4.decode('utf-8')
                                            except Exception:
                                                d[str(f4)] = v4[:8].hex()
                                        elif w4 == 0:
                                            v4, o6 = read_varint(slot_raw, o7)
                                            d[str(f4)] = v4
                                        else:
                                            break
                                    if d:
                                        slots.append(d)
                                elif w3 == 0:
                                    _, o3 = read_varint(r2, o4)
                                else:
                                    break
                        except Exception:
                            pass
                    if w2 == 2 and f2 == 16:
                        try:
                            o3 = 0
                            while o3 < len(r2):
                                k3, o4 = read_varint(r2, o3)
                                f3, w3 = k3 >> 3, k3 & 7
                                if w3 == 0:
                                    v3, o3 = read_varint(r2, o4)
                                    if f3 == 1:
                                        petuid = v3
                                elif w3 == 2:
                                    l3, o5 = read_varint(r2, o4)
                                    o3 = o5 + l3
                                else:
                                    break
                        except Exception:
                            pass
                    if w2 == 2 and f2 == 15:
                        petbreed = _ex_pet_breed(r2)
                if name and state is not None:
                    out.append((name, state, start, finish, slots, em,
                                petuid, petbreed))
        elif wt == 0:
            _, o = read_varint(payload, o)
        else:
            break
    return out


def _ex_pet_record(raw):
    """DispPet / SCPetsUpdate 单条记录 -> dict。

    wire 实测（2026-10-10，线上 AllPetResponse 1942 字节）：
      #1 uid:int64（实例 ID），#2 petId:str（"紫宠物2"/"蓝宠物1"，前缀颜色=品质），
      #3 level:int32，#4 star:int32，#7 grade:int32，#10 extAttrIdx:int32。
      #5/#6/#8 是属性/技能明细，这里用不上，跳过。
    """
    rec = {'uid': 0, 'petId': '', 'level': 0, 'star': 0, 'grade': 0,
           'extAttrIdx': 0}
    o = 0
    while o < len(raw):
        try:
            k, o = read_varint(raw, o)
        except Exception:
            break
        fn, wt = k >> 3, k & 7
        if wt == 2:
            ln, o = read_varint(raw, o)
            v = raw[o:o + ln]; o += ln
            if fn == 2:
                try:
                    rec['petId'] = v.decode('utf-8')
                except Exception:
                    pass
        elif wt == 0:
            v, o = read_varint(raw, o)
            if fn == 1:
                rec['uid'] = v
            elif fn == 3:
                rec['level'] = v
            elif fn == 4:
                rec['star'] = v
            elif fn == 7:
                rec['grade'] = v
            elif fn == 10:
                rec['extAttrIdx'] = v
        else:
            break
    return rec


def _ex_pets(payload):
    """AllPetResponse（repeated #1 包裹）或 SCPetsUpdate（单条）-> list[dict]。

    AllPetResponse 是 repeated DispPet pets = 1：每只海兽被包在 #1 里。
    SCPetsUpdate 是单只推送，直接解顶层字段。两种都兼容：先按包裹解，
    解不出 uid 再退回按单条解。
    """
    out = []
    o = 0
    while o < len(payload):
        try:
            k, o = read_varint(payload, o)
        except Exception:
            break
        fn, wt = k >> 3, k & 7
        if wt == 2:
            ln, o = read_varint(payload, o)
            raw = payload[o:o + ln]; o += ln
            if fn == 1:
                rec = _ex_pet_record(raw)
                if rec.get('uid'):
                    out.append(rec)
        elif wt == 0:
            _, o = read_varint(payload, o)
        else:
            break
    if out:
        return out
    rec = _ex_pet_record(payload)
    if rec.get('uid'):
        out.append(rec)
    return out


def _ex_pet_breed(raw):
    """DispWaterBuilding.#15 = PetBreedBuildingInfo -> dict。

    PetBreedBuildingInfo{1:repeated DispPetBreedJob breedQ,
                        2:repeated MaturePet maturePets,
                        3:maxQLength}
    DispPetBreedJob{1:idx, 2:petId, 3:finishTime,
                    4:repeated feedRequirements(DisplayAsset),
                    5:startTime, 6:star}
    MaturePet{1:petId, 2:star}
    字段号来自客户端 bundle.04ae2.js 的生成式编解码器；proto_defs.json
    里那几条是推测的，对不上。
    """
    out = {'jobs': [], 'mature': [], 'maxQ': 0}
    o = 0
    while o < len(raw):
        try:
            k, o = read_varint(raw, o)
        except Exception:
            break
        fn, wt = k >> 3, k & 7
        if wt == 2:
            ln, o = read_varint(raw, o)
            sub = raw[o:o + ln]; o += ln
            if fn == 1:
                job = {'idx': 0, 'petId': '', 'finish': 0, 'start': 0,
                       'star': 0, 'feed': []}
                oo = 0
                while oo < len(sub):
                    try:
                        k2, oo = read_varint(sub, oo)
                    except Exception:
                        break
                    f2, w2 = k2 >> 3, k2 & 7
                    if w2 == 0:
                        v2, oo = read_varint(sub, oo)
                        if f2 == 1:
                            job['idx'] = v2
                        elif f2 == 3:
                            job['finish'] = v2
                        elif f2 == 5:
                            job['start'] = v2
                        elif f2 == 6:
                            job['star'] = v2
                    elif w2 == 2:
                        l2, o2 = read_varint(sub, oo)
                        v2 = sub[o2:o2 + l2]; oo = o2 + l2
                        if f2 == 2:
                            try:
                                job['petId'] = v2.decode('utf-8')
                            except Exception:
                                pass
                        elif f2 == 4:
                            # DisplayAsset{1:id:string, 2:num:int32}
                            _id, _num, o3 = '', 0, 0
                            while o3 < len(v2):
                                try:
                                    k3, o3 = read_varint(v2, o3)
                                except Exception:
                                    break
                                f3, w3 = k3 >> 3, k3 & 7
                                if w3 == 0:
                                    v3, o3 = read_varint(v2, o3)
                                    if f3 == 2:
                                        _num = v3
                                elif w3 == 2:
                                    l3, o4 = read_varint(v2, o3)
                                    v3 = v2[o4:o4 + l3]; o3 = o4 + l3
                                    if f3 == 1:
                                        try:
                                            _id = v3.decode('utf-8')
                                        except Exception:
                                            pass
                                else:
                                    break
                            if _id:
                                job['feed'].append([_id, _num])
                    else:
                        break
                if job['idx'] or job['petId']:
                    out['jobs'].append(job)
            elif fn == 2:
                mp = {'petId': '', 'star': 0}
                oo = 0
                while oo < len(sub):
                    try:
                        k2, oo = read_varint(sub, oo)
                    except Exception:
                        break
                    f2, w2 = k2 >> 3, k2 & 7
                    if w2 == 0:
                        v2, oo = read_varint(sub, oo)
                        if f2 == 2:
                            mp['star'] = v2
                    elif w2 == 2:
                        l2, o2 = read_varint(sub, oo)
                        v2 = sub[o2:o2 + l2]; oo = o2 + l2
                        if f2 == 1:
                            try:
                                mp['petId'] = v2.decode('utf-8')
                            except Exception:
                                pass
                    else:
                        break
                if mp['petId']:
                    out['mature'].append(mp)
        elif wt == 0:
            v, o = read_varint(raw, o)
            if fn == 3:
                out['maxQ'] = v
        else:
            break
    return out


def _ex_choice(payload):
    """SCChoiceEventUpdate -> 事件 uid"""
    o = 0
    while o < len(payload):
        try:
            key, o = read_varint(payload, o)
        except Exception:
            break
        fn, wt = key >> 3, key & 7
        if wt == 2:
            ln, o = read_varint(payload, o)
            raw = payload[o:o + ln]; o += ln
            if fn == 1:
                try:
                    v, _ = read_varint(raw, 0)
                    return v
                except Exception:
                    pass
        elif wt == 0:
            _, o = read_varint(payload, o)
        else:
            break
    return None


def _ex_building(payload):
    """SCUpdateWaterBuilding -> (建筑名, 等级, 开工时间, 完工时间)"""
    o = 0
    while o < len(payload):
        try:
            key, o = read_varint(payload, o)
        except Exception:
            break
        fn, wt = key >> 3, key & 7
        if wt == 2:
            ln, o = read_varint(payload, o)
            raw = payload[o:o + ln]; o += ln
            if fn == 1:
                name, state, start, finish = None, None, 0, 0
                oo = 0
                while oo < len(raw):
                    try:
                        k2, oo = read_varint(raw, oo)
                    except Exception:
                        break
                    f2, w2 = k2 >> 3, k2 & 7
                    if w2 == 2:
                        l2, oo = read_varint(raw, oo)
                        r2 = raw[oo:oo + l2]; oo += l2
                        if f2 == 1:
                            try:
                                name = r2.decode('utf-8')
                            except Exception:
                                pass
                    elif w2 == 0:
                        v2, oo = read_varint(raw, oo)
                        if f2 == 2:
                            state = v2
                        elif f2 == 10:
                            start = v2
                        elif f2 == 11:
                            finish = v2
                    else:
                        break
                if name:
                    return name, state, start, finish
        elif wt == 0:
            _, o = read_varint(payload, o)
        else:
            break
    return None, None, 0, 0


def _build_collect(name):
    b = name.encode()
    return b'\x0a' + write_varint(len(b)) + b


def _equip_make_payload(building_id, make_id, universal=False):
    """MakeEquipRequest{ #1 buildingId:string, #2 makeId:int32, #3 universal:bool }

    装备厂排产：buildingId 是建筑名（如 1装备厂），makeId 是配方号
    （1001/1002/1003 …），universal 表示是否用通用材料。三个字段服务端
    都当 required，缺一个整条被丢。
    """
    b = str(building_id).encode('utf-8')
    out = _pb_tag(1, 2) + write_varint(len(b)) + b
    out += _pb_tag(2, 0) + write_varint(int(make_id))
    out += _pb_tag(3, 0) + (b'\x01' if universal else b'\x00')
    return bytes(out)


def _pb2(s1, s2=None, fn1=1, fn2=2):
    """构造 {#fn1: s1} 或 {#fn1: s1, #fn2: s2}"""
    out = b''
    for fn, v in ((fn1, s1), (fn2, s2)):
        if v is None:
            continue
        b = v.encode('utf-8')
        out += bytes([(fn << 3) | 2]) + write_varint(len(b)) + b
    return out


def _farm_plant_payload(name, product):
    """FarmPlantRequest{args:[PlantArg{buildingId, productId}]} 的载荷。

    客户端原文（proto-bundle.js）：
        FarmPlantRequest.encode: 每个 arg 走 uint32(10).fork() ... ldelim()
        PlantArg.encode:         #1 = buildingId, #2 = productId
    也就是 **外层 #1 是嵌套的 PlantArg 消息**，不是 buildingId 字符串。
    以前直接发 _pb2(name, product)（顶层 #1=建筑名）：服务端把这段字符串
    当半个 PlantArg 解，解不动就整条丢弃 —— 请求静默失败，种子不减、
    作物不长。线上表现：农田天天"播种"却永远收不到东西，小麦卡在 1，
    于是要小麦的面包永远排不上产。
    """
    inner = _pb2(name, product, 1, 2)          # PlantArg
    return b'\x0a' + write_varint(len(inner)) + inner


# ---------------- 英雄：协议载荷构造 ----------------
#
# 载荷格式全部来自客户端代码 7ccc050.ttpkg 里各按钮的点击处理，
# 再用 big.jsonl 的真实帧交叉验证过（HeroStarUpRequest / HeroPreviewRequest
# 已有真实帧，逐字节一致）。
#
# 重要：服务端这个版本里 heroId 字段是**字符串**（英雄名），不是数字 ID。
# 抓包实证：
#   HeroStarUpRequest  → 0a06 e69db0e6a3ae 1000
#                         #1(字符串)="棺材"   #2=0
#   HeroPreviewRequest → 0a06 e69db0e6a3ae 1001
#                         #1(字符串)="棺材"   #2=1
# 客户端 JS 里写的是 {heroId: s}，但 s 来自 UI 的 itemData，
# 序列化出去就是名字。别自作聪明改成数字 ID —— 会全部失败。

# 招募方式枚举 —— 从客户端 schema 里**直接读到**的原文（不再是猜的）：
#   s.RecruitWay=function(){
#       var e={}, t=Object.create(e);
#       return t[e[1]="RECRUIT_FREE"]=1,
#              t[e[2]="RECRUIT_SINGLE"]=2,
#              t[e[3]="RECRUIT_BATCH_10"]=3,
#              t[e[4]="RECRUIT_BATCH_50"]=4,
#              t[e[5]="RECRUIT_ADV"]=5, t }()
#
# ★ 之前一版把"免费招募"写成 way=0 是错的 —— 枚举里根本没有 0，
#   免费是 1（RECRUIT_FREE），而且 RecruitStartRequest.way 是
#   **required** 字段，服务端默认值也是 1。发 0 会被当成非法枚举。
#
# 注意：这一组是**英雄招募**的枚举（AntiqueRecruitType 是另一套，
# 1=RECRUIT_ANTIQUE、2=RECRUIT_DIVE，用于古董/潜水）。
RECRUIT_WAYS = {
    '免费': 1,       # RECRUIT_FREE      —— 不消耗资源
    '单抽': 2,       # RECRUIT_SINGLE    —— 烧 1 张券
    '十连': 3,       # RECRUIT_BATCH_10  —— 烧 10 张券
    '五十连': 4,     # RECRUIT_BATCH_50  —— 烧 50 张券
    '高级': 5,       # RECRUIT_ADV       —— 高级池
}
RECRUIT_FREE = RECRUIT_WAYS['免费']      # = 1


def _way_name(way):
    """数字 way -> 中文名，日志里给人看的"""
    for k, v in RECRUIT_WAYS.items():
        if v == int(way):
            return k
    return '未知(%d)' % int(way)


def _hero_payload(name):
    """{#1: 英雄名} —— 大部分英雄操作的最小载荷"""
    b = name.encode('utf-8')
    return _pb_tag(1, 2) + write_varint(len(b)) + b


def _hero_skill_payload(name, skill_idx):
    """{#1: 英雄名, #2: skillIdx}

    客户端原文：`{heroId: this._hero.heroId, skillIdx: t}`，
    其中 `t = this._skillIndex + 1` —— UI 从 0 数、协议从 1 起。

    schema 核对（23f2ffc.ttpkg）：
      HeroSkillLevelUpRequest.decode → case 1: heroId=e.string()
                                       case 2: skillIdx=e.int32()
    """
    return _hero_payload(name) + _pb_tag(2, 0) + write_varint(int(skill_idx))


def _hero_exclusive_star_payload(name, universal=False):
    """{#1: 英雄名, #2: universal}

    schema 核对：HeroExclusiveStarUpRequest.decode
      case 1: heroId=e.string() | case 2: universal=e.bool()
    universal=1 表示允许用万能碎片补差（更激进，会动万能碎片）。
    """
    return _hero_payload(name) + _pb_tag(2, 0) + write_varint(1 if universal else 0)


def _hero_exclusive_level_payload(name):
    """{#1: 英雄名} —— HeroExclusiveLevelUpRequest（专武升级）

    schema 核对：该协议 decode 只读 case 1: heroId。
    虽然 encode 里还写了 universal/skinId，但那是别处复用（同一段代码
    里紧跟的 HeroExclusiveStarUpRequest）。专武升级只传英雄名。
    """
    return _hero_payload(name)


def _hero_star_payload(name, universal=0):
    """{#1: 英雄名, #2: universal} —— 与 HeroStarUpRequest 实帧一致

    实帧：0a06 e69db0e6a3ae 1000  →  #1="杰森"  #2=0
    """
    return _hero_payload(name) + _pb_tag(2, 0) + write_varint(int(universal))


def _recruit_payload(way):
    """{#2: way} —— RecruitStartRequest

    ★ 字段号是 2，不是 1！从客户端 protobuf schema 直接读出来的原文：
        s.RecruitStartRequest=...e.prototype.way=1,
        e.encode=function(e,t){ return t.uint32(16).int32(e.way), t }
        e.decode= ... if(s>>>3==2) a.way=e.int32()
      `uint32(16) >> 3 == 2`。way 还是 **required** 字段。

    第一版写成了 #1（b'\\x08'），字段号直接错位 —— 服务端会当成
    "缺 required 字段 way" 直接拒掉。这就是为什么必须对着 schema 核。

    另外注意默认值是 1 不是 0：真正的"免费招募"是哪一档需要在游戏里确认，
    所以 self.recruit_way 保持可配置，不硬编码。
    """
    return _pb_tag(2, 0) + write_varint(int(way))


def _enhance_equip_payload(uid):
    """{#1: uid:int64} —— EnhanceEquipRequest

    schema 核对：
      e.prototype.uid = Long.fromBits(0,0,false)
      e.encode = t.uint32(8).int64(e.uid)
      e.decode → if(s>>>3==1) a.uid=e.int64()  且 uid 是 required
    """
    return _pb_tag(1, 0) + write_varint(int(uid))


def _enhance_badge_payload(uid, decompose_uids=None, exp_num=0):
    """{#1: uid:int64, #2: repeated decomposeUid:int64, #3: expItemNum:int32}

    客户端原文：
      `{uid:this._heroBadge.uid, decomposeUid:e, expItemNum:this._usedExpItemNum}`

    schema 核对：EnhanceBadgeRequest.decode
      case 1: uid=e.int64() | case 3: expItemNum=e.int32()
    （encode 里还有 #16 的 starItemNum，是同一个类的另一个用途，不传。）

    分解 uid 列表可选：不分解装备时只有 uid。
    注意 decomposeUid 是 **int64**，不是 int32 —— 用 varint 直传，
    只要 uid 数值在 int64 范围内就没差别。
    """
    out = _pb_tag(1, 0) + write_varint(int(uid))
    for u in (decompose_uids or []):
        out += _pb_tag(2, 0) + write_varint(int(u))
    if exp_num:
        out += _pb_tag(3, 0) + write_varint(int(exp_num))
    return out


def _frag_exchange_payload(name, frag_item_id, num):
    """{#1: 英雄名, #2: 碎片物品ID, #3: 数量} —— 碎片兑换

    客户端原文：
      `{heroId:this._heroId, fragItemId:this._fragItemId, num:this._exchangeFragNum}`
    这个协议名在客户端里没找到独立的 s.HeroFragExchangeRequest 定义，
    所以保持"构造得出但默认不发"，等线上确认协议名再用。
    """
    out = _hero_payload(name)
    out += _pb_tag(2, 0) + write_varint(int(frag_item_id))
    out += _pb_tag(3, 0) + write_varint(int(num))
    return out


def _auto_appoint_payload(pos_ids):
    """{#1: repeated posId:int32} —— AutoAppointRequest

    客户端原文：
      `var e=[]; ... e.push(l.posId); y("AutoAppointRequest",{posId:e})`
    也就是把所有槽位的 posId 一次性传上去，服务端自己挑人补位。

    schema 核对（逐字）：
      s.AutoAppointRequest = function(){ ... if(this.posId=[],e) ... }
      e.prototype.posId = o.emptyArray
      e.encode = for(var n=0;n<e.posId.length;++n) t.uint32(8).int32(e.posId[n])
      e.decode → if(a>>>3==1) ... o.posId.push(e.int32())
    `uint32(8) >> 3 == 1` → 确认字段号是 1。
    """
    out = b''
    for p in (pos_ids or []):
        out += _pb_tag(1, 0) + write_varint(int(p))
    return out


# ============================================================================
# 新玩法模块的载荷构造（挂机 / 试炼副本 / 积分赛 / 远征副本）
# ============================================================================
#
# ★ 这一批的逆向结论有一个**根本性纠正**，写在最前面，因为它推翻了之前的假设：
#
#   之前我以为"协议名 → 编号"存在一张注册表，route 编号是数组下标，
#   还从 PULL_REQUESTS 的连续编号（0x1ea0~0x1ecc）反推出"中间缺口=未拉协议"。
#   **这个方向是错的。**
#
#   从 23f2ffc.ttpkg 里读到 ProtocolCodec.encode 的真实实现（逐字节）：
#
#       c = 4
#       s.setInt8 (c, 2);            c += 1   // version = 2
#       s.setInt32(c, t);            c += 4   // t = sendSeqNo（自增序号）
#       s.setInt8 (c, r.length);     c += 1   // 协议**名字长度**
#       // 逐字节写入 r（协议名字符串）
#       s.setInt8 (c + r.length, 0);          // 名字以 \0 收尾
#
#   而 Request 类就是：`function(name, body){this.name=name; this.body=body}`
#
#   → **帧头携带的是协议名字符串，route 只是同连接的请求序号。**
#     PULL_REQUESTS 里那串 00001ea0/00001ea1… 是**某一次抓包的自增 seqNo**，
#     不是"协议注册表下标"。所以我们**从来不需要** route 映射表。
#
#   线上实测验证（probe_live.py / probe_farm.py，2026-09-24）：
#     LeagueInfoRequest          → PromptResponse("feature locked")    ← 认得，未解锁
#     ExpeditionInfoRequest      → PromptResponse("feature locked")    ← 认得，未解锁
#     TrialRaidInfoRequest       → PromptResponse("Invalid request")   ← 认得，缺 raidId
#     SetAutoFarmingRequest      → PromptResponse("privilege locked")  ← 认得，特权未开
#     SetBuildingAutoWorkRequest → PromptResponse("building not found")← 认得，且解析出 buildingId
#
#   服务端**没有回 "Unknown message type"**，说明这些协议名都是有效的。
#   `building not found` 更是铁证：它意味着服务端成功解出了 #1 的字符串字段，
#   否则会回 `Invalid request`。→ 载荷结构确认无误。
#
# 所以这批协议可以直接用，唯一门槛是账号侧的功能解锁（等级/VIP/世界天数）。
# 全部按"能确认的才做"落地：结构确认了，就实现；解锁条件由服务端把关，
# 被拒时把服务端的英文文案原样记进日志，不假装成功。

# ---- 挂机自动化（主线闯关模块）----
# 客户端原文（7ccc050.ttpkg @ 2504043，FarmView._onBtnAuto）：
#   `if(g.isOpen("农田自动种植")){ var t=this._btn_auto.selected,
#      e=E("SetAutoFarmingRequest",{isOn:t}); c.instance.sendMessage(e, ...) }`
#   schema: SetAutoFarmingRequest{ #1: isOn:bool (required) }
# 线上实测：isOn=false → "privilege locked"（协议被认识，是特权门槛）
def _farm_auto_payload(is_on):
    return _pb_tag(1, 0) + write_varint(1 if is_on else 0)


# ---- 主线建造 / 挂机奖励 ----
# 客户端编码逐一核对（1.13.6 bundle）：
#   BuildBuildingRequest      {#1: buildingId:string}
#   UpgradeBuildingRequest    {#1: buildingId:string}
#   DrawAfkRewardRequest      {#1: useAdvCard:bool}
#   DrawAfkLevelRewardRequest {#1: level:int32}
#   UpgradeAfkLevelRequest    {#1: level:int32}
# 注意：客户端把 #1 当作“本次连升几级”（1/5/10），不是目标绝对等级。
# UpgradeAfkLevelResponse.level 才是升级后的绝对等级。
def _build_building_payload(building_id):
    return _build_collect(building_id)


# ---- 建筑加速（看广告 / 加速器 / 钻石）----
# 客户端 1.13.6 bundle.59dc0.js 逐字段核对（不是猜的）：
#   WatchAdvRequest { #1: type:int32, #2: id:int32 } —— 两个都是 required
#   SpeedUpUpgradeBuildingRequest { #1: buildingId:string,
#                                   #2: speedUp:SpeedUpCostParam }
#   SpeedUpCostParam { #1: type:int32, #2: useNum:int32 }
#   SpeedUpCost 枚举：SPEED_UP_RUBY=1 / SPEED_UP_ITEM=2 / SPEED_UP_ADV=3
#   AdvType 枚举：ADV_EFFECT=1 / ADV_SHOP=2
#   EAdvEffectId 枚举：… PRODUCTION=6 / BUILDING=8
# 客户端点击流程（SpeedUpPopVO._onBtnAdvSpeed / _onBtnItemSpeed /
# _onBtnRubySpeed，game.js）：
#   广告：playAdv(ADV_EFFECT, BUILDING) —— 服务端 WatchAdvRequest 回包后，
#         VIP>=3 / 免广告的号客户端直接跳过视频；随后本地构造
#         SpeedUpResult(type=3, useNum=0) 并发 SpeedUpUpgradeBuildingRequest，
#         服务端 +1800 秒（30 分钟）。
#   加速器：每个道具 = 1 分钟；useNum = min(剩余分钟, 持有数量)。
#   钻石：useNum=0，服务端按剩余时间算价（SpeedUpRubyCfg）。
SPEEDUP_RUBY = 1
SPEEDUP_ITEM = 2
SPEEDUP_ADV = 3
ADV_TYPE_EFFECT = 1
ADV_EFFECT_BUILDING = 8
# WatchAdvRequest 回包到 SpeedUpUpgradeBuildingRequest 之间至少要隔这么久。
# 线上实测（2026-10-02 文徵明8014）：隔 0.8 秒服务端回 'adv not finished'；
# 隔 3 秒再发，加速立刻生效（建筑 finish 直接减 1800 秒）。
SPEEDUP_ADV_WAIT = 3.0
# 广告档失败后整体歇多久（秒）。用户开了加速器/钻石时，广告一旦失败
# 就让下一轮改走那一档，避免同一栋楼每 30 秒撞一次 adv not finished。
SPEEDUP_AD_COOLDOWN = 600
# 剩余不足这么久就不值得加速（等完工提交更划算，广告次数/道具/钻石都省下来）。
SPEEDUP_MIN_LEFT = 60


def _watch_adv_payload(adv_type, adv_id):
    """WatchAdvRequest { #1: type:int32, #2: id:int32 }（两个都 required）。"""
    return (_pb_tag(1, 0) + write_varint(int(adv_type))
            + _pb_tag(2, 0) + write_varint(int(adv_id)))


def _speedup_building_payload(building_id, cost_type, use_num=0):
    """SpeedUpUpgradeBuildingRequest { #1: buildingId, #2: speedUp }。

    speedUp 是内嵌的 SpeedUpCostParam { #1: type, #2: useNum }，绝不能拍平
    —— #2 是 length-delimited 子消息，写成标量服务端会把整条丢掉。
    """
    b = str(building_id).encode('utf-8')
    out = _pb_tag(1, 2) + write_varint(len(b)) + b
    sub = (_pb_tag(1, 0) + write_varint(int(cost_type))
           + _pb_tag(2, 0) + write_varint(int(use_num)))
    out += _pb_tag(2, 2) + write_varint(len(sub)) + sub
    return bytes(out)


