def _day_start_epoch(ts):
    """把服务器时间戳(秒)对齐到本地时区的当天 0 点。"""
    try:
        lt = time.localtime(int(ts))
        return int(time.mktime((lt.tm_year, lt.tm_mon, lt.tm_mday,
                               0, 0, 0, 0, 0, -1)))
    except Exception:
        return 0


def _guild_title_ready(gi, now):
    """职级礼包能不能领。逐字复刻客户端 GuildModel.isGotTitle()：
      isGotTitle() = gotTitle && getOpenDays(gotTitleTime) > 1
      getOpenDays(t) = floor((now - startOfDay(t)) / 86400) + 1
    即 gotTitle 有值、且已经跨到 gotTitleTime 的第二天。"""
    if not gi or not int(gi.get('gotTitle') or 0):
        return False
    day0 = _day_start_epoch(gi.get('gotTitleTime') or 0)
    if not day0:
        return False
    return (float(now) - day0) >= 86400


