def _pet_exp_to(level):
    """从 1 级升到 `level` 级累计需要多少宠物经验（升到该级的消耗）。"""
    need = 0
    for a, b, v in PET_LEVEL_RUNS:
        if level < a:
            break
        need += (min(level, b) - a + 1) * v
    return need


def _pet_level_cap(player_level):
    """玩家等级 -> 海兽等级上限（客户端 PetUtil.curMaxLevel）。"""
    cap = PET_LEVEL_CAP[0][1]
    for pl, ml in PET_LEVEL_CAP:
        if int(player_level) >= pl:
            cap = ml
        else:
            break
    return cap


def _pet_star_cost(sp_id, cur_star):
    """当前 `cur_star` 星升下一星的 (石名, 石数, 经验)；满星/未知返回 None。"""
    rows = PET_STAR_CFG.get(int(sp_id or 0))
    _s = int(cur_star or 0)
    if not rows or _s >= PET_STAR_MAX or _s < 0:
        return None
    name, cnt, exp = rows[_s]
    return (name, int(cnt), int(exp))


