def _antique_color(antique_id):
    """藏品 id -> 颜色（决定升星消耗哪一列）。认不出来就返回 None。"""
    aid = str(antique_id or '')
    if aid in ANTIQUE_ORANGE_EXTRA:
        return 'ORANGE'
    if len(aid) >= 3 and aid[:2] == '藏品':
        return {'蓝': 'BLUE', '紫': 'PURPLE',
                '橙': 'ORANGE', '红': 'RED'}.get(aid[2])
    return None


def _antique_star_cost(star, color):
    """升到 star 星要多少碎片；star 越界或颜色认不出来返回 None。"""
    row = ANTIQUE_STAR_COST.get(int(star or 0))
    if not row:
        return None
    idx = _ANTIQUE_COLOR_IDX.get(color)
    if idx is None:
        return None
    return row[idx]


# ---- 英雄徽章穿戴 ----
# schema: PutOnBadgeRequest { #1 uid:int64, #2 heroId:string, #3 pos:int32 }
def _put_on_badge_payload(uid, hero_id, pos):
    b = str(hero_id).encode('utf-8')
    return (_pb_tag(1, 0) + write_varint(int(uid) & ((1 << 64) - 1)) +
            _pb_tag(2, 2) + write_varint(len(b)) + b +
            _pb_tag(3, 0) + write_varint(int(pos)))


# ---- 英雄装备穿戴 / 替换 ----
# schema: PutOnEquipRequest { #1 uid:int64, #2 heroId:string }
def _put_on_equip_payload(uid, hero_id):
    b = str(hero_id).encode('utf-8')
    return (_pb_tag(1, 0) + write_varint(int(uid) & ((1 << 64) - 1)) +
            _pb_tag(2, 2) + write_varint(len(b)) + b)


# schema: EquipReplaceRequest { #1 downUid:int64, #2 upUid:int64 }
def _equip_replace_payload(down_uid, up_uid):
    return (_pb_tag(1, 0) + write_varint(int(down_uid) & ((1 << 64) - 1)) +
            _pb_tag(2, 0) + write_varint(int(up_uid) & ((1 << 64) - 1)))


# schema: BadgeReplaceRequest { #1 downUid:int64, #2 upUid:int64 }
def _badge_replace_payload(down_uid, up_uid):
    return (_pb_tag(1, 0) + write_varint(int(down_uid) & ((1 << 64) - 1)) +
            _pb_tag(2, 0) + write_varint(int(up_uid) & ((1 << 64) - 1)))


