EQUIP_TYPES = ('武器', '防具', '饰品')


def _equip_rank(item):
    """装备排序键，越大越好（照搬客户端 EquipSelectPop 的比较器）。"""
    q = int((EQUIP_CFG.get(item.get('equipId')) or ('', 0))[1] or 0)
    return (q, int(item.get('star') or 0), int(item.get('level') or 0))


def _badge_rank(badge):
    """徽章排序键，越大越好（照搬客户端 BadgeSelectPop 的比较器）。"""
    q = int((BADGE_CFG.get(badge.get('badgeId')) or ('', 0))[1] or 0)
    return (int(badge.get('level') or 0), q, int(badge.get('star') or 0))


def _equip_type(equip_id):
    row = EQUIP_CFG.get(equip_id)
    return row[0] if row else ''


def _badge_career(badge_id):
    row = BADGE_CFG.get(badge_id)
    return row[0] if row else ''


def _badge_slots_for_level(level):
    """英雄等级解锁的徽章槽位号列表。"""
    lv = int(level or 0)
    return [p for p, need in sorted(BADGE_UNLOCK.items()) if lv >= need]


def _plan_equip_wear(heroes, equips_by_uid, names, deny, now):
    """算出这一轮要给哪些英雄穿/换哪件装备。

    返回 [{hero, type, action('put'|'replace'), uid, down, key}, ...]。
    排序与挑选规则完全照搬客户端 EquipSelectPop：
      (qualityIndex, star, level) 越大越好；空闲件优先于已穿件。
    每件空闲装备只会被分配给一个英雄（used 集合）。
    """
    worn = set()
    for v in (heroes or {}).values():
        for e in ((v or {}).get('equips') or []):
            u = int(e.get('uid') or 0)
            if u:
                worn.add(u)
    free = [dict(e or {}) for u, e in (equips_by_uid or {}).items()
            if int(u) not in worn and _equip_type((e or {}).get('equipId'))]
    by_type = {}
    for t in EQUIP_TYPES:
        lst = [e for e in free if _equip_type(e.get('equipId')) == t]
        lst.sort(key=_equip_rank, reverse=True)
        by_type[t] = lst
    used = set()
    plan = []
    for nm in (names or []):
        v = (heroes or {}).get(nm) or {}
        have = {}
        for e in (v.get('equips') or []):
            t = _equip_type(e.get('equipId'))
            if t:
                have[t] = e
        for t in EQUIP_TYPES:
            cur = have.get(t)
            best = None
            for cand in by_type.get(t) or []:
                if int(cand['uid']) in used:
                    continue
                if cur is None or _equip_rank(cand) > _equip_rank(cur):
                    best = cand
                    break
            if best is None:
                continue
            key = '%s:%s' % (nm, t)
            if now < ((deny or {}).get(key) or 0):
                continue
            used.add(int(best['uid']))
            plan.append({'hero': nm, 'type': t,
                         'action': 'put' if cur is None else 'replace',
                         'uid': int(best['uid']),
                         'down': int((cur or {}).get('uid') or 0),
                         'key': key})
    return plan


def _plan_badge_wear(heroes, badges_by_uid, names, deny, now):
    """算出这一轮要给哪些英雄哪个槽位穿/换哪个徽章。

    返回 [{hero, pos, action('put'|'replace'), uid, down, key}, ...]。
    规则：只动上阵英雄已解锁的槽位（1/70/90/110 级）；徽章职业必须
    和英雄职业一致；排序照搬客户端 BadgeSelectPop：
      (level, qualityIndex, star) 越大越好。
    """
    worn = set()
    for v in (heroes or {}).values():
        for b in ((v or {}).get('badges') or []):
            u = int(b.get('uid') or 0)
            if u:
                worn.add(u)
    free = [dict(b or {}) for u, b in (badges_by_uid or {}).items()
            if int(u) not in worn and _badge_career((b or {}).get('badgeId'))]
    by_career = {}
    for c in ('坦克', '战士', '法师', '射手'):
        lst = [b for b in free if _badge_career(b.get('badgeId')) == c]
        lst.sort(key=_badge_rank, reverse=True)
        by_career[c] = lst
    used = set()
    plan = []
    for nm in (names or []):
        v = (heroes or {}).get(nm) or {}
        career = HERO_CAREER.get(nm) or ''
        if not career:
            continue
        slots = {}
        for b in (v.get('badges') or []):
            p = int(b.get('pos') or 0)
            if p:
                slots[p] = b
        for pos in _badge_slots_for_level(v.get('level')):
            cur = slots.get(pos)
            best = None
            for cand in by_career.get(career) or []:
                if int(cand['uid']) in used:
                    continue
                if cur is None or _badge_rank(cand) > _badge_rank(cur):
                    best = cand
                    break
            if best is None:
                continue
            key = '%d:%s:%d' % (int(best['uid']), nm, pos)
            if now < ((deny or {}).get(key) or 0):
                continue
            used.add(int(best['uid']))
            plan.append({'hero': nm, 'pos': pos,
                         'action': 'put' if cur is None else 'replace',
                         'uid': int(best['uid']),
                         'down': int((cur or {}).get('uid') or 0),
                         'key': key})
    return plan



