def hero_max_up_level(player_level):
    """与客户端 HeroUtil.maxUpHeroLevel 同规则，返回当前玩家等级可升到的英雄等级。"""
    try:
        player_level = int(player_level or 0)
    except Exception:
        player_level = 0
    cap = 1
    for start, end, _exp, req_player_lv in HERO_UPGRADE_RANGES:
        if req_player_lv > player_level:
            break
        cap = end
    return cap


# HeroStarCfg: 下一星级对应的英雄专属碎片消耗。star 0 -> 1 也按 1 片计。
HERO_STAR_SHARD_COST = (
    0, 1, 1, 2, 2, 4, 5, 5, 5, 10, 15,
    20, 20, 20, 20, 50, 50, 50, 50, 50,
    120, 120, 120, 120, 120,
)


def hero_upgrade_exp_cost(level):
    """返回英雄从 level 升到 level+1 需要的经验。"""
    try:
        target = int(level or 1) + 1
    except Exception:
        target = 2
    for start, end, exp, _req_player_lv in HERO_UPGRADE_RANGES:
        if start <= target <= end:
            return exp
    return 0


def hero_star_shard_cost(star):
    """返回英雄从当前 star 继续升星需要的专属碎片数量。"""
    try:
        nxt = int(star or 0) + 1
    except Exception:
        nxt = 1
    if 0 <= nxt < len(HERO_STAR_SHARD_COST):
        return HERO_STAR_SHARD_COST[nxt]
    return 0


