def _radar_kind(ev):
    """RadarEvent -> (kind, 中文名, 是否要打仗)。

    判定顺序对齐客户端：固定事件优先，其次 #7~#10 四个标志，
    四个都没置就是 other（救海兽/捞宝箱/占宝藏那类跑腿事件）。
    """
    if not ev:
        _n, _c, _d = RADAR_KINDS['other']
        return 'other', _n, _c
    if ev.get('fixed'):
        k = 'fixed'
    elif ev.get('pirate'):
        k = 'pirate'
    elif ev.get('citySpy'):
        k = 'citySpy'
    elif ev.get('refugee'):
        k = 'refugee'
    elif ev.get('collectRes'):
        k = 'collectRes'
    else:
        k = 'other'
    name, combat, _default = RADAR_KINDS[k]
    return k, name, combat


