# 面板画"生产这个需要什么"用的配方表：{厂名: {产品: [[材料, 数量], ...]}}。
# 协议里没有配方字段，面板只能由服务端从这份配置导出。
FAC_COST_MAP = {}
for _fac, _prods in (FACTORY_PRODUCT_COST or {}).items():
    _ent = {}
    for _prod, _cfg in (_prods or {}).items():
        _cost = []
        for _m, _q in ((_cfg or {}).get('cost') or []):
            _cost.append([str(_m), int(_q)])
        _ent[str(_prod)] = _cost
    FAC_COST_MAP[_fac] = _ent

# 游戏建筑名与官方配置名的差异映射。生产调度和面板必须使用同一套别名，
# 否则 1选种厂 会显示为“没有配方”。
#
# 注意：**不要**再把「精铁厂」映射到「金属厂」。线上实测同一账号会同时
# 拥有 1金属厂 和 1精铁厂（如 c0696c48a3 同时有 1金属厂 Lv.2 与
# 1/2/3精铁厂）。配置里两者也是两栋楼：金属厂产粗铁（BuildingProduceCfg），
# 精铁厂 是「冶炼厂」，只有 BuildingUpgradeCfg 的被动 product=[精铁,60]，
# 每小时被动产强化石，没有生产队列。映射到一起会把粗铁排产排到冶炼厂上，
# 服务端一律拒绝，金属厂反而排不到活。
FACTORY_KEY_ALIASES = {
    '选种厂': '种子厂',
}

# 用户界面/任务描述与协议 buildingId 的常见叫法差异。这里只做诊断
# 和测试归一，发送请求仍使用快照或配置表里的真实 buildingId。
BUILD_NAME_ALIASES = {
    '拾荒船': '1探险船',
    '探险船': '1探险船',
    '潜水船坞': '1潜水船',
    '潜水船': '1潜水船',
    '农作物厨房': '1食品厂B',
}

def _building_alias(name):
    """把用户叫法归一到已知 buildingId；未知名字原样返回。"""
    raw = str(name or '')
    for _alias, _target in BUILD_NAME_ALIASES.items():
        if _alias in raw:
            return _target
    return raw


def _factory_config_name(name):
    raw = str(name or '')
    best = ''
    for alias in FACTORY_KEY_ALIASES:
        if raw.endswith(alias) and len(alias) > len(best):
            best = alias
    return FACTORY_KEY_ALIASES[best] if best else raw


def _fac_products(name, level=None):
    """按后缀匹配工厂，并过滤当前建筑等级尚未解锁的产品。"""
    name = _factory_config_name(name)
    best = None
    for k, v in FACTORY_PRODUCTS.items():
        if name.endswith(k) and (best is None or len(k) > len(best[0])):
            best = (k, v)
    if not best:
        return []
    products = best[1]
    if level is None:
        return products
    try:
        lv = int(level)
    except Exception:
        return products
    levels = FACTORY_PRODUCT_LEVELS.get(best[0]) or {}
    return [p for p in products if int(levels.get(p, 1)) <= lv]


def _factory_key(name):
    """把建筑名归一到官方配置键（'1食品厂B' -> '食品厂B'），匹配不到返回 None。

    不能拿整名去查表 —— 建筑名带序号前缀（1食品厂B / 2精铁厂），
    只有"以配置键结尾"这条规则才认得出来（和 _fac_products 同一套口径）。
    """
    nm = _factory_config_name(name)
    best = None
    for k in FACTORY_PRODUCTS:
        if nm.endswith(k) and (best is None or len(k) > len(best)):
            best = k
    return best


def _fac_produce_cost(name, product):
    """取某工厂产品的原料配方：[(材料名, 需要数量), ...]，查不到返回 None。

    None 与 [] 语义不同：None = 这张表里没有该配方（不拦），
    [] = 配方存在但不需要任何原料（例如活动产物）。
    """
    cfg = _factory_key(name)
    ent = (FACTORY_PRODUCT_COST.get(cfg) or {}).get(product)
    if not ent:
        return None
    return [(str(m), int(q)) for m, q in (ent.get('cost') or [])]


def _fac_missing(name, product, have):
    """按客户端 isAssetsEnough 的口径判原料；返回缺的那几项。

    返回 [(材料名, 需要, 现有), ...]；空列表表示料齐了（或这份配方没记录）。
    """
    cost = _fac_produce_cost(name, product)
    if not cost:
        return []
    miss = []
    for m, q in cost:
        cur = int((have or {}).get(m) or 0)
        if cur < q:
            miss.append((m, q, cur))
    return miss


def _expand_product_needs(needed, have, rounds=3):
    """把订单缺的成品沿配方向原料展开，供工厂排产和农田选种共用。"""
    out = set(needed or ())
    for _ in range(max(0, int(rounds or 0))):
        extra = set()
        for product in list(out):
            for products in FACTORY_PRODUCT_COST.values():
                ent = products.get(product)
                if not ent:
                    continue
                for mat, qty in (ent.get('cost') or []):
                    if int((have or {}).get(mat) or 0) < int(qty):
                        extra.add(str(mat))
        if not extra - out:
            break
        out |= extra
    return out


def _short_product_qty(need_qty, have, rounds=3):
    """给定“要凑够这些产物各多少”，返回数量还不够、且能沿配方展开的产物
    集合形式的 **数量**：{产物名: 还差几个}（含中间料）。

    和 _expand_product_needs 的区别：那个只看“单个配方的一份原料够不够”，
    这个按**总需求量**算缺口，所以一次就能把“要 4 个粗铁 → 还差 10 份
    淡水”这种下游缺口一起算出来，金属厂和海水厂能并行开工，不必一轮
    一轮等。用于把主线建造材料变成工厂排产目标。
    """
    short = {}
    frontier = {str(k): int(v) for k, v in (need_qty or {}).items()
                if int(v or 0) > 0}
    for _ in range(max(0, int(rounds or 0))):
        nxt = {}
        for prod, qty in frontier.items():
            have_q = int((have or {}).get(prod) or 0)
            if have_q >= qty:
                continue
            gap = qty - have_q
            short[prod] = max(short.get(prod, 0), gap)
            cost = None
            for products in FACTORY_PRODUCT_COST.values():
                ent = products.get(prod)
                if ent:
                    cost = ent.get('cost') or []
                    break
            if not cost:
                continue
            for mat, per in cost:
                nxt[str(mat)] = nxt.get(str(mat), 0) + int(per) * gap
        if not nxt:
            break
        frontier = nxt
    return short


def _short_products(need_qty, have, rounds=3):
    """同 _short_product_qty，只要名字集合（旧调用方保持不变）。"""
    return set(_short_product_qty(need_qty, have, rounds))


# 仓储上限是“历史峰值”学出来的（服务端不下发容量）。峰值太小的不进
# “满仓”集合 —— 鱼肠线这类产物“曾经只拿到过4个”，峰值就是 4，看着
# 4/4 看着满了，其实真实堆叠上限远不止。拿它当满仓会把倒仓排产自己
# 也堵死，反而卡得更死。10 是拍下来的下限：真满仓的原料（鱼/木材/
# 塑料/汽油/生鱼片…）都在 50 以上，远高于它。
DRAIN_CAP_FLOOR = 10

# 「常备生产」的产量下限：工厂没订单需求（或订单不缺这一样）时也照常
# 开工，把当前等级能产的东西造到上限为止，别让生产槽位空着干等。上限
# 优先用历史峰值学（工厂产物实测普遍收敛到 50），没学到时用这个下限
# 兜底，保证新品也能先备一点。
FAC_IDLE_CAP_FLOOR = 20

# 工厂排产队列的槽位数（实测：家具厂/服装厂 5，海水厂 4，玩具厂/食品厂 3，
# 建材厂/日用品厂/材料厂/药品厂 2）。服务端不下发这个容量，只能按类型打表；
# 快照里一旦看到更多槽位，_fac_slot_max 会跟着抬上来。
FACTORY_SLOT_HINT = {
    '家具厂': 5,
    '服装厂': 5,
    '海水厂': 4,
    '玩具厂': 3,
    '食品厂': 3,
    '食品厂B': 3,
    '建材厂': 2,
    '日用品厂': 2,
    '材料厂': 2,
    '药品厂': 2,
}
# 没打表 / 没学到的工厂按两个槽兜底：至少比"一轮一个"快一倍。
FACTORY_SLOT_DEFAULT = 2


def _drain_product(fac_name, product, have, capped):
    """这份产品能不能拿来"倒逼排产"（吃满仓原料、自己没满仓、料齐）。

    产物本身已经满仓的直接否掉 —— 做出来也收不进仓库，白占一个槽位；
    配方一个满仓原料都不吃也否掉 —— 那腾不出任何仓容。两条都满足才
    放行，避免为了倒仓排出一堆没人要、也没地方放的货。
    """
    try:
        if product in capped:
            return False
        cost = _fac_produce_cost(fac_name, product)
    except Exception:
        return False
    if not cost:
        return False
    if not any(m in capped for m, _q in cost):
        return False
    return not _fac_missing(fac_name, product, have)


def _drain_note(view, capped):
    """主线卡在"获取资源"且材料满仓时，给面板的一句话原因。

    优先挑任务描述里点名的那种材料（#55 描述里就有"鱼"），挑不到就
    退回数量最多的那项。面板把它拼在主线那一行后面，用户不用猜。
    """
    if not capped:
        return ''
    desc = str((view or {}).get('desc') or '')
    hit = None
    for nm in capped:
        if nm and nm in desc:
            hit = nm
            break
    if hit is None:
        hit = sorted(capped, key=lambda k: -capped[k][0])[0]
    cnt, cap = capped[hit]
    return '%s已满仓 %d/%d，正在排产腾仓' % (hit, cnt, cap)


def _plan_factory_jobs(buildings, need_set, have, capped, drain_on,
                       cap_of, pop_block=None, pop_ts=0.0,
                       need_qty=None, slot_cap_of=None):
    """给每家工厂挑这一轮开工的产品（纯函数，方便单测）。

    优先级：需求活（hot，订单/主线当下缺的）> 倒逼排产（drain，主线卡在
    满仓资源上时腾仓）> 常备活（idle，需求之外的产品）。

    队列能排几个就排几个：同一家厂有多个生产槽，以前一轮只派一个活、而且槽里
    已有的产品直接跳过，于是"主线还差 4 个电线"这种单子只能一轮一个地磨。
    现在按缺口的**数量**一次排够，并且整个规划里同一产品的总量不超过缺口
    （不会两家建材厂各把四个电线排一遍）。

    没传 slot_cap_of 时按"一轮一个"（旧行为，老单测不变）。

    返回 (jobs, blocked, up_need)：
      jobs    [(建筑名, 产品名, is_hot, is_drain), ...]
      blocked [(建筑名, 产品名, [(原料, 需要, 现有)]), ...]
      up_need [{building, product, level, need[, why]}, ...]
    """
    need_set = need_set or set()
    have = have or {}
    need_qty = need_qty or {}
    jobs, blocked, up_need = [], [], []

    def _have_of(prod):
        try:
            return int(have.get(prod) or 0)
        except Exception:
            return 0

    def _qty_of(prod, default=1):
        try:
            n = int(need_qty.get(prod) or 0)
        except Exception:
            n = 0
        try:
            d = int(default or 1)
        except Exception:
            d = 1
        return n if n > 0 else d

    # 排队里已有的先扣掉，再把剩下的缺口分给各家厂：同一个产品可能两家厂都造得
    # 出来（1建材厂/2建材厂），不扣就会各排一遍、白造一倍。
    _queued_all = {}
    for _nm0, _v0 in (buildings or {}).items():
        if '厂' not in str(_nm0):
            continue
        for _sl0 in ((_v0 or {}).get('slots') or []):
            _p0 = _sl0.get('2')
            if _p0:
                _p0 = str(_p0)
                _queued_all[_p0] = _queued_all.get(_p0, 0) + 1
    need_left = {}
    for _p0 in need_set:
        need_left[_p0] = max(0, _qty_of(_p0) - int(_queued_all.get(_p0, 0) or 0))

    for nm, v in (buildings or {}).items():
        if '厂' not in nm:
            continue
        try:
            level = int((v or {}).get('state') or 0)
        except Exception:
            level = 0
        allp = _fac_products(nm)
        prods = _fac_products(nm, level) if level > 0 else []
        # 订单要的东西这家厂造不出来，是因为等级没到？记下来，面板/日志才能
        # 说清"得先把这家厂升上去"。
        _lvmap = FACTORY_PRODUCT_LEVELS.get(_factory_key(nm)) or {}
        for _p in allp:
            if (_p in need_set and _p not in prods
                    and int(_lvmap.get(_p, 1)) > level):
                _ent = {'building': nm, 'product': _p, 'level': level,
                        'need': int(_lvmap.get(_p, 1))}
                # 这家厂刚被"人口不足"顶回来过 —— 面板据此说明等级为什么
                # 迟迟不动，而不是让用户干等。
                if (pop_block or {}).get(nm, 0) > pop_ts:
                    _ent['why'] = '人口不足'
                up_need.append(_ent)
        if not prods:
            # Lv.0 只是蓝图/未建成，服务端会直接拒排产。
            continue
        # 槽位里现在排着什么（产品名 -> 占了几个槽）。
        busy_list = [str(sl.get('2')) for sl in ((v or {}).get('slots') or [])
                     if sl.get('2')]
        busy = set(busy_list)
        # 这家厂还能排几个：没给 slot_cap_of 就按只排一个（旧行为）。
        if slot_cap_of is None:
            room = 1
        else:
            try:
                _cap = int(slot_cap_of(nm) or 0)
            except Exception:
                _cap = 0
            room = _cap - len(busy_list)
        if room <= 0:
            continue
        free = [x for x in prods if x not in busy]
        rel_all = [x for x in prods if x in need_set]
        # ---- 需求活：缺口还差几个就排几个（料不齐的记进 blocked）----
        lack_rel = []
        hot_pick = []
        for p in sorted(rel_all,
                        key=lambda x: (-int(need_left.get(x, 0) or 0), x)):
            still = int(need_left.get(p, 0) or 0)
            if still <= 0:
                continue
            miss = _fac_missing(nm, p, have)
            if miss:
                lack_rel.append((p, miss))
                continue
            hot_pick.append((p, still))
        hot_done = 0
        left = room
        for p, still in hot_pick:
            if left <= 0:
                break
            take = min(int(still), left)
            for _ in range(max(0, take)):
                jobs.append((nm, p, True, False))
            left -= max(0, take)
            hot_done += max(0, take)
            need_left[p] = int(need_left.get(p, 0) or 0) - max(0, take)
        # ---- 常备活：需求之外、还没到常备上限的，料齐就能开工 ----
        idle_free = [p for p in free
                     if p not in need_set
                     and _have_of(p) < int(cap_of(p))]
        ready_i, lack_i = [], []
        for p in idle_free:
            miss = _fac_missing(nm, p, have)
            if miss:
                lack_i.append((p, miss))
            else:
                ready_i.append(p)
        # 主线卡在获取资源、原料又满仓时（#55 鱼满仓），先让这家厂做一次
        # 倒逼排产把仓容腾出来。
        _drain_pick = None
        if drain_on and not hot_done:
            for p in free:
                if _drain_product(nm, p, have, capped):
                    _drain_pick = p
                    break
        # ---- 需求之后还有空槽：先倒逼排产，再补常备生产。----
        # 旧逻辑只要 hot_done 大于 0 就整厂收工，导致"要 4 个电线、2 个槽"
        # 时剩下的槽空着。这里把每个空槽都用完，但需求活永远排在最前。
        def _append_idle(n, limit):
            if limit <= 0:
                return 0
            wrote = 0
            for p in ready_i:
                if wrote >= limit:
                    break
                jobs.append((nm, p, False, False))
                wrote += 1
            return wrote

        if hot_done:
            if drain_on and left > 0:
                for p in free:
                    if _drain_product(nm, p, have, capped):
                        jobs.append((nm, p, False, True))
                        left -= 1
                        break
            _append_idle(room, left)
        elif _drain_pick:
            jobs.append((nm, _drain_pick, False, True))
            _append_idle(room, left - 1)
        elif ready_i:
            # 没有需求活时，常备活按全部空槽排满。
            _append_idle(room, left)
        elif lack_rel:
            # 需求的东西原料不齐：记下来给面板解释在等什么。
            blocked.append((nm, lack_rel[0][0], lack_rel[0][1]))
        elif lack_i and not rel_all:
            # 需求之外的产品也缺料：同样记一条，面板能解释。
            blocked.append((nm, lack_i[0][0], lack_i[0][1]))
    return jobs, blocked, up_need
