def _parse_resource_lines(fields):
    """从 dump 出来的行里还原 res 列表 -> [(资源ID, 数量), ...]
    形如： 'res = [6字节] 08031099ab30'  然后 '   #1 = 3'  '   #2 = 791961'
    更稳的做法是直接用原始 hex 解，这里两种都试。
    """
    out = []
    cur = None
    for line in fields:
        s = str(line)
        st = s.strip()
        if st.startswith('res ='):
            # 直接从 hex 解一遍，最可靠
            try:
                hexpart = st.rsplit(']', 1)[-1].strip()
                raw = bytes.fromhex(hexpart)
                rid = cnt = None
                o = 0
                while o < len(raw):
                    k, o = read_varint(raw, o)
                    fn, wt = k >> 3, k & 7
                    if wt == 0:
                        v, o = read_varint(raw, o)
                        if fn == 1: rid = v
                        elif fn == 2: cnt = v
                    else:
                        break
                if rid is not None and cnt is not None:
                    out.append((rid, cnt))
                    cur = None
                    continue
            except Exception:
                pass
            cur = {}
            continue
        if st.startswith('#1 = ') and cur is not None:
            try: cur[1] = int(st.split('=')[1])
            except Exception: pass
        elif st.startswith('#2 = ') and cur is not None:
            try: cur[2] = int(st.split('=')[1])
            except Exception: pass
            if 1 in cur and 2 in cur:
                out.append((cur[1], cur[2]))
                cur = None
    return out


def _guess_level(result):
    """按流水内容猜级别：ok=成功  info=正常但没结果  warn=要注意  bad=出问题"""
    r = result or ''
    if r.startswith('✅'):
        return 'ok'
    if ('失败' in r or '错误' in r or '异常' in r or 'Broken' in r
            or 'timeout' in r or 'refused' in r):
        return 'bad'
    if r.startswith('❌') or r.startswith('服务端提示'):
        return 'warn'
    if ('仓库满' in r or '队列已满' in r or '满' in r and '级' not in r):
        return 'warn'
    if r.startswith('已执行') or r.startswith('·') or r.startswith('尝试'):
        return 'info'
    return 'info'


