def _order_reject_is_normal(payload):
    """判断这个 PromptResponse 是不是"居民订单槽位已完成/不可用"。

    实测服务端的两种形态：
      #1 = 1  #2 = 36                    （无文本，槽位已完成）
      #1 = 1  #2 = 5  #3 = 'Invalid request'
      #3 = 'order not found'
    这些在"逐个槽位试探"的场景里是预期内的，不该报成错误。
    只认 #2 为 36 这种少量已知码，避免把真错误也吞掉。
    """
    try:
        vals = {}
        for fn, v in _pb_fields(payload):
            if isinstance(v, int):
                vals[fn] = v
        if vals.get(1) == 1 and vals.get(2) == 36:
            return True
    except Exception:
        pass
    return False


def _visible_hint(payload):
    """从失败回包里抠出"人能看懂"的部分；只有数字码就返回空"""
    try:
        strs = [x for x in _strings_in(payload) if not x.startswith('#')]
    except Exception:
        strs = []
    strs = [x.strip() for x in strs if x.strip()]
    if not strs:
        return ''
    return '服务端提示：%s' % (' / '.join(strs[:2])[:70])
    return ''


def _reply_summary(mtype, payload):
    """成功回包的一句话摘要：优先用中文行，其次退回原始 dump 清理后的结果"""
    try:
        lines = friendly_lines(mtype, payload) or []
    except Exception:
        lines = []
    keep = []
    for ln in lines:
        s2 = str(ln).strip()
        if not s2:
            continue
        # 跳过纯字节/纯结构 dump
        if s2.startswith(('#', 'bytes[', 'res =', 'sub =', 'item =')):
            continue
        if s2.startswith('[') and '字节]' in s2:
            continue
        keep.append(s2)
    if keep:
        return ' / '.join(keep[:3])[:110]
    return _pretty_reply(_brief(payload))


def _pretty_reply(b):
    """把响应摘要里的天书部分清掉，只留人能看懂的片段"""
    if not b:
        return ''
    txt = str(b)
    parts = []
    # 整串先做一次“资源名 数量”还原：#1 是资源ID，#2 是数量（可能跨 | 分段）
    gnums = []
    for tok in txt.replace('|', ' ').split():
        if tok.startswith('#') and '=' in tok:
            try:
                gnums.append(int(tok.split('=', 1)[1]))
            except Exception:
                pass
    if len(gnums) >= 2 and gnums[0] in RESOURCE_NAMES:
        return '%s %s' % (RESOURCE_NAMES[gnums[0]], '{:,}'.format(gnums[1]))
    for seg in txt.replace('|', ' \n ').split('\n'):
        seg = seg.strip()
        if not seg:
            continue
        nums = []
        for tok in seg.split():
            if tok.startswith('#') and '=' in tok:
                try:
                    nums.append(int(tok.split('=', 1)[1]))
                except Exception:
                    pass
        if nums and len(nums) >= 2 and nums[0] in RESOURCE_NAMES:
            parts.append('%s %s' % (RESOURCE_NAMES[nums[0]], '{:,}'.format(nums[1])))
            continue
        # 纯数字 dump / 纯字节 dump / res 天书，对用户没意义
        if seg.startswith(('bytes[', '#', 'res =', 'sub =', 'item =')):
            continue
        if seg.startswith('成功'):
            continue
        if seg.startswith('[') and '字节]' in seg:
            continue
        # 段里混着 '#1 = 39' 这种，去掉数字部分只留文本
        keep = [w for w in seg.split() if not (w.startswith('#') or w == '=' or w.isdigit())]
        seg2 = ' '.join(keep).strip()
        if seg2:
            parts.append(seg2)
    return ' | '.join(parts[:4])[:120]


def _brief(payload):
    try:
        parts = dump_proto(payload)[:4]
        t = ' | '.join(str(x).strip() for x in parts)
        return t[:150]
    except Exception:
        return ''


