EXTRA = {'SCAllActivity': '活动数据', 'SCBatchChatReceive': '聊天消息(批量)',
         'SCAllActivityUpdate': '活动更新', 'SCMailReceive': '邮件', 'SCPlayerInfo': '角色信息'}


def label_of(t):
    if t in LABELS:
        return LABELS[t]
    if t in EXTRA:
        return EXTRA[t]
    # 兜底：按命名规则翻译
    if t.startswith('SC'):
        return '推送·' + t[2:]
    if t.endswith('Request'):
        return t[:-7] + ' · 请求'
    if t.endswith('Response'):
        return t[:-8] + ' · 返回'
    return t


PROTO = {}


def load_proto():
    global PROTO
    try:
        PROTO = json.load(open(os.path.join(BASE, 'proto_defs.json')))
    except Exception:
        PROTO = {}


def _field_name(msg_type, no):
    d = PROTO.get(msg_type) or {}
    return d.get(str(no)) or d.get(no)


def named_lines(msg_type, payload, ind='', depth=0):
    """带字段名的 protobuf 展开"""
    out = []
    try:
        o = 0
        while o < len(payload):
            key, o = read_varint(payload, o)
            fn, wt = key >> 3, key & 7
            nm = _field_name(msg_type, fn) if depth == 0 else None
            tag = (nm + ' = ') if nm else ('#%d = ' % fn)
            if wt == 0:
                v, o = read_varint(payload, o)
                out.append(ind + tag + str(v))
            elif wt == 2:
                ln, o = read_varint(payload, o)
                raw = payload[o:o + ln]; o += ln
                try:
                    t2 = raw.decode('utf-8')
                    printable = t2 and all(c.isprintable() for c in t2)
                except Exception:
                    printable = False
                if printable:
                    out.append(ind + tag + t2)
                else:
                    out.append(ind + tag + '[%d字节] %s' % (ln, raw[:16].hex()))
                    if depth < 2 and ln and len(out) < 40:
                        sub = named_lines(msg_type, raw, ind + '   ', depth + 1)
                        if sub and not any('…' in x for x in sub):
                            out += sub
            elif wt == 5:
                out.append(ind + tag + str(int.from_bytes(payload[o:o + 4], 'little'))); o += 4
            elif wt == 1:
                out.append(ind + tag + str(int.from_bytes(payload[o:o + 8], 'little'))); o += 8
            else:
                break
    except Exception:
        pass
    return out


def _pb_fields(b):
    """把一层 protobuf 解成 [(字段号, 值)]。
    值：varint 给 int，length-delimited 给 bytes（字符串也先给 bytes，调用方自己解）。
    解不动的部分直接停下，不抛异常——抓包数据经常被截断。"""
    out = []
    o = 0
    while o < len(b):
        try:
            k, o = read_varint(b, o)
        except Exception:
            break
        fn, wt = k >> 3, k & 7
        try:
            if wt == 0:
                v, o = read_varint(b, o)
                out.append((fn, v))
            elif wt == 2:
                ln, o = read_varint(b, o)
                out.append((fn, b[o:o + ln])); o += ln
            elif wt == 5:
                out.append((fn, int.from_bytes(b[o:o + 4], 'little'))); o += 4
            elif wt == 1:
                out.append((fn, int.from_bytes(b[o:o + 8], 'little'))); o += 8
            else:
                break
        except Exception:
            break
    return out


def _pb_str(raw):
    """bytes 尝试当 utf-8 字符串解，失败返回 None"""
    try:
        s = raw.decode('utf-8')
        if s and all(c.isprintable() for c in s):
            return s
    except Exception:
        pass
    return None


def _ex_cargo_ships(payload):
    """CargoShipsResponse -> [{index, cargoIndex, arriveTime}]

    schema（proto_defs.remote.json / DispCargoShip）：
      { #1 shipIndex, #2 cargoIndex, #5 arriveTime }
    ★ 2026-10-05：旧实现把 #2 当成 status 并用 status==2 判“到港”，
    但 #2 其实是 cargoIndex，于是永远判不出到港、从没领过奖励。
    现在按 arriveTime 判到港，cargoIndex 用于装货/卸货判断。
    """
    out = []
    for fn, raw in _pb_fields(payload):
        if fn != 1 or not isinstance(raw, (bytes, bytearray)):
            continue
        item = {'index': 0, 'cargoIndex': 0, 'arriveTime': 0}
        for f2, v2 in _pb_fields(raw):
            if f2 == 1 and isinstance(v2, int):
                item['index'] = v2
            elif f2 == 2 and isinstance(v2, int):
                item['cargoIndex'] = v2
            elif f2 == 5 and isinstance(v2, int):
                item['arriveTime'] = v2
        if item['index']:
            out.append(item)
    return out


