    """LeagueInfoResponse / LeagueGotBonusDanResponse -> 标量字段字典。"""
    out = {}
    for fn, raw in _pb_fields(payload):
        if isinstance(raw, int) and fn in LEAGUE_INFO_FIELDS:
            out[LEAGUE_INFO_FIELDS[fn]] = raw
