def _ex_league_rank(payload, only_field=None):
    """排行榜/对手列表 -> [{playerId, power, worldId, nickname}]。

    实测（2026-10-05 线上 LeagueInfoResponse#3）：每条对手是
      { #1 index, #2 playerId:int64, #3 nickname:string,
        #4 score, #5 power, #6 英雄信息, #7 worldId }
    LeagueRankItem 同形。only_field 用来限定只看某个 repeated 字段
    （LeagueInfoResponse 里对手就是 #3），不传则扫所有子消息。
    """
    out = []
    for fn, raw in _pb_fields(payload):
        if only_field is not None and fn != only_field:
            continue
        if not isinstance(raw, (bytes, bytearray)):
            continue
        rec = {}
        for f2, v2 in _pb_fields(raw):
            if f2 == 2 and isinstance(v2, int):
                rec['playerId'] = v2
            elif f2 == 3 and isinstance(v2, (bytes, bytearray)):
                _nm = _pb_str(v2)
                if _nm:
                    rec['nickname'] = _nm
            elif f2 == 4 and isinstance(v2, int):
                rec['score'] = v2
            elif f2 == 5 and isinstance(v2, int):
                rec['power'] = v2
            elif f2 == 7 and isinstance(v2, int):
                rec['worldId'] = v2
        if rec.get('playerId'):
            out.append(rec)
    return out


