def _ex_guild_order(payload):
    """GuildOrderResponse / SCGuildOrder -> 当前联盟订单的缺料清单。

    客户端 schema（1.13.4 bundle.59dc0.js 逐字核对，线上实测一致）：
      GuildOrderResponse { #1: order:DispGuildOrder }   （required）
      SCGuildOrder       { #1: order:DispGuildOrder }
      DispGuildOrder     { #2: repeated requirements:DisplayAsset,
                           #3: nextRefreshTime:int32 }
      DisplayAsset       { #1: type:int32, #2: id:string, #3: num:int64 }

    客户端 GuildCityArmyPop._refreshOrder 就是拿 order.requirements 当
    "完成订单"要交的货；交完 FinishGuildOrderRequest 会给联盟城市 +1 守军
    并推进主线 #113（MainTaskCfg #113 type=累计联盟订单）。
    """
    reqs = []
    refresh = 0
    for fn, raw in _pb_fields(payload):
        if fn != 1 or not isinstance(raw, (bytes, bytearray)):
            continue
        for f2, v2 in _pb_fields(raw):
            if f2 == 2 and isinstance(v2, (bytes, bytearray)):
                item_id = ''
                num = 0
                for f3, v3 in _pb_fields(v2):
                    if f3 == 2 and isinstance(v3, (bytes, bytearray)):
                        item_id = _pb_str(v3) or ''
                    elif f3 == 3 and isinstance(v3, int):
                        num = v3
                if item_id:
                    reqs.append((item_id, int(num or 0)))
            elif f2 == 3 and isinstance(v2, int):
                refresh = v2
    return {'reqs': reqs, 'refresh': refresh}


def _ex_guild_info(payload):
    """GuildInfoResponse -> 联盟快照（礼包 / 职级 / 基本信息）。

    客户端 schema（1.13.6 proto-bundle.js）逐字核对：
      GuildInfoResponse { #1 guild:DispGuildDetail, #2 myTitle:int32,
                          #3 impeachEndTime, #4 gotTitle:int32,
                          #5 gotTitleTime:int32, #6 fortFund:int64,
                          #7 anonymous:bool }
      DispGuildDetail   { #1 guildId, #2 name, #3 flag, #4 announcement,
                          #6 memberCount, #7 repeated welfarePack,
                          #9 electionTime, #10 president, #11 gotWelfareTime,
                          #12 level, #13 exp }
      DispGuildWelfarePack { #1 id:int64, #2 reward, #3 createTime:int32,
                             #4 descId:string, #5 repeated descParams }
    礼包可领的判定就在客户端 GuildChestPop：某个 pack.createTime 大于
    gotWelfareTime 就说明还没领；职级礼包看 gotTitle + gotTitleTime。
    """
    out = {'guildId': 0, 'name': '', 'level': 0, 'memberCount': 0,
           'gotWelfareTime': 0, 'packs': [], 'myTitle': 0,
           'gotTitle': 0, 'gotTitleTime': 0, 'fortFund': 0,
           'anonymous': False, 'inGuild': False}
    for fn, raw in _pb_fields(payload):
        if fn == 1 and isinstance(raw, (bytes, bytearray)):
            out['inGuild'] = True
            for f2, v2 in _pb_fields(raw):
                if f2 == 1 and isinstance(v2, int):
                    out['guildId'] = v2
                elif f2 == 2 and isinstance(v2, (bytes, bytearray)):
                    # 公会名可能带全角空格/特殊符号，_pb_str 的 isprintable
                    # 检查会把整串判成非法，这里只要求能按 utf-8 解出来。
                    try:
                        out['name'] = v2.decode('utf-8').strip()
                    except Exception:
                        out['name'] = ''
                elif f2 == 6 and isinstance(v2, int):
                    out['memberCount'] = v2
                elif f2 == 7 and isinstance(v2, (bytes, bytearray)):
                    pack = {'id': 0, 'createTime': 0, 'descId': ''}
                    for f3, v3 in _pb_fields(v2):
                        if f3 == 1 and isinstance(v3, int):
                            pack['id'] = v3
                        elif f3 == 3 and isinstance(v3, int):
                            pack['createTime'] = v3
                        elif f3 == 4 and isinstance(v3, (bytes, bytearray)):
                            pack['descId'] = _pb_str(v3) or ''
                    out['packs'].append(pack)
                elif f2 == 11 and isinstance(v2, int):
                    out['gotWelfareTime'] = v2
                elif f2 == 12 and isinstance(v2, int):
                    out['level'] = v2
        elif fn == 2 and isinstance(raw, int):
            out['myTitle'] = raw
        elif fn == 4 and isinstance(raw, int):
            out['gotTitle'] = raw
        elif fn == 5 and isinstance(raw, int):
            out['gotTitleTime'] = raw
        elif fn == 6 and isinstance(raw, int):
            out['fortFund'] = raw
        elif fn == 7 and isinstance(raw, int):
            out['anonymous'] = bool(raw)
    return out


def _ex_guild_tech(payload):
    """GuildTechInfoResponse -> {techId: level}。

    客户端 schema：GuildTechInfoResponse { #1 repeated DispGuildTech tech },
    DispGuildTech { #1 techId:int32, #2 level:int32 }。
    客户端 GuildModel.initTech 就是拿这份列表覆盖本地 techMap。
    """
    out = {}
    for fn, raw in _pb_fields(payload):
        if fn != 1 or not isinstance(raw, (bytes, bytearray)):
            continue
        tech_id = level = 0
        for f2, v2 in _pb_fields(raw):
            if f2 == 1 and isinstance(v2, int):
                tech_id = v2
            elif f2 == 2 and isinstance(v2, int):
                level = v2
        if tech_id:
            out[tech_id] = level
    return out


# ---------------- VIP 免费礼包 / 日常任务 / 成长任务 ----------------
# 三条都是「纯领取、不烧资源」的日常，默认开。
#
# 协议来源：客户端 bundle.04ae2.js（proto 定义）+ game.js（调用点）
#   VipInfo        { #1 vipLevel, #2 vipExp, #3 repeated VipDailyReward,
#                    #4 repeated payPack }
#   VipDailyReward { #1 vipLevel, #2 isGot }
#   GotVipDailyRewardRequest { #1 vipLevel }
#     —— 客户端 VipView._onBtnGotDaily：_showLv <= vipLevel 且该级
#        isGot=false 才让点。也就是每个已达成的 VIP 等级每天各能领一次，
#        不是只领当前等级那一档。
#   DailyTaskInfoResponse { #1 repeated DispDailyTask, #2 dailyActivity,
#                           #3 weeklyActivity,
#                           #4 repeated dailyRewardClaimed,
#                           #5 repeated weeklyRewardClaimed,
#                           #6 dailyResetTime }
#   DispDailyTask  { #1 id, #2 progress, #3 targetProgress, #4 rewardClaimed }
#   DrawDailyTaskRewardRequest { #1 id }
#   DrawDailyRewardRequest     { #1 repeated index }
#     —— 客户端 DailyRewardItem._onClickReward：把「活跃度够且还没领」
#        的宝箱 id 打包一次发过去。门槛来自 DailyActivityRewardCfg。
#   GotBranchTaskRewardRequest { #1 taskId }
#     —— 客户端 MainTaskItem._gotReward：支线按 taskId 直接领，领完从本地
#        branchTask 表删掉 —— 所以服务端下发的 branch 列表本身就是
#        「还没领的支线」，不需要本地配置表也能全领一遍。
DAILY_ACTIVITY_TIERS = ((1, 20), (2, 40), (3, 60), (4, 80), (5, 100))


def _pb_packed_ints(raw):
    """解 repeated int32 的 packed 编码（客户端 proto 用的是 packed）。"""
    out = []
    o = 0
    while o < len(raw):
        try:
            v, o = read_varint(raw, o)
        except Exception:
            break
        out.append(v)
    return out


def _pb_int_list(payload, field):
    """取某个 repeated int32 字段，packed / 非 packed 两种都认。"""
    out = []
    for fn, raw in _pb_fields(payload):
        if fn != field:
            continue
        if isinstance(raw, int):
            out.append(raw)
        elif isinstance(raw, (bytes, bytearray)):
            out.extend(_pb_packed_ints(raw))
    return out


def _ex_vip_info(payload):
    """VipInfo -> {'level': int, 'daily': {level: isGot}}"""
    out = {'level': 0, 'daily': {}}
    for fn, raw in _pb_fields(payload):
        if fn == 1 and isinstance(raw, int):
            out['level'] = raw
        elif fn == 3 and isinstance(raw, (bytes, bytearray)):
            lv = 0
            got = False
            for f2, v2 in _pb_fields(raw):
                if f2 == 1 and isinstance(v2, int):
                    lv = v2
                elif f2 == 2 and isinstance(v2, int):
                    got = bool(v2)
            if lv:
                out['daily'][lv] = got
    return out


def _ex_daily_task_info(payload):
    """DailyTaskInfoResponse -> 日常任务快照。"""
    out = {'tasks': [], 'activity': 0, 'weeklyActivity': 0,
           'claimed': [], 'weeklyClaimed': [], 'resetTime': 0}
    for fn, raw in _pb_fields(payload):
        if fn == 1 and isinstance(raw, (bytes, bytearray)):
            rec = {'id': 0, 'progress': 0, 'target': 0, 'claimed': False}
            for f2, v2 in _pb_fields(raw):
                if not isinstance(v2, int):
                    continue
                if f2 == 1:
                    rec['id'] = v2
                elif f2 == 2:
                    rec['progress'] = v2
                elif f2 == 3:
                    rec['target'] = v2
                elif f2 == 4:
                    rec['claimed'] = bool(v2)
            if rec['id']:
                out['tasks'].append(rec)
        elif fn == 2 and isinstance(raw, int):
            out['activity'] = raw
        elif fn == 3 and isinstance(raw, int):
            out['weeklyActivity'] = raw
        elif fn == 6 and isinstance(raw, int):
            out['resetTime'] = raw
    out['claimed'] = _pb_int_list(payload, 4)
    out['weeklyClaimed'] = _pb_int_list(payload, 5)
    return out


def _ex_branch_tasks(payload):
    """MainTaskInfoResponse #3 repeated DispBranchTask
    -> {groupId: {'progress': int, 'got': bool}}

    schema（proto_defs.remote.json / DispBranchTask）:
      { #1: groupId, #2: progress, #3: gotReward, #4: startTime }
    2026-10-05: 以前只取 #1/#2，把 #3 gotReward 丢了，已经领过的
    支线照样会被反复尝试领取（服务端回 already claimed），而且
    progress 不变时还会一直卡在同一条上。
    """
    out = {}
    for fn, raw in _pb_fields(payload):
        if fn != 3 or not isinstance(raw, (bytes, bytearray)):
            continue
        tid = 0
        rec = {'progress': 0, 'got': False}
        for f2, v2 in _pb_fields(raw):
            if not isinstance(v2, int):
                continue
            if f2 == 1:
                tid = v2
            elif f2 == 2:
                rec['progress'] = v2
            elif f2 == 3:
                rec['got'] = bool(v2)
        if tid:
            out[tid] = rec
    return out


def _ex_sc_branch_task(payload):
    """SCBranchTaskUpdate #1 DispBranchTask -> (groupId, progress, got) 或 None。"""
    for fn, raw in _pb_fields(payload):
        if fn != 1 or not isinstance(raw, (bytes, bytearray)):
            continue
        tid = 0
        rec = {'progress': 0, 'got': False}
        for f2, v2 in _pb_fields(raw):
            if not isinstance(v2, int):
                continue
            if f2 == 1:
                tid = v2
            elif f2 == 2:
                rec['progress'] = v2
            elif f2 == 3:
                rec['got'] = bool(v2)
        if tid:
            return tid, rec['progress'], rec['got']
    return None


def _ex_sc_daily_task(payload):
    for fn, raw in _pb_fields(payload):
        if fn != 1 or not isinstance(raw, (bytes, bytearray)):
            continue
        rec = {'id': 0, 'progress': 0, 'target': 0, 'claimed': False}
        for f2, v2 in _pb_fields(raw):
            if not isinstance(v2, int):
                continue
            if f2 == 1:
                rec['id'] = v2
            elif f2 == 2:
                rec['progress'] = v2
            elif f2 == 3:
                rec['target'] = v2
            elif f2 == 4:
                rec['claimed'] = bool(v2)
        if rec['id']:
            return rec
    return None


def _ex_one_int(payload, field=1):
    """取某个 varint 字段的整数值（DrawDailyTaskRewardResponse#1 等）。"""
    for fn, raw in _pb_fields(payload):
        if fn == field and isinstance(raw, int):
            return raw
    return None


def _one_int_payload(value):
    """只有 #1 一个 int32 的请求体（VIP 等级 / 任务 id 都是这个形状）。"""
    return _pb_tag(1) + write_varint(int(value))


def _int_list_payload(values):
    """#1 repeated int32 的请求体（每日活跃度宝箱一次领多个）。"""
    out = bytearray()
    for v in values:
        out += _pb_tag(1) + write_varint(int(v))
    return bytes(out)


# ---------------- 世界资源地（主线 #114/#115/#116）----------------
# 客户端把世界地图当**静态资源**加载（HotUpdateRes/tt/remote/world_map），
# 服务端不下发"地图上有哪些资源地"——它只回"我占了哪些"
# （MyResFieldsResponse / SCResFieldInfo）。所以想挑目标格子，只能像客户端
# 那样读静态地图。压缩表落在 BASE/world_map_res.json，由部署脚本一起上传：
#   {"map":"world_map1","width":240,"height":640,
#    "tiles":[[gridIdx, type, cityId], ...]}
# type: 1=工厂 2=绿洲 3=油罐，取自客户端 mapData：(v // 10000) % 10。
# ★ 版本核对：线上 WorldFleet.startGridIdx 正好等于 world_map1 里对应
#   cityId 的城市中心格，多个账号都吻合 —— 用的是 world_map1，不是
#   world_map2。地图换版本时这份表要跟着重新导出。
WORLD_RES_TYPES = {1: '工厂', 2: '绿洲', 3: '油罐'}
_WORLD_FLEET_STATE = {1: '待命', 2: '移动中', 3: '返航', 5: '驻守'}
_WORLD_RES_CACHE = {'loaded': False, 'tiles': [], 'width': 0, 'map': '',
                    'cities': {}}


def world_res_tiles():
    """惰性读 BASE/world_map_res.json -> [(grid, type, city), ...]。"""
    if _WORLD_RES_CACHE['loaded']:
        return _WORLD_RES_CACHE['tiles']
    tiles = []
    width = 0
    name = ''
    cities = {}
    try:
        with open(os.path.join(BASE, 'world_map_res.json'),
                  encoding='utf-8') as f:
            data = json.load(f)
        width = int(data.get('width') or 0)
        name = data.get('map') or ''
        for item in (data.get('tiles') or []):
            if len(item) >= 3:
                tiles.append((int(item[0]), int(item[1]), int(item[2])))
        for cid, center in (data.get('cities') or {}).items():
            cities[str(cid)] = int(center)
    except Exception as e:
        print('[WORLD] 静态资源地表加载失败：%s' % e, flush=True)
    _WORLD_RES_CACHE['tiles'] = tiles
    _WORLD_RES_CACHE['width'] = width
    _WORLD_RES_CACHE['map'] = name
    _WORLD_RES_CACHE['cities'] = cities
    _WORLD_RES_CACHE['loaded'] = True
    if tiles:
        print('[WORLD] 静态资源地 %d 格（%s）' % (len(tiles), name or '?'),
              flush=True)
    return tiles


def world_res_city_of(grid):
    """某块资源地属于哪个联盟城市（静态表里查，找不到返回 0）。"""
    for g, _ty, city in (_WORLD_RES_CACHE.get('tiles') or []):
        if g == grid:
            return city
    return 0


def _ex_world_fleets(payload):
    """MyFleetsResponse / SCFleet / SCMyFleetUpdate -> [WorldFleet dict]。

    三者在 proto-bundle 里都是 `repeated WorldFleet fleets = #1`，encode/
    decode 完全同构，所以一份解析通吃。只留调度要用的字段：
      buildingId(#1) state(#2) durability(#3) cityId(#5) startGridIdx(#8)
      targetGridIdx(#9) curGridIdx(#12) power(#14) maxDura(#15)
    """
    out = []
    for fn, raw in _pb_fields(payload):
        if fn != 1 or not isinstance(raw, (bytes, bytearray)):
            continue
        rec = {}
        for f2, v in _pb_fields(raw):
            if f2 == 1 and isinstance(v, (bytes, bytearray)):
                nm = _pb_str(v)
                if nm:
                    rec['buildingId'] = nm
            elif f2 == 2 and isinstance(v, int):
                rec['state'] = v
            elif f2 == 3 and isinstance(v, int):
                rec['durability'] = v
            elif f2 == 5 and isinstance(v, int):
                rec['cityId'] = v
            elif f2 == 8 and isinstance(v, int):
                rec['startGridIdx'] = v
            elif f2 == 9 and isinstance(v, int):
                rec['targetGridIdx'] = v
            elif f2 == 12 and isinstance(v, int):
                rec['curGridIdx'] = v
            elif f2 == 14 and isinstance(v, int):
                rec['power'] = v
            elif f2 == 15 and isinstance(v, int):
                rec['maxDura'] = v
        if rec.get('buildingId'):
            out.append(rec)
    return out


def _ex_res_fields(payload):
    """MyResFieldsResponse / SCResFieldInfo -> ([(grid, city, type)], maxNum)。

    两者都只有 `#1 ResFieldInfo`：
      ResFieldInfo { repeated ResField fields = #1; int32 maxNum = #3 }
      ResField     { int32 gridIdx = #1; int32 cityId = #2; int32 type = #3 }
    maxNum = 最多能占几块资源地（线上是 11）。
    """
    fields = []
    max_num = 0
    for fn, raw in _pb_fields(payload):
        if fn != 1 or not isinstance(raw, (bytes, bytearray)):
            continue
        for f2, v in _pb_fields(raw):
            if f2 == 1 and isinstance(v, (bytes, bytearray)):
                g = c = t = 0
                for f3, v3 in _pb_fields(v):
                    if f3 == 1 and isinstance(v3, int):
                        g = v3
                    elif f3 == 2 and isinstance(v3, int):
                        c = v3
                    elif f3 == 3 and isinstance(v3, int):
                        t = v3
                if g:
                    fields.append((g, c, t))
            elif f2 == 3 and isinstance(v, int):
                max_num = v
    return fields, max_num


def _challenge_res_field_payload(grid_idx, fleet_ids):
    """ChallengeResFieldRequest 的载荷（proto-bundle 逐字）：
      #1 resFieldGridIdx:int32（required）
      #2 repeated fleetBuildingIds:string
    客户端 SelectTroopPop 点"出征"发的就是这两个字段。线上实测：发完
    20 秒内服务端就推 SCMyFleetUpdate/SCResFieldCampaignBegin，
    舰队所属建筑名（buildingId）原样回传，占到手后 SCResFieldInfo 里
    会多出这一格。
    """
    out = _pb_tag(1, 0) + write_varint(int(grid_idx or 0))
    for fid in (fleet_ids or []):
        b = str(fid).encode('utf-8')
        out += _pb_tag(2, 2) + write_varint(len(b)) + b
    return out


def _give_up_res_field_payload(grid_idx):
    """GiveUpResFieldRequest 的载荷（客户端 LandUtil.toGiveUpResField）：
      #1 resFieldGridIdx:int32
    客户端只传格子号。放弃这块资源地，腾出一个名额给下一块。
    """
    return _pb_tag(1, 0) + write_varint(int(grid_idx or 0))


def _ex_pirates(payload):
    """AllPirateResponse -> [{'uid','type','level','gridIdx','cityId'}]

    schema（1.13.6 bundle 逐字）：
      AllPirateResponse { #1 repeated Pirate pirates; #2 sweepTimes:int32 }
      Pirate { #1 uid:int32; #2 type:int32; #3 level:int32;
               #4 gridIdx:int32; #5 cityId:int32 }
    """
    out = []
    for fn, raw in _pb_fields(payload):
        if fn != 1 or not isinstance(raw, (bytes, bytearray)):
            continue
        rec = {}
        for f2, v in _pb_fields(raw):
            if f2 == 1 and isinstance(v, int):
                rec['uid'] = v
            elif f2 == 2 and isinstance(v, int):
                rec['type'] = v
            elif f2 == 3 and isinstance(v, int):
                rec['level'] = v
            elif f2 == 4 and isinstance(v, int):
                rec['gridIdx'] = v
            elif f2 == 5 and isinstance(v, int):
                rec['cityId'] = v
        if rec.get('uid'):
            out.append(rec)
    return out


def _ex_pirate_kill_records(payload):
    """PirateKillRecordResponse -> {type: maxKilledLevel}

    schema（1.13.4 bundle.59dc0.js 逐字）：
      PirateKillRecordResponse { #1 repeated PirateKillRecord records }
      PirateKillRecord { #1 type:int32; #2 maxKilledLevel:int32 }

    客户端 _findAvailablePirate 只挑 maxPirateKilledLevel(type)+1 那一级
    （更低的已经击杀过、更高的还没解锁），发别的级服务端回
    level not challengeable。机器人以前按 level 最小盲挑，所以一直撞墙。
    """
    out = {}
    for fn, raw in _pb_fields(payload):
        if fn != 1 or not isinstance(raw, (bytes, bytearray)):
            continue
        ty = lv = None
        for f2, v in _pb_fields(raw):
            if f2 == 1 and isinstance(v, int):
                ty = v
            elif f2 == 2 and isinstance(v, int):
                lv = v
        if ty is not None:
            out[int(ty)] = int(lv or 0)
    return out


def _ex_pirate_kill_record(payload):
    """SCPirateKillRecordUpdate { #1 record:PirateKillRecord } -> {type: level}

    每次打赢海盗服务端都会推这一条；它比我们自己推的“+1”更权威，
    收到就按它把记录对齐。
    """
    for fn, raw in _pb_fields(payload):
        if fn == 1 and isinstance(raw, (bytes, bytearray)):
            ty = lv = None
            for f2, v in _pb_fields(raw):
                if f2 == 1 and isinstance(v, int):
                    ty = v
                elif f2 == 2 and isinstance(v, int):
                    lv = v
            if ty is not None:
                return {int(ty): int(lv or 0)}
    return {}


def _challenge_pirate_payload(uid, fleet_ids, city_id):
    """ChallengePirateRequest 载荷（proto-bundle 逐字）：
      #1 uid:int32（海盗 uid）
      #2 repeated fleetBuildingIds:string
      #3 cityId:int32
    线上实测（2026-09-29，文徵明8014）：发出去后服务端推
    SCPirateKillRecordUpdate + SCUpdateItem，AllPirateResponse 里那条
    海盗消失，MainTaskInfoResponse 的 #119 进度 4 -> 5。
    """
    out = _pb_tag(1, 0) + write_varint(int(uid or 0))
    for fid in (fleet_ids or []):
        b = str(fid).encode('utf-8')
        out += _pb_tag(2, 2) + write_varint(len(b)) + b
    out += _pb_tag(3, 0) + write_varint(int(city_id or 0))
    return out


def _ex_radar_info(payload):
    """RadarInfoResponse / SCRadarUpdate -> radar 快照 dict。

    schema 逐字（客户端 bundle.04ae2.js）：
      RadarInfoResponse { #1 radarInfo:RadarInfo }
      SCRadarUpdate     { #1 info:RadarInfo }
      RadarInfo { #1 level; #2 exp; #3 storedNum; #4 repeated events;
                  #5 nextRefreshTime; #6 fixedEvent:RadarFixedEvent }
      RadarEvent { #1 uid:int64; #2 eventId; #3 color; #4 gridIdx;
                   #6 startTime; #11 createTime; #12 state }
      RadarFixedEvent { #1 eventId; #2 gridIdx; #3 startTime;
                        #4 createTime; #5 state }
    外层包一层 {#1:RadarInfo}，也可能直接是裸 RadarInfo，两种都吃。
    """
    def _event(raw):
        rec = {}
        for f2, v in _pb_fields(raw):
            if f2 == 1 and isinstance(v, int):
                rec['uid'] = v
            elif f2 == 2 and isinstance(v, int):
                rec['eventId'] = v
            elif f2 == 3 and isinstance(v, int):
                rec['color'] = v
            elif f2 == 4 and isinstance(v, int):
                rec['gridIdx'] = v
            elif f2 == 5 and isinstance(v, int):
                rec['reward'] = v
            elif f2 == 6 and isinstance(v, int):
                rec['startTime'] = v
            # #7~#10 是事件类型标志，与竞品 radar 配置一一对应。
            # 之前整段跳过 -> 把「要打仗的」和「跑腿的」当成同一种处理。
            elif f2 == 7 and isinstance(v, int):
                rec['pirate'] = v
            elif f2 == 8 and isinstance(v, int):
                rec['refugee'] = v
            elif f2 == 9 and isinstance(v, int):
                rec['collectRes'] = v
            elif f2 == 10 and isinstance(v, int):
                rec['citySpy'] = v
            elif f2 == 11 and isinstance(v, int):
                rec['createTime'] = v
            elif f2 == 12 and isinstance(v, int):
                rec['state'] = v
        return rec

    def _fixed(raw):
        rec = {'fixed': True, 'uid': RADAR_FIXED_UID}
        for f2, v in _pb_fields(raw):
            if f2 == 1 and isinstance(v, int):
                rec['eventId'] = v
            elif f2 == 2 and isinstance(v, int):
                rec['gridIdx'] = v
            elif f2 == 3 and isinstance(v, int):
                rec['startTime'] = v
            elif f2 == 4 and isinstance(v, int):
                rec['createTime'] = v
            elif f2 == 5 and isinstance(v, int):
                rec['state'] = v
        return rec

    def _info(raw):
        sub = {}
        for f2, v in _pb_fields(raw):
            if f2 == 1 and isinstance(v, int):
                sub['level'] = v
            elif f2 == 2 and isinstance(v, int):
                sub['exp'] = v
            elif f2 == 3 and isinstance(v, int):
                sub['storedNum'] = v
            elif f2 == 4 and isinstance(v, (bytes, bytearray)):
                sub.setdefault('events', []).append(_event(v))
            elif f2 == 5 and isinstance(v, int):
                sub['nextRefreshTime'] = v
            elif f2 == 6 and isinstance(v, (bytes, bytearray)):
                sub['fixedEvent'] = _fixed(v)
        return sub

    for fn, raw in _pb_fields(payload):
        if fn == 1 and isinstance(raw, (bytes, bytearray)):
            cand = _info(raw)
            if cand.get('events') or cand.get('fixedEvent') \
                    or 'level' in cand:
                return cand
    flat = _info(payload)
    if flat.get('events') or flat.get('fixedEvent') or 'level' in flat:
        return flat
    return {}


def _radar_send_fleets_payload(uid, fleet_ids):
    """RadarSendFleetsRequest 载荷（客户端 bundle 逐字）：
      #1 uid:int64（固定事件不带，用 FIXED_UID=1 占位）
      #2 repeated fleetBuildingIds:string
    客户端 RadarAuto.ts 固定事件发 {fleetBuildingIds:[id]}，普通事件带 uid。
    """
    out = bytearray()
    if uid and int(uid) != RADAR_FIXED_UID:
        out += _pb_tag(1, 0) + write_varint(int(uid))
    for fid in (fleet_ids or ()):
        b = str(fid).encode('utf-8')
        out += _pb_tag(2, 2) + write_varint(len(b)) + b
    return bytes(out)


def _radar_get_reward_payload(uid):
    """RadarGetRewardRequest 载荷：固定事件空包，普通事件 {uid:int64}。"""
    if not uid or int(uid) == RADAR_FIXED_UID:
        return b''
    return _pb_tag(1, 0) + write_varint(int(uid))


def _fmt_secs(sec):
    """把秒数写成人话：'75 分钟' / '1 小时 15 分' / '30 秒'。"""
    try:
        sec = int(sec or 0)
    except Exception:
        return ''
    if sec <= 0:
        return ''
    if sec < 60:
        return '%d 秒' % sec
    if sec < 3600:
        return '%d 分钟' % int(round(sec / 60.0))
    h, m = divmod(int(round(sec / 60.0)), 60)
    return ('%d 小时' % h) if not m else ('%d 小时 %d 分' % (h, m))


def _next_day_ts():
    """本地时区「明天 0 点」的时间戳。用来做按天刷新的冷却。

    广告免费加速次数是按自然天刷新的，被拒后不该 30 分钟就重试 —— 那会
    在一天里反复撞墙。直接静默到明天。
    """
    try:
        t = time.localtime()
        return time.mktime((t.tm_year, t.tm_mon, t.tm_mday + 1,
                            0, 0, 0, 0, 0, -1))
    except Exception:
        return time.time() + 6 * 3600


def _bld_ts(v, key):
    """建筑开工/完工时间戳（秒）。服务端有时给毫秒，统一归一。"""
    try:
        t = int((v or {}).get(key) or 0)
    except Exception:
        t = 0
    if t > 10 ** 12:
        t //= 1000
    return t


def _bld_left_secs(v):
    """建筑还要多久完工（秒）；没在施工返回 0。"""
    fin = _bld_ts(v, 'finish')
    if not fin:
        return 0
    return max(0, fin - int(time.time()))


def _bld_need_secs(v):
    """这一次建造/升级本身要多久（秒）= finish - start；缺一个就返回 0。

    这是最准的“需要多少时间” —— 配置里的 costTime 只是基准值，
    服务端会因为加速/加成把 finish 提前，直接读差值不会说谎。
    """
    st = _bld_ts(v, 'start')
    fin = _bld_ts(v, 'finish')
    if st and fin and fin > st:
        return fin - st
    return 0


def _radar_view(ri, note='', floor=None):
    """把雷达快照整理成面板能直接渲染的 dict。"""
    ri = dict(ri or {})

    def _ev(e):
        st = int(e.get('state') or 0)
        _k, _kn, _kc = _radar_kind(e)
        return {'uid': int(e.get('uid') or 0),
                'eventId': int(e.get('eventId') or 0),
                'gridIdx': int(e.get('gridIdx') or 0),
                'state': st,
                'stateText': RADAR_EVENT_STATE.get(st, ''),
                'fixed': bool(e.get('fixed')),
                # 事件类型（竞品 radar 分类）+ 是否要打仗，面板直接显示
                'kind': _k,
                'kindName': _kn,
                'combat': _kc,
                'reward': int(e.get('reward') or 0),
                # 原始类型标志 + 实际出现的键名：用来观测游戏到底有没有
                # 下发 #7~#10（flagKeys 为空 = 这一帧一个标志都没有）。
                'flags': {k: int(e.get(k) or 0)
                          for k in ('pirate', 'refugee', 'collectRes',
                                    'citySpy')},
                'flagKeys': sorted(k for k in ('pirate', 'refugee',
                                               'collectRes', 'citySpy')
                                   if k in e),
                'color': int(e.get('color') or 0)}

    evs = [_ev(e) for e in (ri.get('events') or [])]
    fx = ri.get('fixedEvent')
    return {'level': int(ri.get('level') or 0),
            'exp': int(ri.get('exp') or 0),
            'storedNum': int(ri.get('storedNum') or 0),
            'events': evs,
            'initCount': len([e for e in evs if e['state'] == 1]),
            'doneCount': len([e for e in evs if e['state'] == 4]),
            'fixedEvent': _ev(fx) if fx else None,
            # 失败学习出的 eventId 战力门槛（面板展示用）
            'floors': {str(k): int(v or 0)
                       for k, v in (floor or {}).items()},
            'note': note or ''}


def _ex_email_box(payload):
    """EmailBoxResponse -> {total, new, ungot}

    schema 逐字（1.13.6 bundle.59dc0.js）：
      EmailBoxResponse { #1 repeated email:EmailDetail, #2 total:int32 }
      EmailDetail { #1 emailId:int64, #2 subject:string, #4 emailType,
                    #5 status:int32, #6 sender, #7 sendTime, #8 content,
                    #9 attachment:DispAttachment, #10 got:bool,
                    #11 tmpId, #12 repeated tmpParams, #13 scenarioId }
      EmailStatus: ES_READ=1, ES_NEW=2
    没有 QuickGotReadEmailResponse —— 一键领邮件成功也是回 EmailBoxResponse。
    """
    out = {'total': 0, 'new': 0, 'ungot': 0, 'ungotIds': []}
    for fn, raw in _pb_fields(payload):
        if fn == 2 and isinstance(raw, int):
            out['total'] = raw
        elif fn == 1 and isinstance(raw, (bytes, bytearray)):
            status = 0
            has_att = False
            got = False
            eid = 0
            for f2, v2 in _pb_fields(raw):
                if f2 == 1 and isinstance(v2, int):
                    eid = v2
                elif f2 == 5 and isinstance(v2, int):
                    status = v2
                elif f2 == 9 and isinstance(v2, (bytes, bytearray)):
                    has_att = True
                elif f2 == 10 and isinstance(v2, int):
                    got = bool(v2)
            if status == 2:
                out['new'] += 1
            if has_att and not got:
                out['ungot'] += 1
                if eid:
                    out['ungotIds'].append(eid)
    return out


def _ex_new_email(payload):
    """SCNewEmail -> {emailId, subject, status}

    schema（1.13.6 bundle）：SCNewEmail { #1 email:EmailDetail }
    EmailDetail: #1 emailId, #2 subject, #5 status（1=READ, 2=NEW）
    服务端在来新邮件时主动推这个，用来即时补发一键领取。
    """
    out = {'emailId': 0, 'subject': '', 'status': 0}
    for fn, raw in _pb_fields(payload):
        if fn == 1 and isinstance(raw, (bytes, bytearray)):
            for f2, v2 in _pb_fields(raw):
                if f2 == 1 and isinstance(v2, int):
                    out['emailId'] = v2
                elif f2 == 2 and isinstance(v2, (bytes, bytearray)):
                    out['subject'] = _pb_str(v2) or ''
                elif f2 == 5 and isinstance(v2, int):
                    out['status'] = v2
    return out


def _ex_campaign_reports(payload):
    """CampaignReportsResponse -> {total, reports, ungot, ungotIds}

    schema（1.13.6 bundle）：
      CampaignReportsResponse { #1 repeated report:CampaignReport,
                                #2 total:int32 }
      CampaignReport { #1 uid:int64, #2 type:int32, #3 win:bool,
                       #4 createTime:int64, #6 received:bool, #7 rewards,
                       #9 read:bool, #12 resField, #13 worldBoss, ... }
    游戏把「世界玩法」的战斗结果放在这个列表里，
    received=false 就是还没领奖励。
    """
    out = {'total': 0, 'reports': 0, 'ungot': 0, 'ungotIds': []}
    for fn, raw in _pb_fields(payload):
        if fn == 2 and isinstance(raw, int):
            out['total'] = raw
        elif fn == 1 and isinstance(raw, (bytes, bytearray)):
            out['reports'] += 1
            rid = 0
            received = True
            for f2, v2 in _pb_fields(raw):
                if f2 == 1 and isinstance(v2, int):
                    rid = v2
                elif f2 == 6 and isinstance(v2, int):
                    received = bool(v2)
            if not received:
                out['ungot'] += 1
                if rid:
                    out['ungotIds'].append(rid)
    return out


def _campaign_ids_payload(ids):
    """按战报 ID 补领，对齐客户端单条「领取」。

    QuickGotCampaignReportRequest { #1 repeated campaignId:int64, #2 all:bool }
    客户端按 ID 领取时 all=false，这里补一个 #2=0。
    """
    out = b''
    for cid in (ids or ()):
        out += _pb_tag(1, 0) + write_varint(int(cid) & ((1 << 64) - 1))
    return out + _pb_tag(2, 0) + write_varint(0)


def _arena_item(raw):
    it = {'rankNo': 0, 'power': 0, 'id': 0, 'nickname': '', 'level': 0}
    for f2, v2 in _pb_fields(raw):
        if f2 == 1 and isinstance(v2, int):
            it['rankNo'] = v2
        elif f2 == 2 and isinstance(v2, (bytes, bytearray)):
            it['nickname'] = _pb_str(v2) or ''
        elif f2 == 4 and isinstance(v2, int):
            it['power'] = v2
        elif f2 == 5 and isinstance(v2, int):
            it['id'] = v2
        elif f2 == 7 and isinstance(v2, int):
            it['level'] = v2
    return it


