def _ex_trade_info(payload):
    """TradeInfoResponse -> {cargo, goods, coins, profit}
    schema: #2 player:TradePlayerInfo, #3 cargo:TradePlayerCargo
      TradePlayerInfo  { #1 coins, #2 maxCoins, #3 profit,
                         #4 repeated goods:TradePlayerGoods, #5 buySpeedTimes }
      TradePlayerGoods { #1 pid, #2 goodsId, #3 num, #4 buyPrice, #5 cityId }
      TradePlayerCargo { #1 cargoLv, #2 cityId, #3 moveStartTime,
                         #4 moveEndTime, #5 moveToCityId }
    """
    out = {'period': 0, 'cargo': {}, 'goods': [], 'coins': 0,
           'maxCoins': 0, 'profit': 0,
           'guildTask': {'profit': 0, 'tradeTimes': 0,
                         'gotTaskId': []}}
    for fn, raw in _pb_fields(payload):
        if not isinstance(raw, (bytes, bytearray)):
            if fn == 1 and isinstance(raw, int):
                out['period'] = raw
            continue
        if fn == 2:
            for f2, v2 in _pb_fields(raw):
                if f2 == 1 and isinstance(v2, int):
                    out['coins'] = v2
                elif f2 == 2 and isinstance(v2, int):
                    out['maxCoins'] = v2
                elif f2 == 3 and isinstance(v2, int):
                    out['profit'] = v2
                elif f2 == 4:
                    g = {'pid': 0, 'goodsId': 0, 'num': 0,
                         'buyPrice': 0, 'cityId': 0}
                    for f3, v3 in _pb_fields(v2):
                        if f3 == 1 and isinstance(v3, int):
                            g['pid'] = v3
                        elif f3 == 2 and isinstance(v3, int):
                            g['goodsId'] = v3
                        elif f3 == 3 and isinstance(v3, int):
                            g['num'] = v3
                        elif f3 == 4 and isinstance(v3, int):
                            g['buyPrice'] = v3
                        elif f3 == 5 and isinstance(v3, int):
                            g['cityId'] = v3
                    if g['pid']:
                        out['goods'].append(g)
        elif fn == 3:
            cargo = {'cargoLv': 0, 'cityId': 0, 'moveStartTime': 0,
                     'moveEndTime': 0, 'moveToCityId': 0}
            for f2, v2 in _pb_fields(raw):
                if f2 == 1 and isinstance(v2, int):
                    cargo['cargoLv'] = v2
                elif f2 == 2 and isinstance(v2, int):
                    cargo['cityId'] = v2
                elif f2 == 3 and isinstance(v2, int):
                    cargo['moveStartTime'] = v2
                elif f2 == 4 and isinstance(v2, int):
                    cargo['moveEndTime'] = v2
                elif f2 == 5 and isinstance(v2, int):
                    cargo['moveToCityId'] = v2
            out['cargo'] = cargo
        elif fn == 8:
            out['guildTask'] = _ex_trade_guild_task(raw)
    return out


