def _ex_trade_player(payload):
    """TradeBuyResponse / TradeSellResponse -> TradePlayerInfo 字典

    schema：{ #1 player:TradePlayerInfo }。把 #1 原样包成 _ex_trade_info 认的
    #2，直接复用那一份解析，避免两处字段号各写一遍、改一处漏一处。
    """
    for fn, raw in _pb_fields(payload):
        if fn == 1 and isinstance(raw, (bytes, bytearray)):
            wrapped = _pb_tag(2, 2) + write_varint(len(raw)) + raw
            return _ex_trade_info(wrapped)
