def _ex_season_card(payload):
    """SeasonCardResponse -> {isPaid, gotDaily, customId}"""
    out = {'isPaid': False, 'gotDaily': False, 'customId': []}
    for fn, raw in _pb_fields(payload):
        if fn == 1 and isinstance(raw, int):
            out['isPaid'] = bool(raw)
        elif fn == 2 and isinstance(raw, int):
            out['gotDaily'] = bool(raw)
        elif fn == 3:
            if isinstance(raw, int):
                out['customId'].append(raw)
            elif isinstance(raw, (bytes, bytearray)):
                oo = 0
                while oo < len(raw):
                    try:
                        v, oo = read_varint(raw, oo)
                    except Exception:
                        break
                    out['customId'].append(v)
    return out


def _ex_worker_orders(payload, field=1):
    """居民订单明细 -> [ {...}, ... ]

    结构由官方客户端 1.13.6 的 protobuf 定义和真实抓包共同核对。
    之前几版把字段语义写错，记在这里防止再走弯路：

    同一个 DispWorkerOrder 会出现在两种消息里：
      - OnWaterResponse #3：登录时的完整订单快照
      - SCWorkerOrder   #1：交付后服务端重新推送的完整订单快照
    所以调用方必须传 field=3 或 field=1 指定外层字段号。

    官方客户端 1.13.6 的真实形状：

        SCWorkerOrder { repeated Order order = 1; }

        DispWorkerOrder {
            #1 = index                     订单序号
            #2 = repeated DisplayAsset {
                    #1 = type（0=ITEM, 1=RESOURCE）
                    #2 = id（当前服务端下发的是中文物品名）
                    #3 = num（数量）
                 }
            #3 = workerId                  哪个居民
            #4 = 奖励经验（106 / 85 / 44 / 178 这种量级）
            #5 = isSpecial
            #7 = refreshTime
        }

    真实样本：

        #1 = 1        #3 = 10   #4 = 106   #5 = 0
          #2 { #2='海藻酒' #3=1 }
          #2 { #2='淡水'   #3=2 }
          #2 { #2='鱼油'   #3=1 }

    DisplayAsset.#1 是类型枚举，不是物品 ID；#2 才是 id。当前服务端
    直接下发中文名称，面板按这个名字和背包对账。
    """
    out = []
    for fn, raw in _pb_fields(payload):
        if fn != field or not isinstance(raw, (bytes, bytearray)):
            continue

        rec = {'index': None, 'items': [], 'extra': {}, 'isSpecial': 0,
               'done': False, 'workerId': None, 'textId': None,
               'refreshTime': None}

        for f2, v2 in _pb_fields(raw):
            if isinstance(v2, (bytes, bytearray)):
                if f2 != 2:
                    # 目前只见过 #2 是需求列表；其它子消息原样留着，
                    # 不做猜测性解读（宁可少显示，不要显示错的）。
                    rec['extra']['blob%d' % f2] = v2.hex()
                    continue
                it = {'name': None, 'need': None, 'id': None,
                      'assetType': None}
                for f3, v3 in _pb_fields(v2):
                    if f3 == 2 and isinstance(v3, (bytes, bytearray)):
                        it['name'] = _pb_str(v3)          # 物品名（中文）
                    elif f3 == 3 and isinstance(v3, int):
                        it['need'] = v3                   # 要几个
                    elif f3 == 1 and isinstance(v3, int):
                        # DisplayAsset.#1 是类型枚举（0=物品，1=资源），
                        # **不是物品 ID**。以前把它写进 id 会让库存对账
                        # 误查 0/1 号物品，所以单独保存，对账走中文名。
                        it['assetType'] = v3
                # 只收"有名字"的需求。名字是明文，解不出来说明这帧被截断了，
                # 收下会变成一条"要 0 个 None"的脏数据。
                if it['name'] and it['need'] is not None:
                    rec['items'].append(it)
                continue
            if isinstance(v2, int):
                if f2 == 1:
                    rec['index'] = v2
                elif f2 == 3:
                    rec['workerId'] = v2      # 哪个居民
                elif f2 == 4:
                    rec['textId'] = v2
                elif f2 == 5:
                    rec['isSpecial'] = 1 if v2 else 0
                elif f2 == 7:
                    rec['refreshTime'] = v2
                else:
                    rec['extra'][f2] = v2
        if rec['index'] is None:
            continue
        # done 的判定：这条订单的内容**全空**才算完成。
        # 不能用"我们没解出物品"来推 done —— 那只是这帧不完整，
        # 会让面板把一堆真订单显示成"已完成"。
        rec['done'] = (not rec['items']) and rec['workerId'] is None \
            and rec['textId'] is None
        # 订单本体没有可靠的奖励数值；权威奖励在交付成功的
        # FinishWorkerOrderResponse 中，保留空壳供面板兼容。
        rec['reward'] = {}
        out.append(rec)
    return out


def _attach_have(orders, stock, stock_by_id=None):
    """给每个订单的每个需求物品补上"我现在有几个" -> have。

    为什么不在 _ex_worker_orders 里一次算完：订单推送（SCWorkerOrder）和
    背包快照（AllItemResponse）是**两条独立的推送**，到达时刻不同。
    在解包时算 have 会把"解包那一刻的库存"永久写进订单里，之后背包变了
    面板也不更新；而且如果订单先于背包到达，have 会全是 0 —— 面板就会
    把所有东西都标红，用户以为啥都缺。所以拆成两步：解包只记"要多少"，
    have 每次导出面板数据时按当前库存现算。

    stock:       {物品名: 数量}，来自 resbars() 的实时快照。
    stock_by_id: {物品ID: 数量}，同一份快照的另一视角。

    当前服务端把 DisplayAsset.#2 直接下发成中文名，所以优先按名字
    匹配；stock_by_id 只保留给旧帧/其它协议排查，正常不会命中。
    """
    sbi = stock_by_id or {}
    out = []
    for od in orders or []:
        items = []
        for it in (od.get('items') or []):
            nm = it.get('name')
            need = it.get('need')
            iid = it.get('id')
            have = None
            if iid is not None and iid in sbi:
                have = sbi[iid]
            elif nm:
                have = stock.get(nm)
            items.append({'name': nm, 'need': need, 'id': iid,
                          'have': (have if have is not None else 0)})
        nd = dict(od)
        nd['items'] = items
        # 这单现在能不能交：所有物品的持有量都 >= 需求量
        try:
            nd['ready'] = bool(items) and all(
                (it.get('have') or 0) >= (it.get('need') or 0) for it in items)
        except Exception:
            nd['ready'] = False
        # 缺哪几样（面板拿去标红 / 交给工厂加工）
        nd['missing'] = [it['name'] for it in items
                         if (it.get('have') or 0) < (it.get('need') or 0)]
        out.append(nd)
    return out


def _parse_order_counts(payload, field=1):
    """SCOrderOfTheDay -> {'done': 已完成, 'total': 今日总量}

    结构（big.jsonl 23 帧逐字节核对）：
        #1 子消息 { #1 = 今日已完成订单数, #2 = 下一个奖励档位 }

    实测 #1 从 6 一路涨到 24，#2 是 6 的倍数跟着走
    （6/6 → 12/12 → 18/18 → 24/24 …），也就是"每满 6 单给一次奖励"。
    竞品面板那个 "22/24" 就是这个形态。

    ⚠️ 别把 #2 当"今日订单总量"——它不是总量，是下一个奖励线。
    面板上按 "done/total" 显示是够用的，但含义要说清楚，
    否则以后看到 #1 超过 #2（24/24 之后继续涨）会以为数据错了。
    """
    for fn, raw in _pb_fields(payload):
        if fn == field and isinstance(raw, (bytes, bytearray)):
            v = dict((k, x) for k, x in _pb_fields(raw) if isinstance(x, int))
            return {'done': v.get(1, 0), 'total': v.get(2, 0)}
    return None


def _ex_display_assets_direct(payload, field=1):
    """提取 repeated DisplayAsset -> [{'type','id','name','num'}, ...]

    官方客户端 1.13.6 的 DisplayAsset 是固定三层结构：
        #1 = type
        #2 = id（当前服务端下发明文名称）
        #3 = num

    有些响应直接 repeated DisplayAsset（例如 WeekOrderInfoResponse.order），
    有些则先包一层 DisplayAssetPackage（例如订单奖励、工厂产物）。
    这里处理前者，`_ex_display_asset_package` 只负责拆掉外层。
    """
    out = []
    for fn, raw in _pb_fields(payload):
        if fn != field or not isinstance(raw, (bytes, bytearray)):
            continue
        asset = {'type': None, 'id': None, 'name': None, 'num': None}
        for f2, v2 in _pb_fields(raw):
            if f2 == 1 and isinstance(v2, int):
                asset['type'] = v2
            elif f2 == 2:
                if isinstance(v2, (bytes, bytearray)):
                    text = _pb_str(v2)
                    asset['id'] = text if text is not None else v2.hex()
                    asset['name'] = text
                elif isinstance(v2, int):
                    asset['id'] = v2
            elif f2 == 3 and isinstance(v2, int):
                asset['num'] = v2
        if asset['name'] is None and isinstance(asset['id'], int):
            if asset.get('type') == 1:
                asset['name'] = RESOURCE_NAMES.get(asset['id'])
            else:
                asset['name'] = _ITEM_ID_NAMES.get(asset['id'])
            if not asset['name']:
                asset['name'] = '物品#%d' % asset['id']
        if asset['name'] and asset['num'] is not None:
            out.append(asset)
    return out


def _ex_display_asset_package(payload, field=1):
    """提取 DisplayAssetPackage -> [DisplayAsset, ...]。

    官方结构：
        DisplayAssetPackage { repeated DisplayAsset asset = 1; }
    """
    out = []
    for fn, raw in _pb_fields(payload):
        if fn == field and isinstance(raw, (bytes, bytearray)):
            out.extend(_ex_display_assets_direct(raw, 1))
    return out


def _ex_order_reward(payload):
    """FinishWorkerOrderResponse -> {'EXP': 148, 'GOLD': 540, ...}

    官方客户端 1.13.6 的真实结构：

        FinishWorkerOrderResponse {
            #1 = DisplayAssetPackage {
                #1 = repeated DisplayAsset {
                    #1 = type
                    #2 = id（当前服务端给名字）
                    #3 = num
                }
            }
        }

    旧解析把 #1 当成 {#2=名字, #3=数量}，和真实结构错了一层，
    所以即使订单交付成功，面板也拿不到权威奖励。
    """
    out = {}
    for asset in _ex_display_asset_package(payload, 1):
        key = asset.get('name')
        val = asset.get('num')
        if key and val is not None:
            out[key] = out.get(key, 0) + int(val)
    if out:
        return out

    # 兼容早期抓包/旧服务端的扁平结构，避免升级后回退显示。
    for fn, raw in _pb_fields(payload):
        if fn != 1 or not isinstance(raw, (bytes, bytearray)):
            continue
        direct_key, direct_val = None, None
        for f2, v2 in _pb_fields(raw):
            if f2 == 2 and isinstance(v2, (bytes, bytearray)):
                direct_key = _pb_str(v2)
            elif f2 == 3 and isinstance(v2, int):
                direct_val = v2
        if direct_key and direct_val is not None:
            out[direct_key] = out.get(direct_key, 0) + direct_val
    return out or None


def _ex_week_order(payload):
    """WeekOrderInfoResponse -> [ {'name':物品名, 'need':数量}, ... ]

    ★ 这是居民需求的**真正数据源**，比 SCWorkerOrder 早、且无条件推送。

    怎么找到它的（这段排查记下来，避免以后又摸黑）：
      - SCWorkerOrder 只在"交付成功那一刻"才推（big.jsonl 19 帧，
        每帧前面都紧跟着一条 FinishWorkerOrderResponse）。材料不够 →
        交付不了 → 永远收不到 → 面板永远空。这是个闭环依赖。
      - 服务端**没有**"拉居民订单列表"的接口，但正常登录（游戏客户端
        启动）后会一次性批量发 35 个 Request，把全部面板数据拉一遍。
        其中一个就是 WeekOrderInfoRequest。
      - 它的响应里直接就是中文物品名 + 数量，明文，不需要任何翻译表。

    真实形状（big.jsonl 6 帧逐字节核对，每帧内容一致）：

        WeekOrderInfoResponse {
            #2 = repeated { #1 = 0, #2 = 物品名(中文), #3 = 数量 }
            #3 = 0
        }

    实例：日常用品×7、海藻泥×5、衣服×5、木板×4、淡水×25

    注意 #2 里的 #1 恒为 0，没有信息量，跟 SCWorkerOrder 的 Requirement
    是同一种占位习惯，别拿它当物品 ID。
    """
    out = []
    for fn, raw in _pb_fields(payload):
        if fn != 2 or not isinstance(raw, (bytes, bytearray)):
            continue
        nm, cnt = None, None
        for f2, v2 in _pb_fields(raw):
            if f2 == 2 and isinstance(v2, (bytes, bytearray)):
                nm = _pb_str(v2)
            elif f2 == 3 and isinstance(v2, int):
                cnt = v2
        if nm and cnt is not None:
            out.append({'name': nm, 'need': cnt})
    return out


def _one_item(raw):
    """解一个物品子消息 -> (名称, 数量, 物品ID)。

    子消息的字段布局（实测）：
        #1 名称（bytes，中文）
        #2 数量（varint）
        #3 一个"物品ID"（varint，数量级在百万以上）

    名称**不是**一定在 #1。线上见过只带 ID 不带名字的条目
    （比如 `#1 = 1210001  #2 = 3` 这种），此时：
      - 不能把 ID 当数量（会把 3 个东西显示成 121 万个）；
      - 但也不能整条丢掉（丢掉就漏材料，进度条少项）。
    所以这里的策略是：数量只认 #2；名称先认 #1 的中文串，
    认不到就退回用 ID 换个可读名字（"物品#N"），至少不漏数据。

    ID 会顺手记进 _ITEM_ID_NAMES：同一 ID 在后面某条里带出名字时，
    之前的"物品#N"就能被回填。这是一个锦上添花的自愈机制，
    居民订单**不依赖**它（那边的物品名是服务端明文下发的）。
    """
    nm = None
    cnt = None
    iid = None
    oo = 0
    while oo < len(raw):
        try:
            k2, oo2 = read_varint(raw, oo)
        except Exception:
            break
        f2, w2 = k2 >> 3, k2 & 7
        oo = oo2
        if w2 == 0:
            try:
                v2, oo = read_varint(raw, oo)
            except Exception:
                break
            if f2 == 2:
                cnt = v2
            elif f2 == 3:
                iid = v2          # 只当 ID 用，绝不能当数量
        elif w2 == 2:
            try:
                l2, oo = read_varint(raw, oo)
            except Exception:
                break
            r2 = raw[oo:oo + l2]
            oo += l2
            if f2 == 1:
                try:
                    t2 = r2.decode('utf-8')
                    if t2 and all(c.isprintable() for c in t2):
                        nm = t2
                except Exception:
                    pass
        elif w2 == 5:
            oo += 4
        elif w2 == 1:
            oo += 8
        else:
            break
    if nm and iid is not None:
        _ITEM_ID_NAMES[iid] = nm
    if not nm and iid is not None:
        nm = _ITEM_ID_NAMES.get(iid) or ('物品#%d' % iid)
    return nm, cnt, iid


def _ex_items(payload):
    """从 AllItemResponse 里提取 [(物品名, 数量, 物品ID), ...]

    实测结构（**嵌套**的，外层是 repeated 子消息）：
        0a0c 0a06 e6b1bde6b2b9 10 b0ea01   ->  汽油 30000
        ^^^^ ^^^^ ^^^^^^^^^^^^ ^^ ^^^^^^
        外层      内层#1(名称)   内层#2(数量)
        #1  len=12
             #1 len=6 '汽油'
             #2 30000

    也就是说：#1 里包着一个子消息，子消息的 #1 是名称、#2 是数量。
    （早期我去掉外层前缀手工拼 hex，误以为结构是平铺的，
      结果线上真数据一条都解不出来——`got: []`。）
    """
    out = []
    o = 0
    while o < len(payload):
        try:
            k, o2 = read_varint(payload, o)
        except Exception:
            break
        fn, wt = k >> 3, k & 7
        o = o2
        if wt != 2:
            if wt == 0:
                try:
                    _, o = read_varint(payload, o)
                except Exception:
                    break
                continue
            break
        try:
            ln, o = read_varint(payload, o)
        except Exception:
            break
        raw = payload[o:o + ln]
        o += ln
        if fn != 1:
            continue
        nm, cnt, iid = _one_item(raw)
        if nm and cnt is not None:
            out.append((nm, cnt, iid))
    return out


# 物品 ID -> 中文名。
# 客户端有完整表（config_cn 那个 bundle 里的 ItemCfg），服务端协议里
# **不带**这张表。但 AllItemResponse 的背包条目里同时有中文名和数字 ID，
# 于是 _one_item 解包时顺手把它学进来 —— 背包里有什么，就认识什么。
# 覆盖不到的走"物品#N"兜底，不瞎猜名字。
#
# 注意：这张表**不是**居民订单的必需品。订单里的物品名是服务端明文
# 下发的中文（见 _ex_worker_orders 的注释），当初以为要靠 ID 翻译，
# 是走了一段弯路。留着它是因为丢弃的 ID 信息在排查时有价值。
_ITEM_ID_NAMES = {}


def _resource_lines(payload):
    """资源响应 -> ['金币：791,961', '钻石：12,445', ...]"""
    out = []
    b = payload
    o = 0
    while o < len(b):
        k, o = read_varint(b, o)
        fn, wt = k >> 3, k & 7
        if wt != 2:
            if wt == 0:
                _, o = read_varint(b, o); continue
            break
        ln, o = read_varint(b, o)
        raw = b[o:o + ln]; o += ln
        if fn != 1:
            continue
        rid = cnt = None
        oo = 0
        while oo < len(raw):
            k2, oo = read_varint(raw, oo)
            f2, w2 = k2 >> 3, k2 & 7
            if w2 == 0:
                v2, oo = read_varint(raw, oo)
                if f2 == 1:
                    rid = v2
                elif f2 == 2:
                    cnt = v2
            else:
                break
        if rid is not None and cnt is not None:
            nm = RESOURCE_NAMES.get(rid)
            if nm:
                out.append('%s：%s' % (nm, '{:,}'.format(cnt)))
    return out


def friendly_lines(t, payload):
    """把已知语义的响应解成中文可读行"""
    # AllItemResponse 逐项 dump 很长（几十种物品 × 每项 3 行），
    # 默认 60 行会把后面的物品全砍掉 —— 资源进度条会因此少一半材料。
    limit = 300 if t == 'AllItemResponse' else 60
    # 资源类优先走中文格式化（否则会被 named_lines 抢答成 '#1 = 3' 天书）
    if t in ('AllResourceResponse', 'SCUpdateResource', 'SCResource'):
        try:
            out = _resource_lines(payload)
            if out:
                return out[:limit]
        except Exception:
            pass
    named = named_lines(t, payload)
    if named:
        return named[:limit]
    lines = dump_proto(payload)
    try:
        if t in ('AllResourceResponse', 'SCUpdateResource', 'SCResource'):
            out = []
            o = 0
            b = payload
            while o < len(b):
                key, o = read_varint(b, o)
                fn, wt = key >> 3, key & 7
                if wt == 2:
                    ln, o = read_varint(b, o)
                    raw = b[o:o + ln]; o += ln
                    if fn == 1:
                        rid = cnt = None
                        oo = 0
                        while oo < len(raw):
                            k2, oo = read_varint(raw, oo)
                            f2, w2 = k2 >> 3, k2 & 7
                            if w2 == 0:
                                v2, oo = read_varint(raw, oo)
                                if f2 == 1: rid = v2
                                elif f2 == 2: cnt = v2
                            else:
                                break
                        if rid is not None:
                            out.append('%s：%s' % (RESOURCE_NAMES.get(rid, '资源#%s' % rid),
                                                  '{:,}'.format(cnt) if cnt is not None else '?'))
                elif wt == 0:
                    _, o = read_varint(b, o)
                else:
                    break
            if out:
                return out
        if t == 'SCUpdateItem' or t == 'AllItemResponse':
            # 尝试把 itemId/数量 读出来
            out = []
            for ln in lines[:24]:
                out.append(ln)
            return out
    except Exception:
        pass
    return lines


# ---------------- 用户与会话 ----------------
USERS_FILE = os.path.join(BASE, 'users.json')
SESSIONS = {}          # token -> {user, ts}
BIND_TARGET = {}       # username -> 绑定到期时间


def _hash_pw(pw):
    return hashlib.sha256(('fksj$' + pw).encode('utf-8')).hexdigest()


AUTH_LOG = os.path.join(BASE, 'logs', 'auth.log')


def _auth_log(msg):
    try:
        os.makedirs(os.path.dirname(AUTH_LOG), exist_ok=True)
        with open(AUTH_LOG, 'a') as f:
            f.write('[%s] %s\n' % (time.strftime('%m-%d %H:%M:%S'), msg))
    except Exception:
        pass


# ---------------- 游戏渠道登录（官方 App） ----------------
# 只调用已授权的渠道适配服务完成账号鉴权；拿到 openId/token/sign 后，
# 仍由本机按游戏协议构造 LoginRequest，并实际连网关验证。
CHANNEL_UPSTREAM_FILE = os.path.join(BASE, 'channel_upstream.json')
_CHANNEL_UPSTREAM = {'token': '', 'exp': 0}


def _channel_upstream_config():
    cfg = {
        'base': (os.environ.get('CHANNEL_UPSTREAM_BASE') or '').strip(),
        'username': os.environ.get('CHANNEL_UPSTREAM_USER', ''),
        'password': os.environ.get('CHANNEL_UPSTREAM_PASSWORD', ''),
    }
    try:
        with open(CHANNEL_UPSTREAM_FILE, encoding='utf-8') as f:
            saved = json.load(f)
        for key in ('base', 'username', 'password'):
            if saved.get(key):
                cfg[key] = saved[key]
    except Exception:
        pass
    return cfg


def _aes192_cbc_b64(text):
    if _AES is None:
        raise RuntimeError('缺少 pycryptodome，无法生成渠道请求头')
    key = b'Kx9mP2wR5tY8uI3oQ6aS5f6x'
    iv = b'A1b2C3d4E5f6G7h8'
    cipher = _AES.new(key, _AES.MODE_CBC, iv)
    return base64.b64encode(
        cipher.encrypt(_pkcs7_pad(str(text).encode('utf-8'), 16))).decode()


def _channel_headers(username, password):
    fp = 'f0e1d2c3b4a5968778695a4b3c2d1e0f'
    uh = hashlib.md5(str(username).encode()).hexdigest()
    ph = hashlib.md5(str(password).encode()).hexdigest()
    argus = _aes192_cbc_b64(uh + fp)
    gorgon = _aes192_cbc_b64(ph + fp)
    ladon = _aes192_cbc_b64(uh + ph + fp)
    helios = hashlib.md5(
        (uh + ph + fp + argus[:8] + gorgon[:8]).encode()).hexdigest()[:16]
    return {
        'Content-Type': 'application/json',
        'User-Agent': ('Mozilla/5.0 (Windows NT 10.0; Win64; x64) '
                       'AppleWebKit/537.36 (KHTML, like Gecko) '
                       'Chrome/140.0.0.0 Safari/537.36'),
        'Accept': 'application/json, text/plain, */*',
        'X-Argus': argus,
        'X-Gorgon': gorgon,
        'X-Ladon': ladon,
        'X-Helios': helios,
        'X-FP': fp,
    }


class _ChannelUpstreamError(RuntimeError):
    def __init__(self, code, message):
        super().__init__(message)
        self.code = code


def _http_json(url, method='GET', headers=None, body=None, timeout=20):
    data = None
    if body is not None:
        data = json.dumps(body, ensure_ascii=False).encode('utf-8')
    req = urllib.request.Request(url, data=data, method=method,
                                 headers=headers or {})
    with urllib.request.urlopen(req, timeout=timeout) as response:
        parsed = json.loads(response.read().decode('utf-8'))
    if parsed.get('code') != 200:
        raise _ChannelUpstreamError(
            parsed.get('code'),
            parsed.get('msg') or ('上游返回 code=%s' % parsed.get('code')))
    return parsed.get('data')


def _channel_upstream_token(force=False):
    now = time.time()
    if (not force and _CHANNEL_UPSTREAM['token']
            and _CHANNEL_UPSTREAM['exp'] > now):
        return _CHANNEL_UPSTREAM['token']
    cfg = _channel_upstream_config()
    if not cfg['base'] or not cfg['username'] or not cfg['password']:
        raise RuntimeError('渠道上游未配置（base/username/password）')
    data = _http_json(
        cfg['base'].rstrip('/') + '/api/auth/login', 'POST',
        _channel_headers(cfg['username'], cfg['password']),
        {'username': cfg['username'], 'password': cfg['password']})
    token = (data or {}).get('token') or ''
    if not token:
        raise RuntimeError('渠道上游未返回 token')
    _CHANNEL_UPSTREAM['token'] = token
    _CHANNEL_UPSTREAM['exp'] = now + 12 * 3600
    return token


def _channel_upstream_api(path, method='GET', params=None, body=None,
                          retry=True, force_auth=False):
    cfg = _channel_upstream_config()
    url = cfg['base'].rstrip('/') + path
    if params:
        url += '?' + urllib.parse.urlencode(params)
    headers = {
        'Authorization': _channel_upstream_token(force=force_auth),
        'User-Agent': ('Mozilla/5.0 (Windows NT 10.0; Win64; x64) '
                       'AppleWebKit/537.36 (KHTML, like Gecko) '
                       'Chrome/140.0.0.0 Safari/537.36'),
        'Accept': 'application/json, text/plain, */*',
    }
    try:
        return _http_json(url, method, headers, body)
    except _ChannelUpstreamError as e:
        # 上游 token 的实际有效期可能短于本地缓存时间。401 时必须强制重新
        # 登录再重试，否则面板会一直拿过期 token，直到进程重启才恢复。
        if retry and e.code == 401:
            _auth_log('CHANNEL_UPSTREAM token 401 -> force refresh')
            return _channel_upstream_api(
                path, method, params, body, False, force_auth=True)
        if not retry:
            raise
        return _channel_upstream_api(path, method, params, body, False)
    except Exception:
        if not retry:
            raise
        return _channel_upstream_api(path, method, params, body, False)


CHANNEL_CLIENT_INFO = {
    'app_id': '14021517',
    'channel_id': '10769',
    'client_version': '1.9.3',
    'network': '4G',
    'platform': '2',
    'did': os.environ.get('GAME_DID', '00000000000000000000000000000000'),
    'sc': '70000259',
    'biz': '103',
    'origin_version': '1.8.3.78',
}


def _s(field, value):
    raw = str(value).encode('utf-8')
    return _pb_tag(field, 2) + write_varint(len(raw)) + raw


def _m(field, raw):
    return _pb_tag(field, 2) + write_varint(len(raw)) + raw


def _v(field, value):
    return _pb_tag(field, 0) + write_varint(int(value))


def _channel_login_frame(open_id, token, ts, sign, birthday=''):
    info = (
        _s(1, CHANNEL_CLIENT_INFO['app_id'])
        + _s(2, CHANNEL_CLIENT_INFO['channel_id'])
        + _s(3, '')
        + _s(4, CHANNEL_CLIENT_INFO['client_version'])
        + _s(5, CHANNEL_CLIENT_INFO['network'])
        + _s(6, CHANNEL_CLIENT_INFO['platform'])
        + _s(7, CHANNEL_CLIENT_INFO['did'])
        + _s(8, CHANNEL_CLIENT_INFO['sc'])
        + _s(9, '')
        + _s(10, CHANNEL_CLIENT_INFO['biz'])
        + _v(11, 1)
        + _s(12, birthday or '')
        + _s(13, CHANNEL_CLIENT_INFO['origin_version'])
    )
    params = _s(1, open_id) + _s(2, token) + _v(3, ts) + _s(4, sign)
    payload = (
        _s(4, 'zh_CN')
        + _m(6, params)
        + _m(7, info)
        + _v(8, 0)
        + _s(9, 'zh-hans-cn')
    )
    return build_frame('LoginRequest', payload, '00000191').hex()


def _parse_login_response(payload):
    code = None
    player_raw = None
    reason = ''
    for field, value in _pb_fields(payload):
        if field == 1 and isinstance(value, int):
            code = value
        elif field == 2 and isinstance(value, (bytes, bytearray)):
            player_raw = value
        elif field == 3 and isinstance(value, (bytes, bytearray)):
            reason = _pb_str(value) or ''
    player = {}
    if reason:
        player['reason'] = reason
    if player_raw:
        for field, value in _pb_fields(player_raw):
            if field == 1 and isinstance(value, int):
                player['playerId'] = value
            elif field == 2 and isinstance(value, (bytes, bytearray)):
                player['nickname'] = _pb_str(value) or ''
            elif field == 7 and isinstance(value, int):
                player['level'] = value
            elif field == 10 and isinstance(value, int):
                player['power'] = value
            elif field == 12 and isinstance(value, int):
                player['worldId'] = value
    return code, player


def _verify_channel_login(frame_hex):
    ctx = ssl.create_default_context()
    raw = socket.create_connection((HOST, 443), timeout=15)
    sock = ctx.wrap_socket(raw, server_hostname=HOST)
    key = binascii.b2a_base64(os.urandom(16)).strip().decode()
    sock.sendall((
        'GET %s HTTP/1.1\r\nHost: %s\r\nSec-WebSocket-Key: %s\r\n'
        'Sec-WebSocket-Version: 13\r\nUpgrade: websocket\r\n'
        'Origin: https://%s\r\nUser-Agent: %s\r\nConnection: Upgrade\r\n\r\n'
        % (PATH, HOST, key, HOST, UA)).encode())
    handshake = b''
    while b'\r\n\r\n' not in handshake:
        handshake += sock.recv(4096)
    ws_send(sock, bytes.fromhex(frame_hex))
    try:
        for _ in range(5):
            resp = ws_recv(sock, 12)
            if not resp:
                continue
            info = parse_frame(resp)
            if not info:
                continue
            if info['type'] == 'LoginResponse':
                return _parse_login_response(info['payload'])
            if info['type'] in ('PromptResponse', 'ErrorResponse'):
                raise RuntimeError('登录被拒：%s' % info['type'])
        raise RuntimeError('等待 LoginResponse 超时')
    finally:
        try:
            sock.close()
        except Exception:
            pass


def _parse_channel_token(value):
    def decode(candidate, depth=0):
        if depth > 3:
            return None
        if isinstance(candidate, dict):
            return candidate
        if isinstance(candidate, (bytes, bytearray)):
            candidate = candidate.decode('utf-8', 'replace')
        if isinstance(candidate, list):
            for item in candidate:
                found = decode(item, depth + 1)
                if found:
                    return found
            return None
        if not isinstance(candidate, str):
            return None
        text = candidate.strip()
        if not text:
            return None
        for raw in (text, urllib.parse.unquote(text)):
            try:
                parsed = json.loads(raw)
            except Exception:
                parsed = None
            if parsed is not None:
                found = decode(parsed, depth + 1)
                if found:
                    return found
            start, end = raw.find('{'), raw.rfind('}')
            if 0 <= start < end:
                found = decode(raw[start:end + 1], depth + 1)
                if found:
                    return found
            if '&' in raw and '=' in raw:
                pairs = urllib.parse.parse_qs(raw, keep_blank_values=True)
                if pairs:
                    return {k: v[-1] if isinstance(v, list) else v
                            for k, v in pairs.items()}
            parts = raw.split('.')
            if len(parts) == 3:
                try:
                    payload = parts[1] + '=' * (-len(parts[1]) % 4)
                    decoded = base64.urlsafe_b64decode(payload)
                    found = decode(decoded.decode('utf-8', 'replace'), depth + 1)
                    if found:
                        return found
                except Exception:
                    pass
        return {'token': text}

    parsed = decode(value)
    if parsed is None:
        raise RuntimeError('渠道 token 格式无法识别')
    return parsed


def _import_channel_account(owner, source, payload, server=None):
    token_data = _parse_channel_token(payload.get('token'))

    def pick(*names):
        for source in (payload, token_data):
            for name in names:
                value = source.get(name)
                if value not in (None, ''):
                    return value
        return ''

    open_id = str(pick('uid', 'openId', 'openid', 'channelUid') or '').strip()
    sign_token = str(
        token_data.get('signToken') or token_data.get('sign_token')
        or payload.get('signToken') or payload.get('sign_token')
        or token_data.get('token') or payload.get('token') or '')
    ts = int(pick('ts', 'timestamp', 'time') or 0)
    sign = str(pick('sign', 'signature') or '')
    birthday = str(pick('birthday', 'birth') or '')
    accounts = load_accounts()
    if not open_id:
        raise RuntimeError('渠道未返回游戏 UID')
    _require_add_quota(owner, open_id)
    if not sign_token or not ts or not sign:
        # 渠道未返回完整的游戏签名。如果该 UID 已经在面板里，
        # 优先验证并使用已有登录帧；登录帧实测长期有效，可以完成绑定/恢复。
        existing = accounts.get(open_id) or {}
        frame_existing = existing.get('frame') or ''
        if frame_existing:
            code, player = _verify_channel_login(frame_existing)
            if code == 0:
                existing.update({
                    'owner': owner,
                    'enabled': True,
                    'nickname': player.get('nickname') or existing.get('nickname') or open_id,
                    'worldId': int(player.get('worldId') or existing.get('worldId') or 0),
                    'login_source': source,
                    'imported_by': owner,
                    'imported_at': time.time(),
                    'last_capture': time.time(),
                })
                save_account(existing)
                return {
                    'uid': open_id,
                    'nickname': existing.get('nickname') or open_id,
                    'worldId': existing.get('worldId') or 0,
                    'level': player.get('level') or 0,
                    'power': player.get('power') or 0,
                    'isNew': False,
                    'reusedFrame': True,
                }
        raise RuntimeError(
            '渠道未返回完整的游戏登录签名；请先通过抓包导入一次')
    frame = _channel_login_frame(open_id, sign_token, ts, sign, birthday)
    code, player = _verify_channel_login(frame)
    if code != 0:
        _auth_log('CHANNEL login-fail uid=%r source=%s code=%s reason=%r '
                  'tokenLen=%s signLen=%s ts=%s'
                  % (open_id, source, code, player.get('reason'),
                     len(sign_token), len(sign), ts))
        existing = accounts.get(open_id) or {}
        frame_existing = existing.get('frame') or ''
        if frame_existing:
            ec, eplayer = _verify_channel_login(frame_existing)
            if ec == 0:
                existing.update({
                    'owner': owner,
                    'enabled': True,
                    'nickname': eplayer.get('nickname') or existing.get('nickname') or open_id,
                    'worldId': int(eplayer.get('worldId') or existing.get('worldId') or 0),
                    'login_source': source,
                    'imported_by': owner,
                    'imported_at': time.time(),
                    'last_capture': time.time(),
                })
                save_account(existing)
                _auth_log('CHANNEL reuse-frame uid=%r -> OK' % open_id)
                return {
                    'uid': open_id,
                    'nickname': existing.get('nickname') or open_id,
                    'worldId': existing.get('worldId') or 0,
                    'level': eplayer.get('level') or 0,
                    'power': eplayer.get('power') or 0,
                    'isNew': False,
                    'reusedFrame': True,
                }
        raise RuntimeError('游戏网关拒绝登录，code=%s%s' % (
            code, ('：%s' % player.get('reason')) if player.get('reason') else ''))
    nickname = (player.get('nickname') or payload.get('nickname')
                or (server or {}).get('nickname') or open_id)
    world_id = int(player.get('worldId') or 0)
    accs = accounts
    d = accs.get(open_id) or {}
    d.update({
        'uid': open_id,
        'nickname': nickname,
        'frame': frame,
        'enabled': d.get('enabled', True),
        'owner': owner,
        'created': d.get('created', time.time()),
        'last_capture': time.time(),
        'login_source': source,
        'token_ts': ts,
        'imported_by': owner,
        'imported_at': time.time(),
        'worldId': world_id,
    })
    _consume_user_quota(owner, open_id, existing=open_id in accs)
    save_account(d)
    return {
        'uid': open_id,
        'nickname': nickname,
        'worldId': world_id,
        'level': player.get('level') or 0,
        'power': player.get('power') or 0,
        'isNew': open_id not in accs,
    }


def load_users():
    try:
        return json.load(open(USERS_FILE))
    except Exception:
        return {}


