def load_changelog():
    """面板更新记录。changelog.json 优先，读不到就用内置的。"""
    try:
        with open(CHANGELOG_PATH, encoding='utf-8') as f:
            data = json.load(f)
        items = data.get('items') if isinstance(data, dict) else data
        if isinstance(items, list) and items:
            return items
    except Exception:
        pass
    return CHANGELOG_DEFAULT


def save_users(u):
    with open(USERS_FILE, 'w') as f:
        json.dump(u, f, ensure_ascii=False, indent=1)


def _user_quota_state(owner):
    """返回 (unlimited, quota)。unlimited=True 表示该用户不限额。"""
    user = load_users().get(owner) or {}
    if 'quota' not in user:
        return True, 0
    return False, int(user.get('quota') or 0)


def _require_add_quota(owner, uid=None):
    """限额用户额度为 0 时，禁止添加新账号；已存在的账号不受影响。"""
    if uid and uid in load_accounts():
        return
    unlimited, quota = _user_quota_state(owner)
    if not unlimited and quota <= 0:
        raise ValueError('额度为 0，无法添加账号，请联系管理员增加额度')


def _consume_user_quota(owner, uid, existing=False):
    """Reserve one finite quota unit for a new game account."""
    with ACCOUNT_UPDATE_LOCK:
        if uid in load_accounts():
            return
        if existing:
            return
        users = load_users()
        user = users.get(owner) or {}
        if 'quota' not in user:
            return
        quota = int(user.get('quota') or 0)
        if quota <= 0:
            raise ValueError('额度为 0，无法添加账号，请联系管理员增加额度')
        user['quota'] = quota - 1
        users[owner] = user
        save_users(users)


def ensure_admin():
    u = load_users()
    if not u:
        u = {'admin': {'pw': _hash_pw('admin'), 'created': time.time(), 'role': 'admin'}}
        save_users(u)
    return u


def check_login(name, pw):
    u = load_users()
    d = u.get(name)
    return (bool(d) and not d.get('disabled')
            and d.get('pw') == _hash_pw(pw))


# ---------------- 账号存储 ----------------
# 冻结帧缓存：uid -> (frame_hex, 载入时间)
# 目的：账号 JSON 一旦被误删/写坏，仍在内存里的登录帧可以即时恢复，
#       不必等下一次抓包（token 实测长期有效，丢帧才是真正的损失）。
FRAME_STORE = {}
FRAME_FREEZE = os.path.join(BASE, 'frames_frozen.json')


def freeze_save():
    try:
        os.makedirs(BASE, exist_ok=True)
        tmp = FRAME_FREEZE + '.tmp'
        with open(tmp, 'w') as f:
            json.dump({k: v[0] for k, v in FRAME_STORE.items() if v[0]}, f)
        os.replace(tmp, FRAME_FREEZE)
    except Exception:
        pass


def freeze_load():
    try:
        for k, v in json.load(open(FRAME_FREEZE)).items():
            if isinstance(v, str) and v:
                FRAME_STORE[k] = (v, time.time())
    except Exception:
        pass


def account_path(uid):
    return os.path.join(ACCOUNTS_DIR, uid + '.json')


def load_accounts():
    out = {}
    if not os.path.isdir(ACCOUNTS_DIR):
        return out
    for p in glob.glob(os.path.join(ACCOUNTS_DIR, '*.json')):
        if p.endswith('.tmp'):
            continue
        try:
            d = json.load(open(p, encoding='utf-8'))
            out[d['uid']] = d
        except Exception:
            # JSON 损坏（写入中断 / 被截断）时尝试用冻结帧救回
            uid = os.path.basename(p)[:-5]
            fr = FRAME_STORE.get(uid, ('', 0))[0]
            if fr:
                out[uid] = {'uid': uid, 'frame': fr, 'nickname': '', 'enabled': True,
                            'owner': 'admin', 'created': time.time(),
                            'last_capture': time.time(), 'recovered': True}
                print('[RECOVER] 账号文件损坏，已用冻结帧恢复 %s' % uid, flush=True)
    # 内存里有、磁盘上没有的帧 → 回填（防误删）
    for uid, (fr, _t) in list(FRAME_STORE.items()):
        if fr and uid not in out:
            out[uid] = {'uid': uid, 'frame': fr, 'nickname': '', 'enabled': True,
                        'owner': 'admin', 'created': time.time(),
                        'last_capture': time.time(), 'recovered': True}
            try:
                save_account(out[uid])
                print('[RECOVER] 磁盘缺失，已从冻结帧重建 %s' % uid, flush=True)
            except Exception:
                pass
    return out


def save_account(d):
    os.makedirs(ACCOUNTS_DIR, exist_ok=True)
    os.makedirs(UPLOAD_DIR, exist_ok=True)
    # 原子写：避免管理器每 5s 读盘时读到半截 JSON
    p = account_path(d['uid'])
    tmp = p + '.tmp'
    with open(tmp, 'w', encoding='utf-8') as f:
        json.dump(d, f, ensure_ascii=False, indent=1)
    os.replace(tmp, p)
    FRAME_STORE[d['uid']] = (d.get('frame') or '', time.time())


def update_account(uid, updates=None, mutate=None):
    """在账号写锁内合并字段，避免并发保存时旧快照覆盖新配置。"""
    with ACCOUNT_UPDATE_LOCK:
        accs = load_accounts()
        d = accs.get(uid)
        if not d:
            return False, None
        if isinstance(updates, dict):
            d.update(updates)
        if callable(mutate):
            mutate(d)
        save_account(d)
        return True, d


# 任务默认值版本号。改动默认开关时 +1，并在 AccountBot.__init__ 里写迁移。
#   v1 -> v2：联盟科技 / 藏品升级 / 藏品升星 从「默认关」改成「默认开」。
# 用户只要在面板上改过开关（persist_account_task 会抬版本号），就不会被
# 迁移覆盖。
TASKS_VERSION = 4
TASK_DEFAULTS_V2_ON = ('联盟科技', '藏品升级', '藏品升星')
#   v2 -> v3：新增「装备穿戴」自动穿戴/替换（默认开）。
TASK_DEFAULTS_V3_ON = ('装备穿戴',)
#   v3 -> v4：建筑升级从旧版默认关改为常驻自动升级。
# 已有账号按版本迁移打开；用户之后仍可在面板上单独关掉。
TASK_DEFAULTS_V4_ON = ('建筑升级',)


def persist_account_tasks(uid, tasks):
    """把完整任务表写入账号 JSON，不依赖 AccountBot 当前是否在线。"""
    return update_account(uid, updates={'tasks': dict(tasks or {}),
                                        'tasksVersion': TASKS_VERSION})


def persist_account_task(uid, name, on):
    """只改一个开关；即使机器人尚未挂载，也能在断线状态保存。"""
    def mutate(d):
        tasks = d.get('tasks')
        if not isinstance(tasks, dict):
            tasks = {}
        tasks[name] = bool(on)
        d['tasks'] = tasks
        d['tasksVersion'] = TASKS_VERSION
    return update_account(uid, mutate=mutate)


def extract_uid_from_login(hexstr):
    """从登录帧里取出 uid（#6.#1）"""
    try:
        b = bytes.fromhex(hexstr)
        mtl = b[9]
        pl = b[11 + mtl:]
        o = 0
        while o < len(pl):
            key, o = read_varint(pl, o)
            fn, wt = key >> 3, key & 7
            if wt == 2:
                ln, o = read_varint(pl, o)
                raw = pl[o:o + ln]; o += ln
                if fn == 6:
                    o2 = 0
                    while o2 < len(raw):
                        k2, o2 = read_varint(raw, o2)
                        f2, w2 = k2 >> 3, k2 & 7
                        if w2 == 2:
                            l2, o2 = read_varint(raw, o2)
                            r2 = raw[o2:o2 + l2]; o2 += l2
                            if f2 == 1:
                                return r2.decode('ascii', 'replace')
                        elif w2 == 0:
                            _, o2 = read_varint(raw, o2)
                        else:
                            break
            elif wt == 0:
                _, o = read_varint(pl, o)
            else:
                break
    except Exception:
        pass
    return None


# ---------------- 登录帧导入（「账号密码登录」的真正落地路径）----------------
#
# 原理（已实测验证，见 /workspace/疯狂水世界-账密登录机制逆向报告.md）：
#   游戏协议 LoginRequest 里【没有】账号密码字段，只有
#     #6 eworldParams { #1 openId, #2 token, #3 timestamp, #4 sign }
#   sign 由服务端私钥签发，客户端侧无法离线复算（69450+ 组爆破全部失败）。
#
#   但实测发现：真实登录帧可以【原样重放】，且
#     * 26 小时前的旧帧依然有效（token 不过期）
#     * 同一帧可重复登录（10/10）、可并发（3/3）
#     * 只有 openId / token / timestamp 三字段参与 sign 校验
#     * route、帧尾、#8 worldId 均【不在】校验范围内
#
#   所以「加一个账号」= 拿到一帧真实登录帧并落盘。
#   拿帧的两条路：
#     A) 用户在「抓包绑定」页面走一次游戏登录，MITM 自动捕获（现有 Binder 已实现，零成本）
#     B) 用户直接粘贴/上传帧 hex 串，用本模块导入（不需要装证书、不需要抓包环境）
#
def diff_frames(a, b):
    """比对两帧，给出人类可读的差异说明"""
    try:
        ba, bb = bytes.fromhex(a), bytes.fromhex(b)
    except Exception:
        return '帧格式非法'
    if len(ba) != len(bb):
        return '长度不同 %d vs %d' % (len(ba), len(bb))
    diffs = [i for i in range(len(ba)) if ba[i] != bb[i]]
    if not diffs:
        return '完全相同'
    return '%d 字节不同（首个偏移 %d）' % (len(diffs), diffs[0])


def frame_world_id(hexstr):
    """读登录帧里的 #8 worldId（0 表示未指定，由服务端按账号默认区服分配）"""
    try:
        b = bytes.fromhex(hexstr)
        mtl = b[9]
        pl = b[11 + mtl:]
        o = 0
        while o < len(pl):
            key, o2 = read_varint(pl, o)
            fn, wt = key >> 3, key & 7
            if wt == 0:
                v, o = read_varint(pl, o2)
                if fn == 8:
                    return v
            elif wt == 2:
                ln, o = read_varint(pl, o2)
                o += ln
            else:
                break
    except Exception:
        pass
    return None


def frame_eworld(hexstr):
    """解析登录帧的 #6 eworldParams，返回 {openId, token, timestamp}（不含 sign）"""
    out = {'openId': None, 'token': None, 'timestamp': None}
    try:
        b = bytes.fromhex(hexstr)
        mtl = b[9]
        pl = b[11 + mtl:]
        o = 0
        while o < len(pl):
            key, o = read_varint(pl, o)
            fn, wt = key >> 3, key & 7
            if wt == 2:
                ln, o = read_varint(pl, o)
                raw = pl[o:o + ln]; o += ln
                if fn == 6:
                    o2 = 0
                    while o2 < len(raw):
                        k2, o2 = read_varint(raw, o2)
                        f2, w2 = k2 >> 3, k2 & 7
                        if w2 == 2:
                            l2, o2 = read_varint(raw, o2)
                            v2 = raw[o2:o2 + l2]; o2 += l2
                            if f2 == 1:
                                out['openId'] = v2.decode('utf-8', 'replace')
                            elif f2 == 2:
                                out['token'] = v2.decode('utf-8', 'replace')
                        elif w2 == 0:
                            v2, o2 = read_varint(raw, o2)
                            if f2 == 3:
                                out['timestamp'] = v2
                        else:
                            break
            elif wt == 0:
                _, o = read_varint(pl, o)
            else:
                break
    except Exception:
        pass
    return out


def verify_login_frame(hexstr, timeout=12):
    """真连网关重放一次，确认这帧能不能登录。返回 (ok, 消息, 详情)

    这是唯一的权威校验手段 —— 服务端说什么就是什么。
    """
    hs = (hexstr or '').strip().replace(' ', '').replace('\n', '').replace('\r', '')
    if len(hs) < 24 or len(hs) % 2:
        return False, '帧 hex 长度非法', {}
    try:
        raw = bytes.fromhex(hs)
    except Exception:
        return False, '不是合法的 hex 字符串', {}
    info = parse_frame(raw)
    if not info:
        return False, '帧结构非法（长度前缀/版本号不匹配）', {}
    if info['type'] != 'LoginRequest':
        return False, '这不是登录帧（类型为 %s）' % info['type'], {}
    uid = extract_uid_from_login(hs)
    if not uid:
        return False, '帧里读不出 openId', {}

    # 建连/握手的超时也跟着 timeout 缩放 —— 批量导入时用短超时，
    # 避免一帧卡满 15s+10s+12s。正常网关 TLS 握手 1 秒内就完成。
    conn_to = max(3.0, min(15.0, timeout))
    ctx = ssl.create_default_context()
    sock = None
    try:
        raw_s = socket.create_connection((HOST, 443), timeout=conn_to)
        sock = ctx.wrap_socket(raw_s, server_hostname=HOST)
        key = binascii.b2a_base64(os.urandom(16)).strip().decode()
        sock.sendall((
            'GET %s HTTP/1.1\r\nHost: %s\r\nSec-WebSocket-Key: %s\r\nSec-WebSocket-Version: 13\r\n'
            'Upgrade: websocket\r\nOrigin: https://%s\r\nUser-Agent: %s\r\nConnection: Upgrade\r\n\r\n'
            % (PATH, HOST, key, HOST, UA)).encode())
        sock.settimeout(conn_to)
        buf = b''
        while b'\r\n\r\n' not in buf:
            d = sock.recv(4096)
            if not d:
                return False, '网关握手失败', {'uid': uid}
            buf += d
        if b'101' not in buf.split(b'\r\n')[0]:
            return False, '网关拒绝握手: %s' % buf.split(b'\r\n')[0].decode('utf8', 'replace'),
        # 复用 test_applogin.py 里那套经过验证的粘包重组逻辑
        buf = buf.split(b'\r\n\r\n', 1)[1]
        ws_send(sock, raw)
        sock.settimeout(timeout)
        t0 = time.time()
        while time.time() - t0 < timeout:
            try:
                d = sock.recv(65536)
            except socket.timeout:
                break
            if not d:
                break
            buf += d
            while len(buf) >= 2:
                b0, b1 = buf[0], buf[1]
                ln = b1 & 0x7f
                off = 2
                if ln == 126:
                    if len(buf) < 4:
                        break
                    ln = struct.unpack('>H', buf[2:4])[0]; off = 4
                elif ln == 127:
                    if len(buf) < 10:
                        break
                    ln = struct.unpack('>Q', buf[2:10])[0]; off = 10
                if len(buf) < off + ln:
                    break
                fr = buf[off:off + ln]; buf = buf[off + ln:]
                if b0 & 0x0f in (0x9, 0xA):
                    continue
                if b0 & 0x0f == 0x8:
                    return False, '网关主动断开', {'uid': uid}
                g = parse_frame(fr)
                if not g or g['type'] == 'PingResponse':
                    continue
                if g['type'] == 'LoginResponse':
                    pl = g['payload']
                    code, msg = None, ''
                    for ln2 in dump_proto(pl):
                        if ln2.startswith('#1 = '):
                            code = ln2.split('=', 1)[1].strip()
                        elif ln2.startswith('#2 = ') and not msg:
                            msg = ln2.split('=', 1)[1].strip()
                    if b'invalid sign' in pl:
                        return False, '签名校验失败：这帧的凭证已被服务端吊销或来源不合法', {
                            'uid': uid, 'code': code}
                    if code and code != '0':
                        return False, '登录被拒（code=%s %s）' % (code, msg or '凭证可能已失效'), {
                            'uid': uid, 'code': code}
                    # 抠昵称：#2 子消息里的 #2 字符串
                    try:
                        o = 0
                        while o < len(pl):
                            k, o = read_varint(pl, o)
                            f, w = k >> 3, k & 7
                            if w == 2:
                                l, o = read_varint(pl, o)
                                sub = pl[o:o + l]; o += l
                                if f == 2:
                                    oo = 0
                                    while oo < len(sub):
                                        k2, oo = read_varint(sub, oo)
                                        f2, w2 = k2 >> 3, k2 & 7
                                        if w2 == 2:
                                            l2, oo = read_varint(sub, oo)
                                            if f2 == 2:
                                                nick = sub[oo:oo + l2].decode('utf-8', 'replace')
                                            oo += l2
                                        elif w2 == 0:
                                            _, oo = read_varint(sub, oo)
                                        else:
                                            break
                            elif w == 0:
                                _, o = read_varint(pl, o)
                            else:
                                break
                    except Exception:
                        pass
                    return True, '登录成功', {'uid': uid, 'code': code, 'nickname': nick,
                                              'worldId': frame_world_id(hs)}
                elif g['type'] == 'PromptResponse':
                    if b'Invalid' in g['payload']:
                        return False, '服务端判定为非法请求（帧被改写或版本不匹配）', {'uid': uid}
    except Exception as e:
        return False, '校验异常: %s' % e, {'uid': uid}
    finally:
        if sock:
            try:
                sock.close()
            except Exception:
                pass
    return False, '网关无任何响应（帧可能已过期）', {'uid': uid}


_LOGIN_TYPE_B = b'LoginRequest'


def _norm_hex(s):
    """把任意 hex 表现规范化：去掉空格、冒号、0x 前缀、换行等分隔符。"""
    if not s:
        return ''
    s = str(s)
    for ch in (' ', '\t', '\n', '\r', ':', '-', '_', '.', ','):
        s = s.replace(ch, '')
    s = s.replace('0x', '').replace('0X', '')
    return ''.join(c for c in s if c in '0123456789abcdefABCDEF').lower()


def _try_one_frame_at(raw, off):
    """在 raw[off:] 尝试解出一帧。返回 (ok, uid, hexstr, 帧总字节数)。

    不要求帧占满剩余全部字节 —— 这样才能处理多帧粘连。
    """
    n = len(raw)
    if off + 14 > n:
        return False, None, '', 0
    declared = int.from_bytes(raw[off:off + 4], 'big')
    if declared < 20 or declared > 65536:
        return False, None, '', 0
    total = declared + 4
    if off + total > n:
        return False, None, '', 0
    if raw[off + 4] != 2:
        return False, None, '', 0
    tnl = raw[off + 9]
    if tnl != len(_LOGIN_TYPE_B):
        return False, None, '', 0
    if raw[off + 10:off + 10 + tnl] != _LOGIN_TYPE_B:
        return False, None, '', 0
    seg = raw[off:off + total]
    uid = extract_uid_from_login(seg.hex())
    if not uid:
        return False, None, '', 0
    return True, uid, seg.hex(), total


def looks_like_login_frame(raw_or_hex):
    """判断一段 bytes/hex 是不是登录帧。返回 (ok, uid, hexstr)。"""
    if isinstance(raw_or_hex, str):
        hs = _norm_hex(raw_or_hex)
        if len(hs) < 24 or len(hs) % 2:
            return False, None, ''
        try:
            raw = bytes.fromhex(hs)
        except Exception:
            return False, None, ''
    else:
        raw = raw_or_hex
        hs = raw.hex()
    if len(raw) < 18 or len(raw) > 65536:
        return False, None, ''
    ok, uid, seg, _ = _try_one_frame_at(raw, 0)
    if not ok or len(seg) != len(hs):
        return False, None, ''
    return True, uid, seg


def _scan_bytes_for_frames(data, out, seen, ctx=None, max_frames=300):
    """在二进制数据里扫描登录帧。

    先定位 'LoginRequest' 出现位置，往前推 10 字节得到候选帧头，再校验。
    """
    pos = 0
    while True:
        i = data.find(_LOGIN_TYPE_B, pos)
        if i < 0:
            break
        pos = i + 1
        if len(out) >= max_frames:
            break
        start = i - 10
        if start < 0:
            continue
        if data[start + 9] != len(_LOGIN_TYPE_B):
            continue
        ok, uid, hs, _ = _try_one_frame_at(data, start)
        if ok and uid not in seen:
            seen.add(uid)
            rec = {'uid': uid, 'hex': hs}
            if ctx:
                rec.update({k: v for k, v in ctx.items() if v})
            out.append(rec)
    return out


def _scan_line_blocks(line, out, seen, ctx=None, max_frames=300):
    """在一行文本里扫描登录帧，支持多帧粘连。"""
    hx = _norm_hex(line)
    if len(hx) < 24 or len(hx) % 2:
        return
    if len(hx) > 400000:          # 单行超 200KB 不合理，截断防卡死
        hx = hx[:400000]
    raw = bytes.fromhex(hx)
    n = len(raw)
    off, guard = 0, 0
    while off < n - 14 and len(out) < max_frames and guard < 20000:
        guard += 1
        ok, uid, hs, total = _try_one_frame_at(raw, off)
        if ok:
            if uid not in seen:
                seen.add(uid)
                rec = {'uid': uid, 'hex': hs}
                if ctx:
                    rec.update({k: v for k, v in ctx.items() if v})
                out.append(rec)
            off += total
        else:
            off += 2
    return


def _from_hexdump(text, out, seen, max_frames=300):
    """从 tcpdump -X / hexdump -C 风格 dump 里还原字节流。"""
    buf = bytearray()
    for line in text.split('\n'):
        s = line.strip()
        if not s:
            continue
        m = re.match(r'^(0x)?[0-9a-fA-F]{4,16}[:\s]\s*', s)
        if m:
            s = s[m.end():]
        if '|' in s:
            s = s.split('|')[0]
        pairs = re.findall(r'\b[0-9a-fA-F]{2}\b', s)
        if len(pairs) >= 8:
            try:
                buf += bytes.fromhex(''.join(pairs))
            except Exception:
                pass
            continue
        quads = re.findall(r'\b[0-9a-fA-F]{4}\b', s)
        if len(quads) >= 3:
            hx = ''.join(quads)
            if len(hx) % 2 == 0:
                try:
                    buf += bytes.fromhex(hx)
                except Exception:
                    pass
    if buf:
        _scan_bytes_for_frames(bytes(buf), out, seen, None, max_frames)
    return out


def _har_bodies(e):
    """从一个 HAR entry 里挖出所有可能藏字节流的 body 容器。

    ★ 这里是踩过坑的地方，务必看完再改。

    HAR 规范里，请求体和响应体放的地方【不一样】：
        请求 → entry.request.postData.text          ← 客户端发出去的东西
        响应 → entry.response.content.text          ← 服务端返回的东西
    老代码对两侧都去读 `content`，等于：
        request 侧读 request.content  → HAR 里压根没这个字段，永远空
        response 侧读 response.content → 对，但登录帧是【发出去】的
    结果就是：登录帧（send 方向，在 request.postData 里）一帧都读不出来。

    实测对照（真帧 + 三种摆放位置）：
        request.postData.text（标准）    → 0 帧  ★ 漏
        request.content.text（非标）     → 1 帧
        response.content.text（标准）    → 1 帧

    另外，有些抓包工具（尤其国产 App）会把 WebSocket 的每一帧
    拆成一条 entry、或者干脆不用 request/response 而塞在自定义字段里，
    所以这里把所有可能的位置都翻一遍，宁可多翻不可漏翻。
    """
    out = []
    for side in ('request', 'response'):
        side_obj = e.get(side) or {}
        if not isinstance(side_obj, dict):
            continue
        # 标准位置：响应 content / 请求 postData
        for key in ('content', 'postData', 'post_data', 'body'):
            v = side_obj.get(key)
            if isinstance(v, dict):
                out.append(v)
            elif isinstance(v, str) and v:
                out.append({'text': v})
    # 少数工具直接把 content 平铺在 entry 上
    for key in ('content', 'postData', 'post_data'):
        v = e.get(key)
        if isinstance(v, dict):
            out.append(v)
        elif isinstance(v, str) and v:
            out.append({'text': v})
    # _webSocketMessages 是 Chrome/ProxyPin 对 WS 帧的扩展字段
    for m in (e.get('_webSocketMessages') or []):
        if isinstance(m, dict):
            d = m.get('data')
            if isinstance(d, str) and d:
                out.append({'text': d, 'encoding': m.get('encoding') or ''})
    return out


def _har_feed(body, out, seen, max_frames):
    """把一个 body 容器的内容喂给扫描器，文本 / base64 两条路都试。"""
    if len(out) >= max_frames:
        return
    data = body.get('text')
    if data is None:
        data = body.get('data')
    if not isinstance(data, str) or not data:
        return
    enc = (body.get('encoding') or '').lower()
    if enc == 'base64':
        try:
            _scan_bytes_for_frames(base64.b64decode(data), out, seen, None, max_frames)
            return
        except Exception:
            pass
    # 先按文本扫（hex / hexdump / 夹在日志里的 hex）
    _scan_text_for_frames(data, out, seen, None, max_frames)
    if len(out) >= max_frames:
        return
    # 文本扫不出来，再赌一把 base64。
    # ★ 必须做这个兜底：很多工具内联 base64 却不写 encoding 字段。
    s = data.strip()
    if len(s) < 40:
        return
    s2 = ''.join(s.split())          # base64 可能带换行
    if len(s2) % 4:
        return
    if not re.match(r'^[A-Za-z0-9+/]+={0,2}$', s2):
        return
    try:
        raw = base64.b64decode(s2, validate=True)
    except Exception:
        return
    if _LOGIN_TYPE_B in raw:
        _scan_bytes_for_frames(raw, out, seen, None, max_frames)


def _from_har(obj, out, seen, max_frames):
    """从 HAR 结构提取登录帧（请求体/响应体、明文/base64 全覆盖）。"""
    log = (obj or {}).get('log') or {}
    for e in (log.get('entries') or []):
        if len(out) >= max_frames:
            break
        if not isinstance(e, dict):
            continue
        for body in _har_bodies(e):
            if len(out) >= max_frames:
                break
            _har_feed(body, out, seen, max_frames)
    return out


def _from_wsdump_jsonl(rows, out, seen, max_frames):
    """wsdump jsonl：每行带 game_frame 的记录，按 uid 保留最新。"""
    best, order = {}, []
    for o in rows:
        if not isinstance(o, dict):
            continue
        hx = o.get('hex') or ''
        ok, uid, hs = looks_like_login_frame(hx)
        if not ok:
            continue
        gf = o.get('game_frame') or {}
        if isinstance(gf, dict) and gf.get('type') and gf.get('type') != 'LoginRequest':
            continue
        if o.get('dir') not in (None, 'send'):
            continue
        ctx = {'ts': o.get('ts'), 'host': o.get('host')}
        old = best.get(uid)
        if old is None:
            best[uid] = (hs, ctx); order.append(uid)
        elif str(ctx.get('ts') or '') >= str(old[1].get('ts') or ''):
            best[uid] = (hs, ctx)
    for uid in order:
        if len(out) >= max_frames:
            break
        if uid in seen:
            continue
        seen.add(uid)
        hs, ctx = best[uid]
        rec = {'uid': uid, 'hex': hs}
        rec.update({k: v for k, v in ctx.items() if v})
        out.append(rec)
    return out


def unwrap_multipart(raw, content_type=''):
    """从 multipart/form-data 请求体里剥出第一个（或最大的）文件部分。

    ★ 为什么必须做这一步：
      /api/quick_import 收到的是 <input type=file> 或 curl -F 发来的
      multipart 请求体，长这样：

        ------WebKitFormBoundaryXXXX
        Content-Disposition: form-data; name="file"; filename="a.har"
        Content-Type: application/json

        {"log":{"entries":[...]}}
        ------WebKitFormBoundaryXXXX--

      老代码把【整坨】直接 decode 成文本喂给解析器，于是：
        * _try_json() 看到首字符是 '-' 不是 '{' → 返回 None，不走 HAR 路径
        * 退到 _scan_text_for_frames()，而它【只认 hex】→ 认不出 JSON
      结果就是「导入了 HAR，却永远说找不到登录帧」。

      剥出来之后还要挑对 part —— 表单里可能既有文件又有别的字段，
      所以优先返回带 filename 的 part，没有就返回最大的那个。

    返回 bytes（剥不出来就原样返回 raw，保证向后兼容）。
    """
    if not raw:
        return raw
    m = re.search(r'boundary=([^;]+)', content_type or '')
    if not m:
        # 没给 boundary 也尽量兜一下：看正文首行像不像 boundary
        if not raw.startswith(b'--'):
            return raw
        head = raw.split(b'\r\n', 1)[0]
        bnd = head if len(head) > 4 else None
    else:
        bnd = ('--' + m.group(1).strip().strip('"')).encode('latin-1', 'ignore')
    if not bnd:
        return raw
    parts = raw.split(bnd)
    best, best_name = None, None
    for part in parts:
        if b'\r\n\r\n' not in part:
            continue
        head, _, body = part.partition(b'\r\n\r\n')
        if b'filename=' not in head:
            continue
        fn = re.search(rb'filename="([^"]*)"', head)
        name = fn.group(1) if fn else b''
        data = body
        # 去掉尾部 CRLF 和结束标记
        while data.endswith(b'\r\n') or data.endswith(b'--'):
            data = data[:-2] if data.endswith(b'\r\n') else data[:-2]
        if not data:
            continue
        if best is None or len(data) > len(best):
            best, best_name = data, name
    if best is None:
        return raw
    return best


def _try_json(text):
    t = (text or '').strip()
    if not t or t[0] not in '{[':
        return None
    try:
        return json.loads(t)
    except Exception:
        pass
    rows = []
    for line in t.split('\n'):
        line = line.strip()
        if not line or line[0] not in '{[':
            continue
        try:
            rows.append(json.loads(line))
        except Exception:
            continue
    return rows if rows else None


def _scan_text_for_frames(text, out, seen, ctx=None, max_frames=300):
    """在文本里扫帧：hex（含分隔符）、hexdump、base64 全覆盖。"""
    if re.search(r'(0x)?[0-9a-fA-F]{4,16}[:\s]\s*(?:[0-9a-fA-F]{2}\s+){8,}', text):
        _from_hexdump(text, out, seen, max_frames)
        if out:
            return out

    # 按行：整行几乎全是 hex 的，直接滑扫
    for raw_line in text.split('\n'):
        if len(out) >= max_frames:
            break
        s = raw_line.strip()
        if not s:
            continue
        hexcnt = sum(1 for c in s if c in '0123456789abcdefABCDEF')
        if hexcnt < 40:
            continue
        core = s.replace(' ', '').replace(':', '').replace('-', '').replace('\t', '')
        if len(core) < 40:
            continue
        hexish = sum(1 for c in core if c in '0123456789abcdefABCDEF')
        if hexish < len(core) * 0.85:
            continue
        _scan_line_blocks(s, out, seen, ctx, max_frames)
    if out:
        return out

    # 兜底：日志行里夹着 hex（"payload = xxx"）
    for raw_line in text.split('\n'):
        if len(out) >= max_frames:
            break
        s = raw_line.strip()
        if not s:
            continue
        best = ''
        for m in re.finditer(r'[0-9a-fA-F][0-9a-fA-F\s:\-]{38,}', s):
            if len(m.group(0)) > len(best):
                best = m.group(0)
        if best:
            _scan_line_blocks(best, out, seen, ctx, max_frames)
    if out:
        return out

    # base64
    for m in re.finditer(r'[A-Za-z0-9+/]{60,}={0,2}', text):
        if len(out) >= max_frames:
            break
        b64 = m.group(0)
        if len(b64) % 4:
            continue
        try:
            raw = base64.b64decode(b64, validate=True)
        except Exception:
            continue
        if _LOGIN_TYPE_B in raw:
            _scan_bytes_for_frames(raw, out, seen, ctx, max_frames)
    return out


def extract_login_frames(text, max_frames=300):
    """主入口：从任意抓包文件文本里提取登录帧（按 uid 去重）。

    兼容 wsdump jsonl / HAR / 纯 hex / 带分隔符 hex / hexdump / base64 / 混合日志。
    返回的每帧都补齐 tokenTs / worldId / size，便于调用方直接比较新旧。
    """
    out, seen = [], set()
    if not text:
        return out
    obj = _try_json(text)
    if isinstance(obj, dict) and 'log' in obj:
        _from_har(obj, out, seen, max_frames)
    elif isinstance(obj, list) and obj and isinstance(obj[0], dict):
        if any(isinstance(r, dict) and ('game_frame' in r or 'hex' in r) for r in obj):
            _from_wsdump_jsonl(obj, out, seen, max_frames)
    elif isinstance(obj, dict) and 'entries' in obj:
        _from_har(obj, out, seen, max_frames)

    if not out:
        _scan_text_for_frames(text, out, seen, None, max_frames)
    if not out:
        try:
            _scan_bytes_for_frames(text.encode('latin-1', 'ignore'), out, seen, None, max_frames)
        except Exception:
            pass

    # 补齐派生字段
    for r in out:
        try:
            ev = frame_eworld(r['hex'])
            r['tokenTs'] = ev.get('timestamp') or 0
        except Exception:
            r.setdefault('tokenTs', 0)
        try:
            r['worldId'] = frame_world_id(r['hex'])
        except Exception:
            r.setdefault('worldId', 0)
        r['size'] = len(r['hex']) // 2
    return out


def parse_capture_file(text, max_frames=200):
    """从抓包文件里挑出所有 LoginRequest 帧（兼容层封装，带本地账号信息）。"""
    frames = extract_login_frames(text, max_frames=max_frames)
    accs = load_accounts()
    for r in frames:
        r['known'] = r['uid'] in accs
        r['nickname'] = (accs.get(r['uid']) or {}).get('nickname') or ''
        r['owner'] = (accs.get(r['uid']) or {}).get('owner')
    return frames


def import_login_frame(hexstr, owner='admin', nickname=None, world_id=None, verify=True,
                       verify_timeout=12):
    """把一帧真实登录帧导入成账号。返回 (ok, msg, info)

    注意：不修改帧内容。「区服」通过 #8 worldId 实现，实测该字段【不参与签名】。

    verify_timeout 只在 verify=True 时起作用 —— 批量导入请传小值（见
    IMPORT_VERIFY_TIMEOUT），否则一帧最坏能耗掉 37 秒。
    """
    hs = (hexstr or '').strip().replace(' ', '').replace('\n', '').replace('\r', '')
    if len(hs) < 24 or len(hs) % 2 or len(hs) > 65536:
        return False, '帧 hex 长度非法（应在 12~32768 字节之间）', {}
    try:
        raw = bytes.fromhex(hs)
    except Exception:
        return False, '不是合法的 hex 字符串（只能含 0-9a-f）', {}

    info = parse_frame(raw)
    if not info:
        return False, '帧结构非法：长度前缀与实际长度不符，或版本号不是 2', {}
    if info['type'] != 'LoginRequest':
        return False, '这不是登录帧，而是 %s。请在游戏登录瞬间抓包，或粘贴登录帧' % info['type'], {}
    uid = extract_uid_from_login(hs)
    if not uid or len(uid) < 8:
        return False, '帧里读不出 openId（#6.#1 为空）', {}
    if not (10 <= len(uid) <= 64) or not uid.replace('-', '').isalnum():
        return False, 'openId 格式异常: %r' % uid, {}
    try:
        _require_add_quota(owner, uid)
    except ValueError as _qe:
        return False, str(_qe), {'uid': uid}

    ev = frame_eworld(hs)
    if not ev.get('token') or not ev.get('timestamp'):
        return False, '帧里缺少 token 或 timestamp，不是完整的登录帧', {'uid': uid}

    if verify:
        ok, msg, det = verify_login_frame(hs, timeout=verify_timeout)
        if not ok:
            return False, msg, det
        if det.get('nickname'):
            nickname = det['nickname']
        if world_id is None and det.get('worldId'):
            world_id = det['worldId']
    else:
        det = {}

    accs = load_accounts()
    is_new = uid not in accs
    d = accs.get(uid) or {}
    old_owner = d.get('owner')
    # 归属规则（关键）：
    #   - 新账号：归导入者
    #   - 已有账号：只有「无归属」或「就是导入者本人」才写 owner
    #     否则由调用方（接口层）先做权限判断，无权就根本不该走到这里。
    #     超级管理员也不能靠"换个账号上传同一份帧"把别人的号划走。
    if is_new or not old_owner:
        new_owner = owner
    else:
        new_owner = old_owner
    d.update({
        'uid': uid,
        'nickname': nickname or d.get('nickname') or '',
        'frame': hs,
        'enabled': d.get('enabled', True),
        'owner': new_owner,
    })
    if world_id is not None:
        d['worldId'] = world_id
    d.setdefault('created', time.time())
    d['last_capture'] = time.time()
    d['login_source'] = 'import'
    d['token_ts'] = ev.get('timestamp')
    d['imported_by'] = owner
    d['imported_at'] = time.time()
    _consume_user_quota(owner, uid, existing=not is_new)
    save_account(d)

    # 让 Manager 立刻接管（正常情况下 5s 轮询也会自动拉起）
    # ★ 先把旧 bot 摘出来，再在锁外关掉它。
    #   不能在 LOCK 内调 b.disconnect() —— 那要拿 self.lock 还会关 socket，
    #   慢操作放在全局锁里就是给整个面板添堵。
    with LOCK:
        old_bot = MANAGER.bots.pop(uid, None)
    if old_bot is not None:
        try:
            old_bot.disconnect()
        except Exception:
            pass
    return True, ('导入成功' if is_new else '已更新该账号的登录帧'), {
        'uid': uid, 'nickname': d.get('nickname') or '', 'worldId': d.get('worldId'),
        'isNew': is_new, 'oldOwner': old_owner, 'tokenTs': ev.get('timestamp'),
        'board': det,
    }


# ---------------- 绑定器：自动发现新账号 ----------------
class Binder(threading.Thread):
    def __init__(self):
        threading.Thread.__init__(self)
        self.daemon = True
        self.offsets = {}
        self.capture_last = 0.0
        self.new_accounts = []      # 供面板提示

    def run(self):
        while True:
            try:
                files = sorted(glob.glob(CAPTURE_GLOB))
                for path in files:
                    st = os.stat(path)
                    self.capture_last = st.st_mtime
                    off = self.offsets.get(path)
                    if off is None:
                        self.offsets[path] = st.st_size   # 启动时只看新数据
                        continue
                    if st.st_size < off:
                        off = 0
                    if st.st_size == off:
                        continue
                    with open(path) as f:
                        f.seek(off)
                        for line in f:
                            self.on_line(line)
                        self.offsets[path] = f.tell()
            except Exception:
                pass
            time.sleep(2)

    def on_line(self, line):
        try:
            r = json.loads(line)
        except Exception:
            return
        gf = r.get('game_frame') or {}
        if gf.get('type') != 'LoginRequest' or r.get('dir') != 'send':
            return
        uid = extract_uid_from_login(r.get('hex', ''))
        if not uid:
            return
        owner = 'admin'
        for un, exp in BIND_TARGET.items():
            if exp > time.time():
                owner = un
                break
        with ACCOUNT_UPDATE_LOCK:
            accs = load_accounts()
            is_new = uid not in accs
            # 已有账号保留原归属，避免别人的挂机号被顺手劫走
            d = accs.get(uid) or {'uid': uid, 'nickname': '',
                                  'created': time.time(),
                                  'enabled': True, 'owner': owner}
            if d.get('owner'):
                owner = d['owner']
            d['owner'] = owner
            d['frame'] = r['hex']
            d['last_capture'] = time.time()
            d['nickname'] = d.get('nickname') or ''
            if not d.get('worldId'):
                w = frame_world_id(r['hex'])
                if w:
                    d['worldId'] = w
            save_account(d)
        freeze_save()
        if is_new:
            self.new_accounts.append({'uid': uid, 'at': time.time()})
            print('[BIND] 发现新账号 %s' % uid, flush=True)


BINDER = Binder()


# ---------------- 单账号机器人 ----------------
class AccountBot(threading.Thread):
    def __init__(self, rec):
        threading.Thread.__init__(self)
        self.daemon = True
        self.uid = rec['uid']
        self.nickname = rec.get('nickname', '')
        self.frame_hex = rec['frame']
        self.world_id = rec.get('worldId') or 0
        self.enabled = rec.get('enabled', True)
        self.cred_state = 'ok'        # ok | stale | invalid | unknown
        self.cred_note = ''
        self.frame_ts = 0             # 登录帧的签发时间（服务端时间戳，ms）
        try:
            ev = frame_eworld(self.frame_hex)
            self.frame_ts = int((ev.get('timestamp') or 0) / 1000)
        except Exception:
            pass
        self.lock = threading.Lock()
        self.online = False
        self.connects = 0
        self.last_error = ''
        self.last_recv = 0
        self.last_ping = 0
        self.session_started = 0
        self.last_disconnect = {}
        self.close_streak = 0
        self.next_retry = 0
        self.paused = False
        self.sock = None
        self.frames = []
        self.counters = {}
        self.latest = {}
        self.player = {}
        self.tasks = {t[0]: True for t in TASK_DEFS}      # 任务开关
        self.tasks.setdefault('领主线任务奖励', True)
        for _rn, (_tn, _rt, _rf, _ri) in REACTIONS.items():
            self.tasks.setdefault(_tn, True)
        self.tasks.setdefault('收取建筑产出', True)      # 已实测有效
        self.tasks.setdefault('农田收获', True)          # 已实测有效
        # 建筑完工改为到 buildFinishTime 后主动提交，不再依赖响应式推送。
        self.tasks.setdefault('完成建筑升级', True)
        # 主动升级默认开；只对已知可升建筑发请求，缺料时先交给工厂备料。
        self.tasks.setdefault('建筑升级', True)
        # 建筑加速（正在施工的楼）：广告免费（默认开）、加速器 / 钻石会花资源
        # （默认关）。用户 2026-10-02 要求：看广告加速要能自动过广告，加速器
        # 和钻石加速各给一个开关。协议与客户端 SpeedUpPopVO 一致。
        self.tasks.setdefault('建筑加速-广告', True)     # WatchAdv+SpeedUpUpgrade(type=ADV)
        self.tasks.setdefault('建筑加速-加速器', False)   # 消耗加速器道具
        self.tasks.setdefault('建筑加速-钻石', False)     # 消耗钻石
        self.tasks.setdefault('完成居民订单', True)      # 已从 TASK_DEFS 移出，见调度处动态发
        self.tasks.setdefault('联盟募兵', True)          # 只在主线 #113 时发，且需已有城市列表
        # 联盟里另外三件“每天该做但不会自动做”的事：领联盟礼包、领职级礼包、
        # 升联盟科技。前两个不花资源，默认开；科技会烧公会科技点，默认关。
        self.tasks.setdefault('联盟礼包', True)
        self.tasks.setdefault('职级礼包', True)
        # 公会科技点 / 联盟职级科技点只能用来点科技，没有第二种用途，
        # 所以默认开。世界战斗（type=世界）和职级科技（type=职级）都在
        # 同一份 GuildTechInfoResponse 里，按等级从低到高轮着升。
        self.tasks.setdefault('联盟科技', True)         # 消耗公会科技点
        self.tasks.setdefault('满仓自动消耗', True)      # 收到"仓库满了"才触发，升级建筑花掉资源
        # 舰队维修（对标竞品「自动维修」）。游戏机制原文：
        #   「舰队空闲时耐久低于维修阈值就自动修满，消耗汽油。」
        #   「耐久低于 1600 打城战/货轮/世界BOSS 会掉战力，低于 1000 不会被
        #     派去攻城。」
        # 只修 state==1（在家待命）且耐久低于阈值的舰队；移动 / 驻守 /
        # 出征的一律不碰 —— 半路把人叫回来修是负收益。默认开、阈值 1600，
        # 每支舰队 60 秒最多修一次，避免刷接口。
        self.tasks.setdefault('舰队维修', True)          # RepairFleetRequest
        self.repair_threshold = int(rec.get('repairThreshold') or 1600)
        self.repair_last = 0        # 发维修请求的节流（每 60 秒上限）
        self.repair_note_at = 0     # 上次"无需维修"诊断的时间，防刷屏
        self.tasks.setdefault('收工厂成品', True)        # 实测有效
        self.tasks.setdefault('工厂生产', True)          # 实测有效
        # 装备生产：主线 #124「生产1件装备」——给装备厂排产 + 到点取件。
        self.tasks.setdefault('装备生产', True)
        # 主线看门狗：主线卡太久就复位相关任务、清冷却，逼一次重试。
        self.tasks.setdefault('主线看门狗', True)
        # 兼容旧开关名：老配置/老前端里存的是「英雄升星」，
        # 现在这项已按竞品改名「自动升星」。如果用户本地存过这个开关，
        # 直接把值继承过去，免得升级后发现自己开着的东西"没了"。
        if '英雄升星' in self.tasks:
            _legacy_star = bool(self.tasks.pop('英雄升星'))
            self.tasks.setdefault('自动升星', _legacy_star)
        # ---- 英雄任务（对标竞品 14 项）----
        # 会消耗不可逆资源的三项默认**关**（用户明确要求）：
        #   专武升星   —— 烧碎片
        #   自动招募   —— 烧招募券/钻石（way 可配）
        #   徽章强化   —— 分解装备
        self.tasks.setdefault('一键委任', True)
        self.tasks.setdefault('自动升级', True)
        self.tasks.setdefault('自动升星', True)          # 原「英雄升星」改名对齐竞品
        # 英雄成长任务的服务端拒绝冷却。Lv.6 前本地会直接跳过；
        # 若仍收到 feature locked（等级/引导状态不同步），再静默一段时间。
        self.hero_growth_deny = 0
        self.hero_material_note = {}
        self.tasks.setdefault('技能升级', True)
        self.tasks.setdefault('技能进阶', True)
        self.tasks.setdefault('专武升级', True)
        self.tasks.setdefault('专武升星', False)         # ⚠️ 烧碎片，默认关
        self.tasks.setdefault('装备强化', True)
        # 徽章强化会**分解其它徽章**换经验（不是装备），不可逆，默认关。
        self.tasks.setdefault('徽章强化', False)         # ⚠️ 分解徽章，默认关
        self.tasks.setdefault('自动看技能视频', True)
        self.tasks.setdefault('自动招募', False)         # ⚠️ 烧招募券，默认关
        self.tasks.setdefault('碎片集齐招募', True)      # 不烧券，把集齐的碎片兑现
        self.tasks.setdefault('免费招募', True)          # 免费次数，不花资源
        self.tasks.setdefault('招募积分奖励', True)
        # 「指定英雄」白名单：留空 = 全部英雄。用户选择"可多选白名单"。
        self.hero_watch = list(rec.get('heroWatch') or [])
        # 「英雄品级筛选」：留空 = 不限品级。多选，存品级字符串
        # （'RED' / 'ORANGE' / 'PURPLE' / 'BLUE' / 'GREEN'）。
        # 作用在 hero_watch 之后 —— 先按名字圈人，再按品级收窄。
        self.hero_quality_filter = list(rec.get('heroQualityFilter') or [])
        # 品级的"用户标注 + 聊天自学习"覆盖层。优先级高于内置 HERO_QUALITY，
        # 因为内置表会滞后于游戏版本（新英雄），而这两条路径都是实时的。
        self.hero_quality_extra = dict(rec.get('heroQualityExtra') or {})
        # 自学习的"观测次数"：某个英雄被聊天广播确认过几次。
        # 只做统计展示用，不参与判定 —— 品级是确定的，不需要投票。
        self.hero_quality_seen = dict(rec.get('heroQualitySeen') or {})
        # 招募方式（RECRUIT_* 枚举）。0 = 免费。改这个值请先确认枚举含义。
        self.recruit_way = int(rec.get('recruitWay') or 0)
        # 委任槽位 / 装备 uid / 徽章 uid：从对应响应里解析，没解析到就跳过
        self.appoint_slots = []
        self.appoint_heroes = {}
        self.equip_uids = []
        self.equip_levels = {}
        self.badge_uids = []
        # 全量装备/徽章快照（uid -> 明细）。自动穿戴/替换要按品级、星级、
        # 等级、职业挑"数值最高"，光有 uid 列表不够。
        self.equips_by_uid = {}       # {uid: {equipId,level,star,attrs}}
        self.badges_by_uid = {}       # {uid: {badgeId,level,exp,star,attr}}
        # 上阵英雄（GetFormationResponse / SCFormationUpdate 的 mainline 编队）
        # heroId 列表。自动穿戴只动这些人；拿不到编队时回退到战力前 N。
        self.formation_heroes = []
        self.formation_last = 0       # 上次收到编队快照的时间
        # 新玩法模块的同步数据（从各模块的 *InfoResponse 宽松解析而来）
        # 结构没 schema 可对照，所以先存原始候选，等线上解锁后收紧。
        self.trial_raids = []       # 试炼副本 raidId 列表
        self.trial_live = []        # 有进度的副本（#2>0，值得挑战的）
        self.trial_data = []        # 完整记录 [{id,val,a,b}]
        self.trial_stage = {}       # {raidId: 已通关层}
        self.trial_challenge_deny = {}   # {raidId: 挑战失败冷却截止}
        self.trial_challenge_try = 0     # 最近一次挑战的 raidId（被拒时拉黑它）
        self.trial_sweep_day = ''        # 扫荡记录归属的日期
        self.trial_sweep_done = set()    # 当天已扫荡的 raidId
        self.item_counts = {}       # SCUpdateItem 的实时物品数量覆盖层
        self.league_rivals = []     # 积分赛候补对手 playerId
        self.league_rival = None    # 当前选中的对手
        self.league_info = {}        # LeagueInfoResponse 快照（dan/段位等）
        self.league_rank = []        # LeagueRankResponse 解析出的对手列表
        self.league_deny = {}        # {playerId: 挑战冷却}
        self.league_last = 0
        self.exp_raids = []         # 远征副本 raidId 列表
        self.exp_stage = {}         # {raidId: 已通关层}
        # 协议探针的收帧队列。None = 未开探针（正常路径，零开销）；
        # 列表 = /api/probe 正在等回包，on_frame 会把帧抄进来。
        self.probe_inbox = None
        # 探针进行中的“让路”标志：置位后主循环暂停跑任务、专职读 sock。
        # 为什么需要：主循环是单线程“发一条 -> 睡觉 -> 读一帧”，探针靠
        # on_frame 旁路收帧；如果账号正卡在一长串 sleep 里，8~25 秒窗口
        # 内什么也读不到，看起来就像“服务端没有这份数据”——线上已经因此
        # 误判过一批模块（EquipsResponse / AllItemResponse 实际都有）。
        self.probe_hold = False
        self.probe_hold_until = 0
        # 自增 route 序号（英雄操作批量发时防撞号）
        self._route_seq = 0
        self.tasks.setdefault('农田播种', True)          # 实测有效 FarmPlantRequest
        self.tasks.setdefault('闯关', True)              # ChallengeStageRequest{#1:层数}
        self.tasks.setdefault('竞技场挑战', True)        # 实测载荷 {#1:排名,#2:255}
        self.tasks.setdefault('英雄预览', True)
        self.tasks.setdefault('公会信息', True)
        # ---- 新玩法模块（对标竞品，默认全关）----
        # 为什么默认关：这几个都会**改账号状态**（开启自动化、打副本消耗次数、
        # 积分赛会真的开战）。线上实测它们的返回是 "feature locked" /
        # "privilege locked" —— 说明多数号还没解锁，默认开只会刷一屏
        # 无意义的拒绝日志。等用户确认自己的号够等级、愿意开，再点。
        self.tasks.setdefault('自动挂机升级', False)      # SetAutoFarmingRequest{#1:isOn}
        self.tasks.setdefault('挂机奖励', True)          # AfkInfo/DrawAfk/UpgradeAfk
        self.tasks.setdefault('主线建造', True)          # 只建当前主线要求的目标
        self.tasks.setdefault('建筑自动工作', False)      # SetBuildingAutoWorkRequest
        self.tasks.setdefault('竞技场扫荡', False)        # ArenaSweepRequest（空载荷）
        self.tasks.setdefault('漂流货船', False)          # 自动领取到港奖励
        self.tasks.setdefault('联盟互助', False)          # GuildAidList/Help
        self.tasks.setdefault('月卡领取', False)          # MonthCardDailyRewardRequest
        self.tasks.setdefault('赛季卡领取', False)        # SeasonCardGotDailyRequest
        self.tasks.setdefault('试炼副本', False)          # TrialRaid*（Lv.14）
        self.tasks.setdefault('积分赛', False)            # League*（Lv.25）
        self.tasks.setdefault('远征副本', False)          # Expedition*（Lv.30）
        # ---- 每日特惠 / 贸易 / 藏品 / 徽章 ----
        # 不花资源、纯领取或只改装备状态的默认开；烧碎片/烧材料/可能亏钱的默认关。
        self.tasks.setdefault('每日赠礼', True)         # GotFreeDailyPackRequest
        self.tasks.setdefault('闯关达标', True)         # PassStageGotRewardRequest
        self.tasks.setdefault('限购日礼包', True)       # LimitedShopGotFreeRequest type=1
        self.tasks.setdefault('限购周礼包', True)       # LimitedShopGotFreeRequest type=2
        self.tasks.setdefault('徽章穿戴', True)         # PutOnBadgeRequest
        # 自动穿戴装备：给上阵英雄补/换"数值最高"的武器/防具/饰品。
        # 不烧资源（换下来的回背包），默认开。
        self.tasks.setdefault('装备穿戴', True)         # PutOn/EquipReplace
        # 世界资源地占领：只在主线当前这一步是「占领资源地」时动手，
        # 派待命舰队去打一块没被自己占、类型对得上的资源地。默认开。
        self.tasks.setdefault('世界占领', True)         # ChallengeResFieldRequest
        # 资源地常驻占领（对标竞品 world.resField）：不只在主线要求时动手。
        # 名下有空位就派待命舰队补一块，优先补占得最少的类型；名额满了
        # 就停手（不来回换地，避免舰队空跑）。默认开。
        self.tasks.setdefault('资源地占领', True)
        self.tasks.setdefault('世界海盗', True)         # ChallengePirateRequest（主线 #109/#119）
        self.tasks.setdefault('贸易交货', True)        # 海商王跑商，推进主线 #73
        # 藏品材料/碎片也只服务于藏品本身，默认开。
        self.tasks.setdefault('藏品升级', True)         # 消耗藏品材料
        self.tasks.setdefault('藏品升星', True)         # 消耗藏品碎片
        # ---- VIP 免费礼包 / 日常任务 / 成长任务（纯领取，不烧资源）----
        self.tasks.setdefault('VIP免费礼包', True)      # GotVipDailyRewardRequest
        self.tasks.setdefault('日常任务奖励', True)     # DrawDailyTaskRewardRequest
        self.tasks.setdefault('成长任务奖励', True)     # GotBranchTaskRewardRequest
        # 任务·漫剧：阅读/看视频领奖（ComicDrama*）。纯领取，不烧资源，默认开。
        self.tasks.setdefault('漫剧', True)           # ComicDramaRead/GotReward
        # ---- 海兽（宠物培育室）----
        # 培育：把海兽放进宠物培育室孵化，成熟后领取（PetBreed/GetMaturePet）。
        # 投喂：PetFeedRequest，日常喂养提升成长。
        # 这两个不烧关键资源，默认开；升星/升级会消耗材料/碎片，默认关。
        self.tasks.setdefault('海兽培育', True)        # PetBreed/GetMaturePet
        self.tasks.setdefault('海兽投喂', True)        # PetFeedRequest
        self.tasks.setdefault('海兽升星', False)       # PetStarUpRequest ⚠ 消耗材料
        self.tasks.setdefault('海兽升级', False)       # PetLevelUpRequest ⚠ 消耗碎片
        # 联盟情报（主线 #128）的 6 个事件类型开关，对齐竞品 radar 配置。
        # ★ 必须放在下面「回读已存任务」**之前** —— 否则 _saved_known 快照
        #   里没有这些键，`_saved_known != self.tasks` 不成立，新开关永远
        #   不会落盘（27 个账号实测 0/27 命中）。
        for _rk, (_rn, _rc, _rd) in RADAR_KINDS.items():
            self.tasks.setdefault(_radar_task_name(_rk), _rd)
        # 任务开关属于账号配置，不能只活在内存里。旧版本这里没有回读，
        # 服务一重启就恢复默认，试炼副本等开关会静默关掉；用户看到的就是
        # 经验不再产出、英雄停止升级。只接收已知任务名，避免脏 JSON 注入。
        _saved_tasks = rec.get('tasks')
        if isinstance(_saved_tasks, dict):
            for _task_name, _task_on in _saved_tasks.items():
                if _task_name in self.tasks:
                    self.tasks[_task_name] = bool(_task_on)
        # 默认值迁移：老账号里存的是旧默认（联盟科技/藏品默认关），光改
        # setdefault 不会生效。按版本号补一次；用户在面板上改过开关的不会
        # 被覆盖，因为 persist_account_task 会把 tasksVersion 抬到当前值。
        if int(rec.get('tasksVersion') or 0) < TASKS_VERSION:
            for _flip in (TASK_DEFAULTS_V2_ON + TASK_DEFAULTS_V3_ON
                          + TASK_DEFAULTS_V4_ON):
                self.tasks[_flip] = True
        # 老账号可能没有 tasks，或是旧版本只存了部分开关。首次构造时补齐
        # 一份完整默认配置并落盘，后续掉线/重连/服务重启都按这一份恢复。
        try:
            _saved_known = ({k: bool(v) for k, v in _saved_tasks.items()
                             if k in self.tasks}
                            if isinstance(_saved_tasks, dict) else {})
            if _saved_known != self.tasks:
                ok, _saved = persist_account_tasks(self.uid, self.tasks)
                if not ok:
                    print('[TASK] 账号不存在，无法初始化配置 uid=%s' % self.uid,
                          flush=True)
        except Exception as e:
            print('[TASK] 初始化任务配置失败 uid=%s: %s' % (self.uid, e),
                  flush=True)
        # ---- 世界资源地（主线 #114/#115/#116）----
        # MyFleetsResponse / SCFleet / SCMyFleetUpdate 解出的自己的舰队，
        # buildingId -> 快照。WorldFleet.state 线上实测：1=在家待命，
        # 2=移动中，5=驻守/采集。只有 state==1 且耐久>0 的才派得出去。
        self.my_fleets = {}
        # MyResFieldsResponse / SCResFieldInfo 解出的已占资源地：
        # grid -> {'cityId','type'}
        self.my_res_fields = {}
        self.res_field_max = 0          # 最多能占几块资源地
        self.world_occupy_last = 0      # 发占领请求的节流
        self.world_occupy_deny = 0      # 被拒/占满后的冷却
        self.world_occupy_note = ''     # 最近一次结果，写进任务日志
        self.world_occupy_grid = 0      # 正在打的格子
        self.world_occupy_bad = {}      # 打不下来的格子 -> 解禁时间戳
        self.world_occupy_tries = {}    # 每格连续尝试次数（3 次后拉黑）
        # ---- 世界海盗（主线 #109/#119「累计击败野怪」）----
        # AllPirateResponse 解出的海盗列表；打一只少一只。
        self.my_pirates = []
        self.pirate_pull_last = 0   # 拉海盗列表的节流
        self.pirate_last = 0        # 发挑战请求的节流
        self.pirate_deny = 0        # 被拒/打不动后的冷却
        self.pirate_note = ''       # 最近一次结果，写进任务日志
        self.pirate_bad = {}        # 打不赢的海盗 uid -> 解禁时间戳
        self.pirate_pending_uid = 0  # 正在打的海盗 uid（0=空闲）
        # 击杀记录：type -> maxKilledLevel（服务端 PirateKillRecordResponse /
        # SCPirateKillRecordUpdate）。只能打 maxKilledLevel+1 那一级。
        self.pirate_records = {}
        self.pirate_record_pull_last = 0  # 拉击杀记录的节流
        self.pirate_pending_type = 0      # 正在打的海盗类型（0=空闲）
        self.pirate_pending_level = 0     # 正在打的海盗等级（0=空闲）
        # ---- 联盟情报（主线 #128「完成5件联盟情报」）----
        # RadarInfoResponse 解出的雷达快照：level/exp/storedNum/events/
        # fixedEvent/nextRefreshTime。
        self.radar_info = {}
        self.radar_info_at = 0      # 上次收到雷达快照的时间
        self.radar_pull_last = 0    # 拉雷达快照的节流
        self.radar_send_last = 0    # 派舰队执行情报事件的节流
        self.radar_claim_last = 0   # 领情报奖励的节流
        self.radar_deny = 0         # 被拒/没汽油后的冷却
        self.radar_note = ''        # 最近一次结果，写进任务日志
        # 已派出去执行事件的情报 uid -> 发车时间戳（含固定事件用 1 占位）。
        # 服务端推 START/FINISHED 或超时后会清掉，避免重复派兵。
        self.radar_track = {}
        self.radar_bad = {}         # 派不动的事件 uid -> 解禁时间戳
        # 战斗类事件要求的**最低舰队战力**（面板可调，0 = 不限）。
        # 事件包本身不带敌军战力，所以这里只能给一条绝对下限当保险绳。
        self.radar_min_power = int(rec.get('radarMinPower') or 0)
        # 失败学习：eventId -> 下次要求的舰队战力下限。
        self.radar_floor = {}
        # 已派出事件 uid -> (发车时间戳, 战力)。服务端把事件推回「待派兵」
        # 就说明这一趟没打成，据此把该 eventId 的门槛抬上去。
        self.radar_sent_power = {}
        self.radar_claim_sig = ''    # 上次待领奖的 uid 集合签名
        self.radar_claim_tries = 0   # 同一批奖连续领了几次
        self.arena_rank = 290
        # ---- 闯关状态 ----
        # 关卡进度**不在** PassStageStateResponse 里。那份协议实测是战令
        # （PassStageStateResponse 的 #1 是 `id`，即战令 id，不是关卡号），
        # 真正的进度是随角色信息下发的 mainlineStage（PlayerInfo #9）。
        # mainlineStage 是“当前要挑战的关卡”，不是“已通关数量”：
        # 客户端 ChallengeStageRequest 直接发这个值，胜利后才本地 +1。
        #
        # 线上踩过的坑：老代码发 PassStageStateRequest{#1:1} 再读回包
        # 第 2 个字段当关卡号，条件写的是 `if vals.get(1) == 0:` —— 请求里
        # #1 明明是 1，所以这个 if 永远不成立，self.stage 永远是 0，
        # 于是 `st = self.stage or 1` 一直回落到第 1 关，无脑重打 203 次。
        self.stage = 0            # 当前可挑战关卡（来自 player['当前关卡']）
        self.stage_try = 0        # 本次要挑战的关卡 = stage
        self.stage_deny = 0       # 战败后的冷却截止时间戳（暂停闯关，等战力涨）
        self.stage_fail_pow = 0   # 上次战败时的战力，用来判断"战力是否涨了"
        self.stage_log = []       # 最近挑战记录（面板"最近·挑战第 N 关"用）
        self.stage_state = ''     # '', 'trying', 'failed', 'ok'
        self.stage_tries = 0      # 累计发起挑战次数（面板显示）
        self.stage_fails = 0      # 累计挑战失败次数（面板显示）
        self.stage_reason = ''    # 最近一次失败原因（面板显示）
        self.stage_note = ''      # 一句话状态说明，直接给面板显示
        self.battlepass = None    # 战令状态（PassStageStateResponse，非闯关进度）
        self.main_task = None     # 当前主线任务 {taskId, progress, rewardClaimed}
        self.main_task_deny = 0   # 未完成时被服务端拒绝后的重试冷却
        self.main_recruit_last = 0  # 主线 #28 招募英雄的请求节流
        self.main_recruit_deny = 0  # 服务端明确拒绝招募后的冷却
        # 挂机状态与主线建造的限频。挂机奖励默认开，但只在 Lv.1 之后、
        # 当前主线明确要求某个建筑时才发写请求，避免新号刷无意义协议。
        self.afk_info = {}
        self.afk_reward_done_finish = 0
        self.afk_note = 0
        self.afk_deny = 0
        self.main_build_deny = {}
        # 最近一次主线目标建筑被服务端硬拒的原因 (buildingId, 文案, 时点)。
        self.main_build_last_reason = None
        self.main_task_refresh_pending = 0
        self.main_task_refresh_last = 0
        # 最近一次因为"机器人没有对应协议"而提示过的主线 taskId（去重，别刷屏）
        # 主线卡住的“一句话原因”（材料满仓等），拼进面板主线那一行显示。
        self.main_task_stall = ''
