            #   PirateKillRecordResponse { #1 repeated PirateKillRecord }
            #   SCPirateKillRecordUpdate { #1 record:PirateKillRecord }
            # 击杀记录决定“每一型海盗该打几级”：只能打 maxKilledLevel+1。
            if t == 'PirateKillRecordResponse':
                _rec = _ex_pirate_kill_records(info['payload'])
                if _rec:
                    with self.lock:
                        _cur = dict(
                            getattr(self, 'pirate_records', {}) or {})
                        for _ty, _lv in _rec.items():
                            # 记录只会涨，别被迟到的旧包打回去。
                            if int(_lv) >= int(_cur.get(_ty, -1)):
                                _cur[int(_ty)] = int(_lv)
                        self.pirate_records = _cur
                    self.note_task(
                        '世界海盗',
                        '击杀记录：%s' % '、'.join(
                            '%d 型最高 %d 级' % (_ty, _lv)
                            for _ty, _lv in sorted(_rec.items())),
                        level='debug')
            if t == 'SCPirateKillRecordUpdate':
                _rec = _ex_pirate_kill_record(info['payload'])
                if _rec:
                    with self.lock:
                        _cur = dict(
                            getattr(self, 'pirate_records', {}) or {})
                        for _ty, _lv in _rec.items():
                            if int(_lv) >= int(_cur.get(_ty, -1)):
                                _cur[int(_ty)] = int(_lv)
                        self.pirate_records = _cur
                    self.note_task(
                        '世界海盗',
                        '击杀记录更新：%s' % '、'.join(
                            '%d 型最高 %d 级' % (_ty, _lv)
                            for _ty, _lv in sorted(_rec.items())),
                        level='debug')
            if t == 'AllPirateResponse':
                _ps = _ex_pirates(info['payload'])
                with self.lock:
                    self.my_pirates = _ps
                    # 列表里已经没有的海盗，把冷却也清掉。
                    _live = set(int(p.get('uid') or 0) for p in _ps)
                    _bad = dict(getattr(self, 'pirate_bad', {}) or {})
                    for _u in list(_bad):
                        if _u not in _live:
                            _bad.pop(_u, None)
                    self.pirate_bad = _bad
                _lvl = [int(p.get('level') or 0) for p in _ps]
                self.note_task(
                    '世界海盗',
                    '海盗列表 %d 只%s' % (
                        len(_ps),
                        ('（最低 %d 级）' % min(_lvl)) if _lvl else ''),
                    level='debug')
            #   SCPirateCampaignEnd { #1 uid:int32; #2 isWin:bool }
            if t == 'SCPirateCampaignEnd':
                _pu = 0
                _pwin = False
                for _fn, _v in _pb_fields(info['payload']):
                    if _fn == 1 and isinstance(_v, int):
                        _pu = _v
                    elif _fn == 2 and isinstance(_v, int):
                        _pwin = bool(_v)
                with self.lock:
                    if _pu:
                        _bad = dict(getattr(self, 'pirate_bad', {}) or {})
                        if _pwin:
                            _bad.pop(_pu, None)
                            self.my_pirates = [
                                p for p in (getattr(self, 'my_pirates', [])
                                            or [])
                                if int(p.get('uid') or 0) != _pu]
                            # 赢了就把这一型的最高击杀抬到刚打过的这一级，
                            # 下一轮自动去打 +1 级（等 SCPirateKillRecordUpdate
                            # 到了也会以它为准，两者一致）。
                            _pty = int(getattr(
                                self, 'pirate_pending_type', 0) or 0)
                            _plv = int(getattr(
                                self, 'pirate_pending_level', 0) or 0)
                            if _pty and _plv:
                                _recs = dict(getattr(
                                    self, 'pirate_records', {}) or {})
                                if _plv > int(_recs.get(_pty, 0) or 0):
                                    _recs[_pty] = _plv
                                    self.pirate_records = _recs
                        else:
                            _bad[_pu] = time.time() + 3600
                        self.pirate_bad = _bad
                    self.pirate_pending_uid = 0
                    self.pirate_pending_type = 0
                    self.pirate_pending_level = 0
                # 打完就立刻重拉一次列表，拿到最新剩余海盗。
                self.pirate_pull_last = 0
                self.note_task(
                    '世界海盗',
                    '海盗 uid=%s %s' % (
                        _pu, '击败' if _pwin else '没打过（拉黑1小时）'),
                    level='ok' if _pwin else 'debug')
            # ---- 联盟情报（主线 #128「完成5件联盟情报」）----
            #   RadarInfoResponse { #1 radarInfo:RadarInfo }
            #   SCRadarUpdate     { #1 info:RadarInfo }
            if t in ('RadarInfoResponse', 'SCRadarUpdate'):
                _ri = _ex_radar_info(info['payload'])
                if _ri:
                    with self.lock:
                        self.radar_info = _ri
                        self.radar_info_at = time.time()
                        # 事件已经从待派兵变成进行中/完成的，把本地
                        # “已派兵”标记清掉，避免一直占着不发下一件。
                        _trk = dict(getattr(self, 'radar_track', {}) or {})
                        _live = set()
                        for _e in list(_ri.get('events') or []):
                            if int(_e.get('state') or 0) == 1:
                                _live.add(int(_e.get('uid') or 0))
                        _fx0 = _ri.get('fixedEvent')
                        if _fx0 and int(_fx0.get('state') or 0) == 1:
                            _live.add(RADAR_FIXED_UID)
                        for _u in list(_trk):
                            if _u not in _live:
                                _trk.pop(_u, None)
                        self.radar_track = _trk
                    _evs = list(_ri.get('events') or [])
                    _fx = _ri.get('fixedEvent')
                    _n_init = len([e for e in _evs
                                   if int(e.get('state') or 0) == 1])
                    self.note_task(
                        '联盟情报',
                        '情报等级 %s，事件 %d 件（待派兵 %d）%s'
                        % (_ri.get('level'), len(_evs), _n_init,
                           ('，固定事件 #%s' % _fx.get('eventId'))
                           if _fx else ''),
                        level='debug')
            #   SCRadarEventState { #1 uid:int64; #2 state:int32; #3 startTime }
            if t == 'SCRadarEventState':
                _ru = _rs = 0
                for _fn, _v in _pb_fields(info['payload']):
                    if _fn == 1 and isinstance(_v, int):
                        _ru = _v
                    elif _fn == 2 and isinstance(_v, int):
                        _rs = _v
                _key = _ru or RADAR_FIXED_UID
                _now2 = time.time()
                _learn_eid = 0
                _learn_val = 0
                with self.lock:
                    _ri = dict(getattr(self, 'radar_info', {}) or {})
                    for _e in list(_ri.get('events') or []):
                        if int(_e.get('uid') or 0) == _ru:
                            _e['state'] = _rs
                    _fx = _ri.get('fixedEvent')
                    if _fx and _key == RADAR_FIXED_UID:
                        _fx['state'] = _rs
                    self.radar_info = _ri
                    # 服务端把事件推到进行中/完成：本地派兵标记可以清了。
                    if _rs in (3, 4):
                        _trk = dict(getattr(self, 'radar_track', {}) or {})
                        _trk.pop(_key, None)
                        self.radar_track = _trk
                    # 派兵记录：打成了就删，超时的也顺手清掉别越攒越多。
                    _sp = dict(getattr(self, 'radar_sent_power', {}) or {})
